    noahmp%water_flux_PrecipConvTotRefHeight(noahmp_c) = 0.10 * noahmp%water_flux_PrecipTotRefHeight(noahmp_c)
    noahmp%water_flux_PrecipLargeSclRefHeight(noahmp_c) = 0.90 * noahmp%water_flux_PrecipTotRefHeight(noahmp_c)
