! Source: physics_noahmp/src/GeneralInitMod.F90
module lean_generalinitmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine GeneralInit(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: LoopInd
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 4
      if ( LoopInd == noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1 ) then
        noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c) = - noahmp%config_domain_DepthSnowSoilLayer(LoopInd, noahmp_c)
      else
        noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c) = noahmp%config_domain_DepthSnowSoilLayer(LoopInd-1, noahmp_c) - noahmp%config_domain_DepthSnowSoilLayer(LoopInd, noahmp_c)
      endif
    enddo
    noahmp%energy_state_TemperatureRootZone(noahmp_c) = 0.0
    do LoopInd = 1, noahmp%water_param_NumSoilLayerRoot(noahmp_c)
      noahmp%energy_state_TemperatureRootZone(noahmp_c) = noahmp%energy_state_TemperatureRootZone(noahmp_c) + noahmp%energy_state_TemperatureSoilSnow(LoopInd, noahmp_c) * noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c) / (-noahmp%config_domain_DepthSoilLayer(noahmp%water_param_NumSoilLayerRoot(noahmp_c), noahmp_c))
    enddo
  end subroutine GeneralInit
end module lean_generalinitmod

! Source: physics_noahmp/src/PhenologyMainMod.F90
module lean_phenologymainmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine PhenologyMain (noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: IntpMonth1,IntpMonth2
    real(kind=kind_noahmp) :: ThicknessCanBury
    real(kind=kind_noahmp) :: SnowDepthVegBury
    real(kind=kind_noahmp) :: DayCurrent
    real(kind=kind_noahmp) :: IntpWgt1,IntpWgt2
    real(kind=kind_noahmp) :: MonthCurrent
    if ( noahmp%config_domain_CropType(noahmp_c) == 0 ) then
      if ( noahmp%config_domain_Latitude(noahmp_c) >= 0.0 ) then
        DayCurrent = noahmp%config_domain_DayJulianInYear(noahmp_c)
      else
        DayCurrent = mod(noahmp%config_domain_DayJulianInYear(noahmp_c)+(0.5*noahmp%config_domain_NumDayInYear(noahmp_c)), real(noahmp%config_domain_NumDayInYear(noahmp_c)))
      endif
      MonthCurrent = 12.0 * DayCurrent / real(noahmp%config_domain_NumDayInYear(noahmp_c))
      IntpMonth1 = MonthCurrent + 0.5
      IntpMonth2 = IntpMonth1 + 1
      IntpWgt1 = (IntpMonth1 + 0.5) - MonthCurrent
      IntpWgt2 = 1.0 - IntpWgt1
      if ( IntpMonth1 < 1 ) IntpMonth1 = 12
      if ( IntpMonth2 > 12 ) IntpMonth2 = 1
      noahmp%energy_state_LeafAreaIndex(noahmp_c) = IntpWgt1 * noahmp%energy_param_LeafAreaIndexMon(IntpMonth1, noahmp_c) + IntpWgt2 * noahmp%energy_param_LeafAreaIndexMon(IntpMonth2, noahmp_c)
      noahmp%energy_state_StemAreaIndex(noahmp_c) = IntpWgt1 * noahmp%energy_param_StemAreaIndexMon(IntpMonth1, noahmp_c) + IntpWgt2 * noahmp%energy_param_StemAreaIndexMon(IntpMonth2, noahmp_c)
      if ( noahmp%energy_state_StemAreaIndex(noahmp_c) < 0.05 ) noahmp%energy_state_StemAreaIndex(noahmp_c) = 0.0
      if ( (noahmp%energy_state_LeafAreaIndex(noahmp_c) < 0.05) .or. (noahmp%energy_state_StemAreaIndex(noahmp_c) == 0.0) ) noahmp%energy_state_LeafAreaIndex(noahmp_c) = 0.0
      if ( (noahmp%config_domain_VegType(noahmp_c) == noahmp%config_domain_IndexWaterPoint(noahmp_c)) .or. (noahmp%config_domain_VegType(noahmp_c) == noahmp%config_domain_IndexBarrenPoint(noahmp_c)) .or. (noahmp%config_domain_VegType(noahmp_c) == noahmp%config_domain_IndexIcePoint(noahmp_c) ) .or. (noahmp%config_domain_FlagUrban(noahmp_c) .eqv. .true.) ) then
        noahmp%energy_state_LeafAreaIndex(noahmp_c) = 0.0
        noahmp%energy_state_StemAreaIndex(noahmp_c) = 0.0
      endif
    endif
    ThicknessCanBury = min(max(noahmp%water_state_SnowDepth(noahmp_c)-noahmp%energy_param_HeightCanopyBot(noahmp_c),0.0), (noahmp%energy_param_HeightCanopyTop(noahmp_c)-noahmp%energy_param_HeightCanopyBot(noahmp_c)))
    noahmp%energy_state_CanopyFracSnowBury(noahmp_c) = ThicknessCanBury / max(1.0e-06, (noahmp%energy_param_HeightCanopyTop(noahmp_c)-noahmp%energy_param_HeightCanopyBot(noahmp_c)))
    if ( (noahmp%energy_param_HeightCanopyTop(noahmp_c) > 0.0) .and. (noahmp%energy_param_HeightCanopyTop(noahmp_c) <= 1.0) ) then
      SnowDepthVegBury = noahmp%energy_param_HeightCanopyTop(noahmp_c) * exp(-noahmp%water_state_SnowDepth(noahmp_c) / 0.2)
      noahmp%energy_state_CanopyFracSnowBury(noahmp_c) = min(noahmp%water_state_SnowDepth(noahmp_c), SnowDepthVegBury) / SnowDepthVegBury
    endif
    noahmp%energy_state_LeafAreaIndEff(noahmp_c) = noahmp%energy_state_LeafAreaIndex(noahmp_c) * (1.0 - noahmp%energy_state_CanopyFracSnowBury(noahmp_c))
    noahmp%energy_state_StemAreaIndEff(noahmp_c) = noahmp%energy_state_StemAreaIndex(noahmp_c) * (1.0 - noahmp%energy_state_CanopyFracSnowBury(noahmp_c))
    if ( (noahmp%energy_state_StemAreaIndEff(noahmp_c) < 0.05) .and. (noahmp%config_domain_CropType(noahmp_c) == 0) ) noahmp%energy_state_StemAreaIndEff(noahmp_c) = 0.0
    if ( ((noahmp%energy_state_LeafAreaIndEff(noahmp_c) < 0.05) .or. (noahmp%energy_state_StemAreaIndEff(noahmp_c) == 0.0)) .and. (noahmp%config_domain_CropType(noahmp_c) == 0) ) noahmp%energy_state_LeafAreaIndEff(noahmp_c) = 0.0
    if ( ((noahmp%energy_state_TemperatureCanopy(noahmp_c) > noahmp%biochem_param_TemperatureMinPhotosyn(noahmp_c)) .and. (noahmp%config_domain_CropType(noahmp_c) == 0)) .or. ((noahmp%biochem_state_PlantGrowStage(noahmp_c) > 2) .and. (noahmp%biochem_state_PlantGrowStage(noahmp_c) < 7) .and. (noahmp%config_domain_CropType(noahmp_c) > 0))) then
      noahmp%biochem_state_IndexGrowSeason(noahmp_c) = 1.0
    else
      noahmp%biochem_state_IndexGrowSeason(noahmp_c) = 0.0
    endif
    noahmp%energy_state_VegFrac(noahmp_c) = noahmp%energy_param_VegFracAnnMax(noahmp_c)
    if ( noahmp%energy_state_VegFrac(noahmp_c) <= 0.05 ) noahmp%energy_state_VegFrac(noahmp_c) = 0.05
    if ( (noahmp%config_domain_FlagUrban(noahmp_c) .eqv. .true.) .or. (noahmp%config_domain_VegType(noahmp_c) == noahmp%config_domain_IndexBarrenPoint(noahmp_c)) ) noahmp%energy_state_VegFrac(noahmp_c) = 0.0
    if ( (noahmp%energy_state_LeafAreaIndEff(noahmp_c)+noahmp%energy_state_StemAreaIndEff(noahmp_c)) == 0.0 ) noahmp%energy_state_VegFrac(noahmp_c) = 0.0
    noahmp%config_domain_FlagDynamicCrop(noahmp_c) = .false.
    noahmp%config_domain_FlagDynamicVeg(noahmp_c) = .false.
  end subroutine PhenologyMain
end module lean_phenologymainmod

! Source: physics_noahmp/src/IrrigationTriggerMod.F90
module lean_irrigationtriggermod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine IrrigationTrigger(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    logical :: FlagIrri
    integer :: LoopInd
    real(kind=kind_noahmp) :: SoilMoistAvail
    real(kind=kind_noahmp) :: SoilMoistAvailMax
    real(kind=kind_noahmp) :: IrrigationWater
    FlagIrri = .true.
    FlagIrri = .false.
    if ( FlagIrri .eqv. .true. ) then
      SoilMoistAvail = 0.0
      SoilMoistAvailMax = 0.0
      SoilMoistAvail = (noahmp%water_state_SoilLiqWater(1, noahmp_c) - noahmp%water_param_SoilMoistureWilt(1, noahmp_c)) * (-1.0) * noahmp%config_domain_DepthSoilLayer(1, noahmp_c)
      SoilMoistAvailMax = (noahmp%water_param_SoilMoistureFieldCap(1, noahmp_c) - noahmp%water_param_SoilMoistureWilt(1, noahmp_c)) * (-1.0) * noahmp%config_domain_DepthSoilLayer(1, noahmp_c)
      do LoopInd = 2, noahmp%water_param_NumSoilLayerRoot(noahmp_c)
        SoilMoistAvail = SoilMoistAvail + (noahmp%water_state_SoilLiqWater(LoopInd, noahmp_c) - noahmp%water_param_SoilMoistureWilt(LoopInd, noahmp_c)) * (noahmp%config_domain_DepthSoilLayer(LoopInd-1, noahmp_c) - noahmp%config_domain_DepthSoilLayer(LoopInd, noahmp_c))
        SoilMoistAvailMax = SoilMoistAvailMax + (noahmp%water_param_SoilMoistureFieldCap(LoopInd, noahmp_c) - noahmp%water_param_SoilMoistureWilt(LoopInd, noahmp_c)) * (noahmp%config_domain_DepthSoilLayer(LoopInd-1, noahmp_c) - noahmp%config_domain_DepthSoilLayer(LoopInd, noahmp_c))
      enddo
      if ( (SoilMoistAvail/SoilMoistAvailMax) <= noahmp%water_param_SoilWatDeficitAllow(noahmp_c) ) then
        IrrigationWater = (SoilMoistAvailMax - SoilMoistAvail) * noahmp%water_state_IrrigationFracGrid(noahmp_c) * noahmp%energy_state_VegFrac(noahmp_c)
        if ( (noahmp%water_state_IrrigationAmtSprinkler(noahmp_c) == 0.0) .and. (noahmp%water_state_IrrigationFracSprinkler(noahmp_c) > 0.0) .and. (0 == 0) ) then
          noahmp%water_state_IrrigationAmtSprinkler(noahmp_c) = noahmp%water_state_IrrigationFracSprinkler(noahmp_c) * IrrigationWater
          noahmp%water_state_IrrigationCntSprinkler(noahmp_c) = noahmp%water_state_IrrigationCntSprinkler(noahmp_c) + 1
        endif
        if ( (noahmp%water_state_IrrigationAmtMicro(noahmp_c) == 0.0) .and. (noahmp%water_state_IrrigationFracMicro(noahmp_c) > 0.0) .and. (0 == 0) ) then
          noahmp%water_state_IrrigationAmtMicro(noahmp_c) = noahmp%water_state_IrrigationFracMicro(noahmp_c) * IrrigationWater
          noahmp%water_state_IrrigationCntMicro(noahmp_c) = noahmp%water_state_IrrigationCntMicro(noahmp_c) + 1
        endif
        if ( (noahmp%water_state_IrrigationAmtFlood(noahmp_c) == 0.0) .and. (noahmp%water_state_IrrigationFracFlood(noahmp_c) > 0.0) .and. (0 == 0) ) then
          noahmp%water_state_IrrigationAmtFlood(noahmp_c) = noahmp%water_state_IrrigationFracFlood(noahmp_c) * IrrigationWater * (1.0/(1.0 - noahmp%water_param_IrriFloodLossFrac(noahmp_c)))
          noahmp%water_state_IrrigationCntFlood(noahmp_c) = noahmp%water_state_IrrigationCntFlood(noahmp_c) + 1
        endif
      else
        IrrigationWater = 0.0
        noahmp%water_state_IrrigationAmtSprinkler(noahmp_c) = 0.0
        noahmp%water_state_IrrigationAmtMicro(noahmp_c) = 0.0
        noahmp%water_state_IrrigationAmtFlood(noahmp_c) = 0.0
      endif
    endif
  end subroutine IrrigationTrigger
end module lean_irrigationtriggermod

! Source: physics_noahmp/src/IrrigationPrepareMod.F90
module lean_irrigationpreparemod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_irrigationtriggermod, only : IrrigationTrigger
  implicit none
  contains
  subroutine IrrigationPrepare(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    noahmp%config_domain_FlagCropland(noahmp_c) = .false.
    if ( (noahmp%config_domain_VegType(noahmp_c) == 12) .or. (noahmp%config_domain_VegType(noahmp_c) == 14) ) noahmp%config_domain_FlagCropland(noahmp_c) = .true.
    if ( (0 == 0) .and. (noahmp%water_state_IrrigationFracSprinkler(noahmp_c) == 0.0) .and. (noahmp%water_state_IrrigationFracMicro(noahmp_c) == 0.0) .and. (noahmp%water_state_IrrigationFracFlood(noahmp_c) == 0.0) .and. (noahmp%water_state_IrrigationFracGrid(noahmp_c) >= noahmp%water_param_IrriFracThreshold(noahmp_c)) ) then
      noahmp%water_state_IrrigationFracSprinkler(noahmp_c) = 1.0
    endif
    if ( noahmp%config_domain_FlagSoilProcess(noahmp_c) .eqv. .true. ) then
      if ( (noahmp%config_domain_FlagCropland(noahmp_c) .eqv. .true.) .and. (noahmp%water_state_IrrigationFracGrid(noahmp_c) >= noahmp%water_param_IrriFracThreshold(noahmp_c)) .and. (noahmp%water_flux_RainfallRefHeight(noahmp_c) < (noahmp%water_param_IrriStopPrecipThr(noahmp_c)/3600.0)) .and. ((noahmp%water_state_IrrigationAmtSprinkler(noahmp_c)+noahmp%water_state_IrrigationAmtMicro(noahmp_c)+noahmp%water_state_IrrigationAmtFlood(noahmp_c)) == 0.0) ) then
        call IrrigationTrigger(noahmp, noahmp_c)
      endif
      if ( (noahmp%water_flux_RainfallRefHeight(noahmp_c) >= (noahmp%water_param_IrriStopPrecipThr(noahmp_c)/3600.0)) .or. (noahmp%water_state_IrrigationFracGrid(noahmp_c) < noahmp%water_param_IrriFracThreshold(noahmp_c)) ) then
        noahmp%water_state_IrrigationAmtSprinkler(noahmp_c) = 0.0
        noahmp%water_state_IrrigationAmtMicro(noahmp_c) = 0.0
        noahmp%water_state_IrrigationAmtFlood(noahmp_c) = 0.0
      endif
    endif
  end subroutine IrrigationPrepare
end module lean_irrigationpreparemod

! Source: physics_noahmp/utility/CheckNanMod.F90
module lean_checknanmod
  use Machine, only : kind_noahmp
  implicit none
  contains
  subroutine CheckRealNaN(NumIn, OutVal)
 !$acc routine seq
    real(kind=kind_noahmp), intent(in) :: NumIn
    logical , intent(out) :: OutVal
    OutVal = (NumIn /= NumIn)
  end subroutine CheckRealNaN
end module lean_checknanmod

! Source: physics_noahmp/src/SoilHydraulicPropertyMod.F90
module lean_soilhydraulicpropertymod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine SoilDiffusivityConductivityOpt1(noahmp, noahmp_c, SoilWatDiffusivity, SoilWatConductivity, SoilMoisture, &
    & SoilImpervFrac, IndLayer)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer , intent(in) :: IndLayer
    real(kind=kind_noahmp), intent(in) :: SoilMoisture
    real(kind=kind_noahmp), intent(in) :: SoilImpervFrac
    real(kind=kind_noahmp), intent(out) :: SoilWatConductivity
    real(kind=kind_noahmp), intent(out) :: SoilWatDiffusivity
    real(kind=kind_noahmp) :: SoilExpTmp
    real(kind=kind_noahmp) :: SoilPreFac
    SoilPreFac = max(0.01, SoilMoisture/noahmp%water_param_SoilMoistureSat(IndLayer, noahmp_c))
    SoilExpTmp = noahmp%water_param_SoilExpCoeffB(IndLayer, noahmp_c) + 2.0
    SoilWatDiffusivity = noahmp%water_param_SoilWatDiffusivitySat(IndLayer, noahmp_c) * SoilPreFac ** SoilExpTmp
    SoilWatDiffusivity = SoilWatDiffusivity * (1.0 - SoilImpervFrac)
    SoilExpTmp = 2.0 * noahmp%water_param_SoilExpCoeffB(IndLayer, noahmp_c) + 3.0
    SoilWatConductivity = noahmp%water_param_SoilWatConductivitySat(IndLayer, noahmp_c) * SoilPreFac ** SoilExpTmp
    SoilWatConductivity = SoilWatConductivity * (1.0 - SoilImpervFrac)
  end subroutine SoilDiffusivityConductivityOpt1
  subroutine SoilDiffusivityConductivityOpt2(noahmp, noahmp_c, SoilWatDiffusivity, SoilWatConductivity, SoilMoisture, &
    & SoilIce, IndLayer)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer , intent(in) :: IndLayer
    real(kind=kind_noahmp), intent(in) :: SoilMoisture
    real(kind=kind_noahmp), intent(in) :: SoilIce
    real(kind=kind_noahmp), intent(out) :: SoilWatConductivity
    real(kind=kind_noahmp), intent(out) :: SoilWatDiffusivity
    real(kind=kind_noahmp) :: SoilExpTmp
    real(kind=kind_noahmp) :: SoilPreFac1
    real(kind=kind_noahmp) :: SoilPreFac2
    real(kind=kind_noahmp) :: SoilIceWgt
    SoilPreFac1 = 0.05 / noahmp%water_param_SoilMoistureSat(IndLayer, noahmp_c)
    SoilPreFac2 = max(0.01, SoilMoisture/noahmp%water_param_SoilMoistureSat(IndLayer, noahmp_c))
    SoilPreFac1 = min(SoilPreFac1, SoilPreFac2)
    SoilExpTmp = noahmp%water_param_SoilExpCoeffB(IndLayer, noahmp_c) + 2.0
    SoilWatDiffusivity = noahmp%water_param_SoilWatDiffusivitySat(IndLayer, noahmp_c) * SoilPreFac2 ** SoilExpTmp
    if ( SoilIce > 0.0 ) then
      SoilIceWgt = 1.0 / (1.0 + (500.0 * SoilIce)**3.0)
      SoilWatDiffusivity = SoilIceWgt * SoilWatDiffusivity + (1.0-SoilIceWgt) * noahmp%water_param_SoilWatDiffusivitySat(IndLayer, noahmp_c) * SoilPreFac1**SoilExpTmp
    endif
    SoilExpTmp = 2.0 * noahmp%water_param_SoilExpCoeffB(IndLayer, noahmp_c) + 3.0
    SoilWatConductivity = noahmp%water_param_SoilWatConductivitySat(IndLayer, noahmp_c) * SoilPreFac2 ** SoilExpTmp
  end subroutine SoilDiffusivityConductivityOpt2
end module lean_soilhydraulicpropertymod

! Source: physics_noahmp/src/IrrigationInfilPhilipMod.F90
module lean_irrigationinfilphilipmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_soilhydraulicpropertymod, only : SoilDiffusivityConductivityOpt2
  implicit none
  contains
  subroutine IrrigationInfilPhilip(noahmp, noahmp_c, TimeStep, InfilRateSfc)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    real(kind=kind_noahmp), intent(in) :: TimeStep
    real(kind=kind_noahmp), intent(out) :: InfilRateSfc
    integer :: LoopInd
    integer :: IndSoilLayer
    real(kind=kind_noahmp) :: SoilSorptivity
    real(kind=kind_noahmp) :: SoilWatConductInit
    real(kind=kind_noahmp) :: SoilWatConductivity
    real(kind=kind_noahmp) :: SoilWatDiffusivity
    real(kind=kind_noahmp) :: SoilIceMaxTmp
    SoilWatConductivity = 0.0
    SoilWatDiffusivity = 0.0
    SoilIceMaxTmp = 0.0
    SoilSorptivity = 0.0
    SoilWatConductInit = 0.0
    do LoopInd = 1, 4
      if ( noahmp%water_state_SoilIce(LoopInd, noahmp_c) > SoilIceMaxTmp ) SoilIceMaxTmp = noahmp%water_state_SoilIce(LoopInd, noahmp_c)
    enddo
    IndSoilLayer = 1
    call SoilDiffusivityConductivityOpt2(noahmp, noahmp_c, SoilWatDiffusivity, SoilWatConductivity, &
      & noahmp%water_state_SoilLiqWater(IndSoilLayer, noahmp_c), SoilIceMaxTmp, IndSoilLayer)
    SoilSorptivity = sqrt(2.0 * max(0.0, &
      & (noahmp%water_param_SoilMoistureSat(IndSoilLayer, noahmp_c) - noahmp%water_state_SoilMoisture(IndSoilLayer, noahmp_c))) * (noahmp%water_param_SoilWatDiffusivitySat(IndSoilLayer, noahmp_c) - SoilWatDiffusivity))
    SoilWatConductInit = min(SoilWatConductivity, (2.0/3.0) * noahmp%water_param_SoilWatConductivitySat(IndSoilLayer, noahmp_c))
    SoilWatConductInit = max(SoilWatConductInit , (1.0/3.0) * noahmp%water_param_SoilWatConductivitySat(IndSoilLayer, noahmp_c))
    InfilRateSfc = 0.5 * SoilSorptivity * (TimeStep**(-0.5)) + SoilWatConductInit
    InfilRateSfc = max(0.0, InfilRateSfc)
  end subroutine IrrigationInfilPhilip
end module lean_irrigationinfilphilipmod

! Source: physics_noahmp/src/IrrigationSprinklerMod.F90
module lean_irrigationsprinklermod
  use Machine
  use lean_checknanmod
  use noahmp_state
  use lean_constantdefinemod
  use lean_irrigationinfilphilipmod, only : IrrigationInfilPhilip
  implicit none
  contains
  subroutine IrrigationSprinkler(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    logical :: FlagNan
    real(kind=kind_noahmp) :: InfilRateSfc
    real(kind=kind_noahmp) :: IrriRateTmp
    real(kind=kind_noahmp) :: WindSpdTot
    real(kind=kind_noahmp) :: IrriLossTmp
    real(kind=kind_noahmp) :: PressureVaporSat
    noahmp%water_state_SoilIce(:, noahmp_c) = max(0.0, noahmp%water_state_SoilMoisture(:, noahmp_c)-noahmp%water_state_SoilLiqWater(:, noahmp_c))
    call IrrigationInfilPhilip(noahmp, noahmp_c, noahmp%config_domain_MainTimeStep(noahmp_c), InfilRateSfc)
    IrriRateTmp = noahmp%water_param_IrriSprinklerRate(noahmp_c) * (1.0/1000.0) * noahmp%config_domain_MainTimeStep(noahmp_c) / 3600.0
    noahmp%water_flux_IrrigationRateSprinkler(noahmp_c) = min(InfilRateSfc*noahmp%config_domain_MainTimeStep(noahmp_c), noahmp%water_state_IrrigationAmtSprinkler(noahmp_c), IrriRateTmp)
    WindSpdTot = sqrt((noahmp%forcing_WindEastwardRefHeight(noahmp_c)**2.0) + (noahmp%forcing_WindNorthwardRefHeight(noahmp_c)**2.0))
    PressureVaporSat = 610.8 * exp((17.27*(noahmp%forcing_TemperatureAirRefHeight(noahmp_c)-273.15)) / (237.3+(noahmp%forcing_TemperatureAirRefHeight(noahmp_c)-273.15)))
    if ( noahmp%forcing_TemperatureAirRefHeight(noahmp_c) > 273.15 ) then
      IrriLossTmp = 4.375 * (exp(0.106*WindSpdTot)) * (((PressureVaporSat-noahmp%energy_state_PressureVaporRefHeight(noahmp_c))*0.01)**(-0.092)) * ((noahmp%forcing_TemperatureAirRefHeight(noahmp_c)-273.15)**(-0.102))
    else
      IrriLossTmp = 4.337 * (exp(0.077*WindSpdTot)) * (((PressureVaporSat-noahmp%energy_state_PressureVaporRefHeight(noahmp_c))*0.01)**(-0.098))
    endif
    call CheckRealNaN(IrriLossTmp, FlagNan)
    if ( FlagNan .eqv. .true. ) IrriLossTmp = 4.0
    if ( (IrriLossTmp > 100.0) .or. (IrriLossTmp < 0.0) ) IrriLossTmp = 4.0
    noahmp%water_flux_IrrigationRateSprinkler(noahmp_c) = noahmp%water_flux_IrrigationRateSprinkler(noahmp_c) * noahmp%water_state_IrrigationFracSprinkler(noahmp_c)
    if ( noahmp%water_flux_IrrigationRateSprinkler(noahmp_c) >= noahmp%water_state_IrrigationAmtSprinkler(noahmp_c) ) then
      noahmp%water_flux_IrrigationRateSprinkler(noahmp_c) = noahmp%water_state_IrrigationAmtSprinkler(noahmp_c)
      noahmp%water_state_IrrigationAmtSprinkler(noahmp_c) = 0.0
    else
      noahmp%water_state_IrrigationAmtSprinkler(noahmp_c) = noahmp%water_state_IrrigationAmtSprinkler(noahmp_c) - noahmp%water_flux_IrrigationRateSprinkler(noahmp_c)
    endif
    noahmp%water_flux_IrriEvapLossSprinkler(noahmp_c) = noahmp%water_flux_IrrigationRateSprinkler(noahmp_c) * IrriLossTmp * (1.0/100.0)
    noahmp%water_flux_IrrigationRateSprinkler(noahmp_c) = noahmp%water_flux_IrrigationRateSprinkler(noahmp_c) - noahmp%water_flux_IrriEvapLossSprinkler(noahmp_c)
    noahmp%water_flux_RainfallRefHeight(noahmp_c) = noahmp%water_flux_RainfallRefHeight(noahmp_c) + (noahmp%water_flux_IrrigationRateSprinkler(noahmp_c) * 1000.0 / noahmp%config_domain_MainTimeStep(noahmp_c))
    noahmp%energy_flux_HeatLatentIrriEvap(noahmp_c) = noahmp%water_flux_IrriEvapLossSprinkler(noahmp_c) * 1000.0 * ConstLatHeatEvap / noahmp%config_domain_MainTimeStep(noahmp_c)
    noahmp%water_flux_EvapIrriSprinkler(noahmp_c) = noahmp%water_flux_IrriEvapLossSprinkler(noahmp_c) * 1000.0 / noahmp%config_domain_MainTimeStep(noahmp_c)
  end subroutine IrrigationSprinkler
end module lean_irrigationsprinklermod

! Source: physics_noahmp/src/CanopyWaterInterceptMod.F90
module lean_canopywaterinterceptmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine CanopyWaterIntercept(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    real(kind=kind_noahmp) :: IceDripFacTemp
    real(kind=kind_noahmp) :: IceDripFacWind
    real(kind=kind_noahmp) :: CanopySnowDrip
    noahmp%water_flux_InterceptCanopyRain(noahmp_c) = 0.0
    noahmp%water_flux_DripCanopyRain(noahmp_c) = 0.0
    noahmp%water_flux_ThroughfallRain(noahmp_c) = 0.0
    noahmp%water_flux_InterceptCanopySnow(noahmp_c) = 0.0
    noahmp%water_flux_DripCanopySnow(noahmp_c) = 0.0
    noahmp%water_flux_ThroughfallSnow(noahmp_c) = 0.0
    noahmp%water_flux_RainfallGround(noahmp_c) = 0.0
    noahmp%water_flux_SnowfallGround(noahmp_c) = 0.0
    noahmp%water_flux_SnowDepthIncr(noahmp_c) = 0.0
    CanopySnowDrip = 0.0
    IceDripFacTemp = 0.0
    IceDripFacWind = 0.0
    noahmp%water_state_CanopyLiqWaterMax(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%water_param_CanopyLiqHoldCap(noahmp_c) * (noahmp%energy_state_LeafAreaIndEff(noahmp_c) + noahmp%energy_state_StemAreaIndEff(noahmp_c))
    if ( (noahmp%energy_state_LeafAreaIndEff(noahmp_c)+noahmp%energy_state_StemAreaIndEff(noahmp_c)) > 0.0 ) then
      noahmp%water_flux_InterceptCanopyRain(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%water_flux_RainfallRefHeight(noahmp_c) * noahmp%water_state_PrecipAreaFrac(noahmp_c)
      noahmp%water_flux_InterceptCanopyRain(noahmp_c) = min( noahmp%water_flux_InterceptCanopyRain(noahmp_c), &
        & (noahmp%water_state_CanopyLiqWaterMax(noahmp_c)-noahmp%water_state_CanopyLiqWater(noahmp_c))/noahmp%config_domain_MainTimeStep(noahmp_c) * (1.0-exp(-noahmp%water_flux_RainfallRefHeight(noahmp_c)*noahmp%config_domain_MainTimeStep(noahmp_c)/noahmp%water_state_CanopyLiqWaterMax(noahmp_c))) )
      noahmp%water_flux_InterceptCanopyRain(noahmp_c) = max( noahmp%water_flux_InterceptCanopyRain(noahmp_c), 0.0 )
      noahmp%water_flux_DripCanopyRain(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%water_flux_RainfallRefHeight(noahmp_c) - noahmp%water_flux_InterceptCanopyRain(noahmp_c)
      noahmp%water_flux_ThroughfallRain(noahmp_c) = (1.0 - noahmp%energy_state_VegFrac(noahmp_c)) * noahmp%water_flux_RainfallRefHeight(noahmp_c)
      noahmp%water_state_CanopyLiqWater(noahmp_c) = max( 0.0, noahmp%water_state_CanopyLiqWater(noahmp_c) + noahmp%water_flux_InterceptCanopyRain(noahmp_c)*noahmp%config_domain_MainTimeStep(noahmp_c) )
    else
      noahmp%water_flux_InterceptCanopyRain(noahmp_c) = 0.0
      noahmp%water_flux_DripCanopyRain(noahmp_c) = 0.0
      noahmp%water_flux_ThroughfallRain(noahmp_c) = noahmp%water_flux_RainfallRefHeight(noahmp_c)
      if ( noahmp%water_state_CanopyLiqWater(noahmp_c) > 0.0 ) then
        noahmp%water_flux_DripCanopyRain(noahmp_c) = noahmp%water_flux_DripCanopyRain(noahmp_c) + noahmp%water_state_CanopyLiqWater(noahmp_c) / noahmp%config_domain_MainTimeStep(noahmp_c)
        noahmp%water_state_CanopyLiqWater(noahmp_c) = 0.0
      endif
    endif
    noahmp%water_state_CanopyIceMax(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * 6.6 * (0.27 + 46.0/noahmp%water_state_SnowfallDensity(noahmp_c)) * (noahmp%energy_state_LeafAreaIndEff(noahmp_c) + noahmp%energy_state_StemAreaIndEff(noahmp_c))
    if ( (noahmp%energy_state_LeafAreaIndEff(noahmp_c)+noahmp%energy_state_StemAreaIndEff(noahmp_c)) > 0.0 ) then
      noahmp%water_flux_InterceptCanopySnow(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%water_flux_SnowfallRefHeight(noahmp_c) * noahmp%water_state_PrecipAreaFrac(noahmp_c)
      noahmp%water_flux_InterceptCanopySnow(noahmp_c) = min( noahmp%water_flux_InterceptCanopySnow(noahmp_c), &
        & (noahmp%water_state_CanopyIceMax(noahmp_c)-noahmp%water_state_CanopyIce(noahmp_c))/noahmp%config_domain_MainTimeStep(noahmp_c) * (1.0-exp(-noahmp%water_flux_SnowfallRefHeight(noahmp_c)*noahmp%config_domain_MainTimeStep(noahmp_c)/noahmp%water_state_CanopyIceMax(noahmp_c))) )
      noahmp%water_flux_InterceptCanopySnow(noahmp_c) = max( noahmp%water_flux_InterceptCanopySnow(noahmp_c), 0.0 )
      IceDripFacTemp = max( 0.0, (noahmp%energy_state_TemperatureCanopy(noahmp_c) - 270.15) / 1.87e5 )
      IceDripFacWind = sqrt(noahmp%forcing_WindEastwardRefHeight(noahmp_c)**2.0 + noahmp%forcing_WindNorthwardRefHeight(noahmp_c)**2.0) / 1.56e5
      CanopySnowDrip = max( 0.0, noahmp%water_state_CanopyIce(noahmp_c) ) * (IceDripFacWind + IceDripFacTemp)
      CanopySnowDrip = min( noahmp%water_state_CanopyIce(noahmp_c)/noahmp%config_domain_MainTimeStep(noahmp_c) + noahmp%water_flux_InterceptCanopySnow(noahmp_c), CanopySnowDrip)
      noahmp%water_flux_DripCanopySnow(noahmp_c) = (noahmp%energy_state_VegFrac(noahmp_c) * noahmp%water_flux_SnowfallRefHeight(noahmp_c) - noahmp%water_flux_InterceptCanopySnow(noahmp_c)) + CanopySnowDrip
      noahmp%water_flux_ThroughfallSnow(noahmp_c) = (1.0 - noahmp%energy_state_VegFrac(noahmp_c)) * noahmp%water_flux_SnowfallRefHeight(noahmp_c)
      noahmp%water_state_CanopyIce(noahmp_c) = max( 0.0, noahmp%water_state_CanopyIce(noahmp_c) + (noahmp%water_flux_InterceptCanopySnow(noahmp_c)-CanopySnowDrip)*noahmp%config_domain_MainTimeStep(noahmp_c) )
    else
      noahmp%water_flux_InterceptCanopySnow(noahmp_c) = 0.0
      noahmp%water_flux_DripCanopySnow(noahmp_c) = 0.0
      noahmp%water_flux_ThroughfallSnow(noahmp_c) = noahmp%water_flux_SnowfallRefHeight(noahmp_c)
      if ( noahmp%water_state_CanopyIce(noahmp_c) > 0.0 ) then
        noahmp%water_flux_DripCanopySnow(noahmp_c) = noahmp%water_flux_DripCanopySnow(noahmp_c) + noahmp%water_state_CanopyIce(noahmp_c) / noahmp%config_domain_MainTimeStep(noahmp_c)
        noahmp%water_state_CanopyIce(noahmp_c) = 0.0
      endif
    endif
    if ( noahmp%water_state_CanopyIce(noahmp_c) > 0.0 ) then
      noahmp%water_state_CanopyWetFrac(noahmp_c) = max( 0.0, noahmp%water_state_CanopyIce(noahmp_c) ) / max( noahmp%water_state_CanopyIceMax(noahmp_c), 1.0e-06 )
    else
      noahmp%water_state_CanopyWetFrac(noahmp_c) = max( 0.0, noahmp%water_state_CanopyLiqWater(noahmp_c) ) / max( noahmp%water_state_CanopyLiqWaterMax(noahmp_c), 1.0e-06 )
    endif
    noahmp%water_state_CanopyWetFrac(noahmp_c) = min( noahmp%water_state_CanopyWetFrac(noahmp_c), 1.0 ) ** 0.667
    noahmp%water_state_CanopyTotalWater(noahmp_c) = noahmp%water_state_CanopyLiqWater(noahmp_c) + noahmp%water_state_CanopyIce(noahmp_c)
    noahmp%water_flux_RainfallGround(noahmp_c) = noahmp%water_flux_DripCanopyRain(noahmp_c) + noahmp%water_flux_ThroughfallRain(noahmp_c)
    noahmp%water_flux_SnowfallGround(noahmp_c) = noahmp%water_flux_DripCanopySnow(noahmp_c) + noahmp%water_flux_ThroughfallSnow(noahmp_c)
    noahmp%water_flux_SnowDepthIncr(noahmp_c) = noahmp%water_flux_SnowfallGround(noahmp_c) / noahmp%water_state_SnowfallDensity(noahmp_c)
  end subroutine CanopyWaterIntercept
end module lean_canopywaterinterceptmod

! Source: physics_noahmp/src/PrecipitationHeatAdvectMod.F90
module lean_precipitationheatadvectmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine PrecipitationHeatAdvect(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    real(kind=kind_noahmp) :: HeatPrcpAirToCan
    real(kind=kind_noahmp) :: HeatPrcpCanToGrd
    real(kind=kind_noahmp) :: HeatPrcpAirToGrd
    HeatPrcpAirToCan = 0.0
    HeatPrcpCanToGrd = 0.0
    HeatPrcpAirToGrd = 0.0
    noahmp%energy_flux_HeatPrecipAdvCanopy(noahmp_c) = 0.0
    noahmp%energy_flux_HeatPrecipAdvVegGrd(noahmp_c) = 0.0
    noahmp%energy_flux_HeatPrecipAdvBareGrd(noahmp_c) = 0.0
    HeatPrcpAirToCan = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%water_flux_RainfallRefHeight(noahmp_c) * (ConstHeatCapacWater/1000.0) * (noahmp%forcing_TemperatureAirRefHeight(noahmp_c)-noahmp%energy_state_TemperatureCanopy(noahmp_c))
    HeatPrcpCanToGrd = noahmp%water_flux_DripCanopyRain(noahmp_c) * (ConstHeatCapacWater/1000.0) * (noahmp%energy_state_TemperatureCanopy(noahmp_c)-noahmp%energy_state_TemperatureGrd(noahmp_c))
    HeatPrcpAirToGrd = noahmp%water_flux_ThroughfallRain(noahmp_c) * (ConstHeatCapacWater/1000.0) * (noahmp%forcing_TemperatureAirRefHeight(noahmp_c)-noahmp%energy_state_TemperatureGrd(noahmp_c))
    HeatPrcpAirToCan = HeatPrcpAirToCan + noahmp%energy_state_VegFrac(noahmp_c) * noahmp%water_flux_SnowfallRefHeight(noahmp_c) * (ConstHeatCapacIce/1000.0) * (noahmp%forcing_TemperatureAirRefHeight(noahmp_c)-noahmp%energy_state_TemperatureCanopy(noahmp_c))
    HeatPrcpCanToGrd = HeatPrcpCanToGrd + noahmp%water_flux_DripCanopySnow(noahmp_c) * (ConstHeatCapacIce/1000.0) * (noahmp%energy_state_TemperatureCanopy(noahmp_c)-noahmp%energy_state_TemperatureGrd(noahmp_c))
    HeatPrcpAirToGrd = HeatPrcpAirToGrd + noahmp%water_flux_ThroughfallSnow(noahmp_c) * (ConstHeatCapacIce/1000.0) * (noahmp%forcing_TemperatureAirRefHeight(noahmp_c)-noahmp%energy_state_TemperatureGrd(noahmp_c))
    noahmp%energy_flux_HeatPrecipAdvCanopy(noahmp_c) = HeatPrcpAirToCan - HeatPrcpCanToGrd
    noahmp%energy_flux_HeatPrecipAdvVegGrd(noahmp_c) = HeatPrcpCanToGrd
    noahmp%energy_flux_HeatPrecipAdvBareGrd(noahmp_c) = HeatPrcpAirToGrd
    if ( (noahmp%energy_state_VegFrac(noahmp_c) > 0.0) .and. (noahmp%energy_state_VegFrac(noahmp_c) < 1.0) ) then
      noahmp%energy_flux_HeatPrecipAdvVegGrd(noahmp_c) = noahmp%energy_flux_HeatPrecipAdvVegGrd(noahmp_c) / noahmp%energy_state_VegFrac(noahmp_c)
      noahmp%energy_flux_HeatPrecipAdvBareGrd(noahmp_c) = noahmp%energy_flux_HeatPrecipAdvBareGrd(noahmp_c) / (1.0-noahmp%energy_state_VegFrac(noahmp_c))
    elseif ( noahmp%energy_state_VegFrac(noahmp_c) <= 0.0 ) then
      noahmp%energy_flux_HeatPrecipAdvBareGrd(noahmp_c) = noahmp%energy_flux_HeatPrecipAdvVegGrd(noahmp_c) + noahmp%energy_flux_HeatPrecipAdvBareGrd(noahmp_c)
      noahmp%energy_flux_HeatPrecipAdvVegGrd(noahmp_c) = 0.0
      noahmp%energy_flux_HeatPrecipAdvCanopy(noahmp_c) = 0.0
    elseif ( noahmp%energy_state_VegFrac(noahmp_c) >= 1.0 ) then
      noahmp%energy_flux_HeatPrecipAdvBareGrd(noahmp_c) = 0.0
    endif
    noahmp%energy_flux_HeatPrecipAdvCanopy(noahmp_c) = max(noahmp%energy_flux_HeatPrecipAdvCanopy(noahmp_c) , -20.0)
    noahmp%energy_flux_HeatPrecipAdvCanopy(noahmp_c) = min(noahmp%energy_flux_HeatPrecipAdvCanopy(noahmp_c) , 20.0)
    noahmp%energy_flux_HeatPrecipAdvVegGrd(noahmp_c) = max(noahmp%energy_flux_HeatPrecipAdvVegGrd(noahmp_c) , -20.0)
    noahmp%energy_flux_HeatPrecipAdvVegGrd(noahmp_c) = min(noahmp%energy_flux_HeatPrecipAdvVegGrd(noahmp_c) , 20.0)
    noahmp%energy_flux_HeatPrecipAdvBareGrd(noahmp_c) = max(noahmp%energy_flux_HeatPrecipAdvBareGrd(noahmp_c), -20.0)
    noahmp%energy_flux_HeatPrecipAdvBareGrd(noahmp_c) = min(noahmp%energy_flux_HeatPrecipAdvBareGrd(noahmp_c), 20.0)
  end subroutine PrecipitationHeatAdvect
end module lean_precipitationheatadvectmod

! Source: physics_noahmp/src/SnowCoverGroundNiu07Mod.F90
module lean_snowcovergroundniu07mod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine SnowCoverGroundNiu07(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    real(kind=kind_noahmp) :: SnowDensBulk
    real(kind=kind_noahmp) :: MeltFac
    noahmp%water_state_SnowCoverFrac(noahmp_c) = 0.0
    if ( noahmp%water_state_SnowDepth(noahmp_c) > 0.0 ) then
      SnowDensBulk = noahmp%water_state_SnowWaterEquiv(noahmp_c) / noahmp%water_state_SnowDepth(noahmp_c)
      MeltFac = (SnowDensBulk / 100.0)**noahmp%water_param_SnowMeltFac(noahmp_c)
      noahmp%water_state_SnowCoverFrac(noahmp_c) = tanh( noahmp%water_state_SnowDepth(noahmp_c) /(noahmp%water_param_SnowCoverFac(noahmp_c) * MeltFac))
    endif
  end subroutine SnowCoverGroundNiu07
end module lean_snowcovergroundniu07mod

! Source: physics_noahmp/src/GroundRoughnessPropertyMod.F90
module lean_groundroughnesspropertymod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine GroundRoughnessProperty(noahmp, noahmp_c, FlagVegSfc)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    logical , intent(in ) :: FlagVegSfc
    noahmp%energy_state_RoughLenMomGrd(noahmp_c) = noahmp%energy_param_RoughLenMomSoil(noahmp_c) * (1.0-noahmp%water_state_SnowCoverFrac(noahmp_c)) + noahmp%water_state_SnowCoverFrac(noahmp_c) * noahmp%energy_param_RoughLenMomSnow(noahmp_c)
    noahmp%energy_state_ZeroPlaneDispGrd(noahmp_c) = noahmp%water_state_SnowDepth(noahmp_c)
    if ( FlagVegSfc .eqv. .true. ) then
      noahmp%energy_state_RoughLenMomSfc(noahmp_c) = noahmp%energy_param_RoughLenMomVeg(noahmp_c)
      noahmp%energy_state_ZeroPlaneDispSfc(noahmp_c) = 0.65 * noahmp%energy_param_HeightCanopyTop(noahmp_c)
      if ( noahmp%water_state_SnowDepth(noahmp_c) > noahmp%energy_state_ZeroPlaneDispSfc(noahmp_c) ) noahmp%energy_state_ZeroPlaneDispSfc(noahmp_c) = noahmp%water_state_SnowDepth(noahmp_c)
    else
      noahmp%energy_state_RoughLenMomSfc(noahmp_c) = noahmp%energy_state_RoughLenMomGrd(noahmp_c)
      noahmp%energy_state_ZeroPlaneDispSfc(noahmp_c) = noahmp%energy_state_ZeroPlaneDispGrd(noahmp_c)
    endif
    if ( noahmp%config_domain_FlagUrban(noahmp_c) .eqv. .true. ) then
      noahmp%energy_state_RoughLenMomGrd(noahmp_c) = noahmp%energy_param_RoughLenMomVeg(noahmp_c)
      noahmp%energy_state_ZeroPlaneDispGrd(noahmp_c) = 0.65 * noahmp%energy_param_HeightCanopyTop(noahmp_c)
      noahmp%energy_state_RoughLenMomSfc(noahmp_c) = noahmp%energy_state_RoughLenMomGrd(noahmp_c)
      noahmp%energy_state_ZeroPlaneDispSfc(noahmp_c) = noahmp%energy_state_ZeroPlaneDispGrd(noahmp_c)
    endif
    noahmp%energy_state_RefHeightAboveGrd(noahmp_c) = max(noahmp%energy_state_ZeroPlaneDispSfc(noahmp_c), noahmp%energy_param_HeightCanopyTop(noahmp_c)) + noahmp%config_domain_RefHeightAboveSfc(noahmp_c)
    if ( noahmp%energy_state_ZeroPlaneDispGrd(noahmp_c) >= noahmp%energy_state_RefHeightAboveGrd(noahmp_c) ) noahmp%energy_state_RefHeightAboveGrd(noahmp_c) = noahmp%energy_state_ZeroPlaneDispGrd(noahmp_c) + noahmp%config_domain_RefHeightAboveSfc(noahmp_c)
  end subroutine GroundRoughnessProperty
end module lean_groundroughnesspropertymod

! Source: physics_noahmp/src/SnowThermalPropertyMod.F90
module lean_snowthermalpropertymod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine SnowThermalProperty(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: LoopInd
    real(kind=kind_noahmp), dimension(-2:0) :: SnowDensBulk
    SnowDensBulk = 0.0
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 0
      noahmp%water_state_SnowIceVol(LoopInd, noahmp_c) = min(1.0, noahmp%water_state_SnowIce(LoopInd, noahmp_c)/(noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c)*ConstDensityIce))
      noahmp%water_state_SnowEffPorosity(LoopInd, noahmp_c) = 1.0 - noahmp%water_state_SnowIceVol(LoopInd, noahmp_c)
      noahmp%water_state_SnowLiqWaterVol(LoopInd, noahmp_c) = min(noahmp%water_state_SnowEffPorosity(LoopInd, noahmp_c), &
        & noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c)/(noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c)*ConstDensityWater))
    enddo
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 0
      SnowDensBulk(LoopInd) = (noahmp%water_state_SnowIce(LoopInd, noahmp_c) + noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c)) / noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c)
      noahmp%energy_state_HeatCapacVolSnow(LoopInd, noahmp_c) = ConstHeatCapacIce*noahmp%water_state_SnowIceVol(LoopInd, noahmp_c) + ConstHeatCapacWater*noahmp%water_state_SnowLiqWaterVol(LoopInd, noahmp_c)
    enddo
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 0
      noahmp%energy_state_ThermConductSnow(LoopInd, noahmp_c) = 3.2217e-6 * SnowDensBulk(LoopInd)**2.0
    enddo
  end subroutine SnowThermalProperty
end module lean_snowthermalpropertymod

! Source: physics_noahmp/src/SoilThermalPropertyMod.F90
module lean_soilthermalpropertymod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine SoilThermalProperty(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: LoopInd
    real(kind=kind_noahmp) :: KerstenFac
    real(kind=kind_noahmp) :: SoilGamFac
    real(kind=kind_noahmp) :: ThermConductSoilDry
    real(kind=kind_noahmp) :: ThermConductSoilSat
    real(kind=kind_noahmp) :: ThermConductSolid
    real(kind=kind_noahmp) :: SoilSatRatio
    real(kind=kind_noahmp) :: SoilWatFracSat
    real(kind=kind_noahmp) :: SoilWatFrac
    real(kind=kind_noahmp), dimension(1:4) :: SoilIceTmp
    SoilIceTmp(:) = 0.0
    do LoopInd = 1, 4
      SoilIceTmp(LoopInd) = noahmp%water_state_SoilMoisture(LoopInd, noahmp_c) - noahmp%water_state_SoilLiqWater(LoopInd, noahmp_c)
      noahmp%energy_state_HeatCapacVolSoil(LoopInd, noahmp_c) = noahmp%water_state_SoilLiqWater(LoopInd, noahmp_c) * ConstHeatCapacWater + (1.0 - noahmp%water_param_SoilMoistureSat(LoopInd, noahmp_c)) * noahmp%energy_param_SoilHeatCapacity(noahmp_c) + (noahmp%water_param_SoilMoistureSat(LoopInd, noahmp_c) - noahmp%water_state_SoilMoisture(LoopInd, noahmp_c)) * ConstHeatCapacAir + SoilIceTmp(LoopInd) * ConstHeatCapacIce
      SoilSatRatio = noahmp%water_state_SoilMoisture(LoopInd, noahmp_c) / noahmp%water_param_SoilMoistureSat(LoopInd, noahmp_c)
      ThermConductSolid = (ConstThermConductQuartz ** noahmp%energy_param_SoilQuartzFrac(LoopInd, noahmp_c)) * (ConstThermConductSoilOth ** (1.0 - noahmp%energy_param_SoilQuartzFrac(LoopInd, noahmp_c)))
      SoilWatFrac = 1.0
      if ( noahmp%water_state_SoilMoisture(LoopInd, noahmp_c) > 0.0 ) SoilWatFrac = noahmp%water_state_SoilLiqWater(LoopInd, noahmp_c) / noahmp%water_state_SoilMoisture(LoopInd, noahmp_c)
      SoilWatFracSat = SoilWatFrac * noahmp%water_param_SoilMoistureSat(LoopInd, noahmp_c)
      ThermConductSoilSat = ThermConductSolid ** (1.0-noahmp%water_param_SoilMoistureSat(LoopInd, noahmp_c)) * ConstThermConductIce ** (noahmp%water_param_SoilMoistureSat(LoopInd, noahmp_c)-SoilWatFracSat) * ConstThermConductWater ** (SoilWatFracSat)
      SoilGamFac = (1.0 - noahmp%water_param_SoilMoistureSat(LoopInd, noahmp_c)) * 2700.0
      ThermConductSoilDry = (0.135 * SoilGamFac + 64.7) / (2700.0 - 0.947 * SoilGamFac)
      if ( (noahmp%water_state_SoilLiqWater(LoopInd, noahmp_c)+0.0005) < noahmp%water_state_SoilMoisture(LoopInd, noahmp_c) ) then
        KerstenFac = SoilSatRatio
      else
        if ( SoilSatRatio > 0.1 ) then
          KerstenFac = log10(SoilSatRatio) + 1.0
        else
          KerstenFac = 0.0
        endif
      endif
      noahmp%energy_state_ThermConductSoil(LoopInd, noahmp_c) = KerstenFac*(ThermConductSoilSat-ThermConductSoilDry) + ThermConductSoilDry
    enddo
  end subroutine SoilThermalProperty
end module lean_soilthermalpropertymod

! Source: physics_noahmp/src/GroundThermalPropertyMod.F90
module lean_groundthermalpropertymod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_snowthermalpropertymod, only : SnowThermalProperty
  use lean_soilthermalpropertymod, only : SoilThermalProperty
  implicit none
  contains
  subroutine GroundThermalProperty(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: LoopInd
    noahmp%energy_state_HeatCapacSoilSnow(:, noahmp_c) = 0.0
    noahmp%energy_state_ThermConductSoilSnow(:, noahmp_c) = 0.0
    call SnowThermalProperty(noahmp, noahmp_c)
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 0
      noahmp%energy_state_ThermConductSoilSnow(LoopInd, noahmp_c) = noahmp%energy_state_ThermConductSnow(LoopInd, noahmp_c)
      noahmp%energy_state_HeatCapacSoilSnow(LoopInd, noahmp_c) = noahmp%energy_state_HeatCapacVolSnow(LoopInd, noahmp_c)
    enddo
    call SoilThermalProperty(noahmp, noahmp_c)
    do LoopInd = 1, 4
      noahmp%energy_state_ThermConductSoilSnow(LoopInd, noahmp_c) = noahmp%energy_state_ThermConductSoil(LoopInd, noahmp_c)
      noahmp%energy_state_HeatCapacSoilSnow(LoopInd, noahmp_c) = noahmp%energy_state_HeatCapacVolSoil(LoopInd, noahmp_c)
    enddo
    if ( noahmp%config_domain_FlagUrban(noahmp_c) .eqv. .true. ) then
      do LoopInd = 1, 4
        noahmp%energy_state_ThermConductSoilSnow(LoopInd, noahmp_c) = 3.24
      enddo
    endif
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 4
      noahmp%energy_state_PhaseChgFacSoilSnow(LoopInd, noahmp_c) = noahmp%config_domain_MainTimeStep(noahmp_c) / (noahmp%energy_state_HeatCapacSoilSnow(LoopInd, noahmp_c) * noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c))
    enddo
    if ( noahmp%config_domain_NumSnowLayerNeg(noahmp_c) == 0 ) then
      noahmp%energy_state_ThermConductSoilSnow(1, noahmp_c) = (noahmp%energy_state_ThermConductSoilSnow(1, noahmp_c)*noahmp%config_domain_ThicknessSnowSoilLayer(1, noahmp_c) + 0.35*noahmp%water_state_SnowDepth(noahmp_c)) / (noahmp%water_state_SnowDepth(noahmp_c) + noahmp%config_domain_ThicknessSnowSoilLayer(1, noahmp_c))
    else
      noahmp%energy_state_ThermConductSoilSnow(1, noahmp_c) = (noahmp%energy_state_ThermConductSoilSnow(1, noahmp_c)*noahmp%config_domain_ThicknessSnowSoilLayer(1, noahmp_c) + noahmp%energy_state_ThermConductSoilSnow(0, noahmp_c)*noahmp%config_domain_ThicknessSnowSoilLayer(0, noahmp_c)) / (noahmp%config_domain_ThicknessSnowSoilLayer(0, noahmp_c) + noahmp%config_domain_ThicknessSnowSoilLayer(1, noahmp_c))
    endif
  end subroutine GroundThermalProperty
end module lean_groundthermalpropertymod

! Source: physics_noahmp/src/SnowAgingBatsMod.F90
module lean_snowagingbatsmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine SnowAgingBats(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    real(kind=kind_noahmp) :: SnowAgeFacTot
    real(kind=kind_noahmp) :: SnowAgeVapEff
    real(kind=kind_noahmp) :: SnowAgeFrzEff
    real(kind=kind_noahmp) :: SnowAgeSootEff
    real(kind=kind_noahmp) :: SnowAgeChg
    real(kind=kind_noahmp) :: SnowAgeTmp
    real(kind=kind_noahmp) :: SnowFreshFac
    real(kind=kind_noahmp) :: SnowAgeTimeFac
    real(kind=kind_noahmp) :: SnowGrowVapExp
    if ( noahmp%water_state_SnowWaterEquiv(noahmp_c) <= 0.0 ) then
      noahmp%energy_state_SnowAgeNondim(noahmp_c) = 0.0
    else
      SnowAgeTimeFac = noahmp%config_domain_MainTimeStep(noahmp_c) / noahmp%energy_param_SnowAgeFacBats(noahmp_c)
      SnowGrowVapExp = noahmp%energy_param_SnowGrowVapFacBats(noahmp_c) * (1.0/ConstFreezePoint - 1.0/noahmp%energy_state_TemperatureGrd(noahmp_c))
      SnowAgeVapEff = exp(SnowGrowVapExp)
      SnowAgeFrzEff = exp(amin1(0.0, noahmp%energy_param_SnowGrowFrzFacBats(noahmp_c)*SnowGrowVapExp))
      SnowAgeSootEff = noahmp%energy_param_SnowSootFacBats(noahmp_c)
      SnowAgeFacTot = SnowAgeVapEff + SnowAgeFrzEff + SnowAgeSootEff
      SnowAgeChg = SnowAgeTimeFac * SnowAgeFacTot
      SnowFreshFac = amax1(0.0, noahmp%water_state_SnowWaterEquiv(noahmp_c)-noahmp%water_state_SnowWaterEquivPrev(noahmp_c)) / noahmp%water_param_SnowMassFullCoverOld(noahmp_c)
      SnowAgeTmp = (noahmp%energy_state_SnowAgeNondim(noahmp_c) + SnowAgeChg) * (1.0 - SnowFreshFac)
      noahmp%energy_state_SnowAgeNondim(noahmp_c) = amax1(0.0, SnowAgeTmp)
    endif
    noahmp%energy_state_SnowAgeFac(noahmp_c) = noahmp%energy_state_SnowAgeNondim(noahmp_c) / (noahmp%energy_state_SnowAgeNondim(noahmp_c) + 1.0)
  end subroutine SnowAgingBats
end module lean_snowagingbatsmod

! Source: physics_noahmp/src/SnowAlbedoBatsMod.F90
module lean_snowalbedobatsmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine SnowAlbedoBats(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    real(kind=kind_noahmp) :: ZenithAngFac
    real(kind=kind_noahmp) :: ZenithAngFacTmp
    real(kind=kind_noahmp) :: SolarAngleFac2
    real(kind=kind_noahmp) :: SolarAngleFac1
    real(kind=kind_noahmp) :: SolarAngleFac
    noahmp%energy_state_AlbedoSnowDir(1:2, noahmp_c) = 0.0
    noahmp%energy_state_AlbedoSnowDif(1:2, noahmp_c) = 0.0
    SolarAngleFac = noahmp%energy_param_SolarZenithAdjBats(noahmp_c)
    SolarAngleFac1 = 1.0 / SolarAngleFac
    SolarAngleFac2 = 2.0 * SolarAngleFac
    ZenithAngFacTmp = (1.0 + SolarAngleFac1) / (1.0 + SolarAngleFac2*noahmp%config_domain_CosSolarZenithAngle(noahmp_c)) - SolarAngleFac1
    ZenithAngFac = amax1(ZenithAngFacTmp, 0.0)
    noahmp%energy_state_AlbedoSnowDif(1, noahmp_c) = noahmp%energy_param_FreshSnoAlbVisBats(noahmp_c) * (1.0 - noahmp%energy_param_SnoAgeFacDifVisBats(noahmp_c) * noahmp%energy_state_SnowAgeFac(noahmp_c))
    noahmp%energy_state_AlbedoSnowDif(2, noahmp_c) = noahmp%energy_param_FreshSnoAlbNirBats(noahmp_c) * (1.0 - noahmp%energy_param_SnoAgeFacDifNirBats(noahmp_c) * noahmp%energy_state_SnowAgeFac(noahmp_c))
    noahmp%energy_state_AlbedoSnowDir(1, noahmp_c) = noahmp%energy_state_AlbedoSnowDif(1, noahmp_c) + noahmp%energy_param_SzaFacDirVisBats(noahmp_c) * ZenithAngFac * (1.0 - noahmp%energy_state_AlbedoSnowDif(1, noahmp_c))
    noahmp%energy_state_AlbedoSnowDir(2, noahmp_c) = noahmp%energy_state_AlbedoSnowDif(2, noahmp_c) + noahmp%energy_param_SzaFacDirNirBats(noahmp_c) * ZenithAngFac * (1.0 - noahmp%energy_state_AlbedoSnowDif(2, noahmp_c))
  end subroutine SnowAlbedoBats
end module lean_snowalbedobatsmod

! Source: physics_noahmp/src/GroundAlbedoMod.F90
module lean_groundalbedomod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine GroundAlbedo(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: IndSwBnd
    real(kind=kind_noahmp) :: AlbedoSoilAdjWet
    do IndSwBnd = 1, 2
      AlbedoSoilAdjWet = max(0.11-0.40*noahmp%water_state_SoilMoisture(1, noahmp_c), 0.0)
      noahmp%energy_state_AlbedoSoilDir(IndSwBnd, noahmp_c) = min(noahmp%energy_param_AlbedoSoilSat(IndSwBnd, noahmp_c)+AlbedoSoilAdjWet, noahmp%energy_param_AlbedoSoilDry(IndSwBnd, noahmp_c))
      noahmp%energy_state_AlbedoSoilDif(IndSwBnd, noahmp_c) = noahmp%energy_state_AlbedoSoilDir(IndSwBnd, noahmp_c)
      noahmp%energy_state_AlbedoGrdDir(IndSwBnd, noahmp_c) = noahmp%energy_state_AlbedoSoilDir(IndSwBnd, noahmp_c)*(1.0-noahmp%water_state_SnowCoverFrac(noahmp_c)) + noahmp%energy_state_AlbedoSnowDir(IndSwBnd, noahmp_c)*noahmp%water_state_SnowCoverFrac(noahmp_c)
      noahmp%energy_state_AlbedoGrdDif(IndSwBnd, noahmp_c) = noahmp%energy_state_AlbedoSoilDif(IndSwBnd, noahmp_c)*(1.0-noahmp%water_state_SnowCoverFrac(noahmp_c)) + noahmp%energy_state_AlbedoSnowDif(IndSwBnd, noahmp_c)*noahmp%water_state_SnowCoverFrac(noahmp_c)
    enddo
  end subroutine GroundAlbedo
end module lean_groundalbedomod

! Source: physics_noahmp/src/CanopyRadiationTwoStreamMod.F90
module lean_canopyradiationtwostreammod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine CanopyRadiationTwoStream(noahmp, noahmp_c, IndSwBnd, IndSwDif)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer , intent(in ) :: IndSwBnd
    integer , intent(in ) :: IndSwDif
    real(kind=kind_noahmp) :: ScatCoeffCan
    real(kind=kind_noahmp) :: ScatCoeffLeaf
    real(kind=kind_noahmp) :: UpscatCoeffCanDif
    real(kind=kind_noahmp) :: UpscatCoeffLeafDif
    real(kind=kind_noahmp) :: UpscatCoeffCanDir
    real(kind=kind_noahmp) :: UpscatCoeffLeafDir
    real(kind=kind_noahmp) :: OpticDepthDir
    real(kind=kind_noahmp) :: OpticDepthDif
    real(kind=kind_noahmp) :: CosSolarZenithAngleTmp
    real(kind=kind_noahmp) :: SingleScatAlb
    real(kind=kind_noahmp) :: LeafOrientIndex
    real(kind=kind_noahmp) :: RadSwTransDir
    real(kind=kind_noahmp) :: RadSwTransDif
    real(kind=kind_noahmp) :: RadSwReflTot
    real(kind=kind_noahmp) :: VegDensity
    real(kind=kind_noahmp) :: RadSwReflCan
    real(kind=kind_noahmp) :: RadSwReflGrd
    real(kind=kind_noahmp) :: CrownDepth
    real(kind=kind_noahmp) :: CrownRadiusVert
    real(kind=kind_noahmp) :: SolarAngleTmp
    real(kind=kind_noahmp) :: FoliageDensity
    real(kind=kind_noahmp) :: VegAreaIndTmp
    real(kind=kind_noahmp) :: Tmp0,Tmp1,Tmp2,Tmp3,Tmp4
    real(kind=kind_noahmp) :: Tmp5,Tmp6,Tmp7,Tmp8,Tmp9
    real(kind=kind_noahmp) :: P1,P2,P3,P4,S1,S2,U1,U2,U3
    real(kind=kind_noahmp) :: B,C,D,D1,D2,F,H,H1,H2,H3
    real(kind=kind_noahmp) :: H4,H5,H6,H7,H8,H9,H10
    real(kind=kind_noahmp) :: Phi1,Phi2,Sigma
    if ( noahmp%energy_state_VegAreaIndEff(noahmp_c) == 0.0 ) then
      noahmp%energy_state_GapCanopyDir(noahmp_c) = 1.0
      noahmp%energy_state_GapCanopyDif(noahmp_c) = 1.0
    else
      noahmp%energy_state_GapCanopyDir(noahmp_c) = 1.0 - noahmp%energy_state_VegFrac(noahmp_c)
      noahmp%energy_state_GapCanopyDif(noahmp_c) = 1.0 - noahmp%energy_state_VegFrac(noahmp_c)
    endif
    CosSolarZenithAngleTmp = max( 0.001, noahmp%config_domain_CosSolarZenithAngle(noahmp_c) )
    LeafOrientIndex = min( max(noahmp%energy_param_CanopyOrientIndex(noahmp_c), -0.4), 0.6 )
    if ( abs(LeafOrientIndex) <= 0.01 ) LeafOrientIndex = 0.01
    Phi1 = 0.5 - 0.633 * LeafOrientIndex - 0.330 * LeafOrientIndex * LeafOrientIndex
    Phi2 = 0.877 * (1.0 - 2.0 * Phi1)
    noahmp%energy_state_VegAreaProjDir(noahmp_c) = Phi1 + Phi2 * CosSolarZenithAngleTmp
    OpticDepthDir = noahmp%energy_state_VegAreaProjDir(noahmp_c) / CosSolarZenithAngleTmp
    OpticDepthDif = (1.0 - Phi1/Phi2 * log( (Phi1+Phi2) / Phi1 )) / Phi2
    ScatCoeffLeaf = noahmp%energy_state_ReflectanceVeg(IndSwBnd, noahmp_c) + noahmp%energy_state_TransmittanceVeg(IndSwBnd, noahmp_c)
    Tmp0 = noahmp%energy_state_VegAreaProjDir(noahmp_c) + Phi2 * CosSolarZenithAngleTmp
    Tmp1 = Phi1 * CosSolarZenithAngleTmp
    SingleScatAlb = 0.5 * ScatCoeffLeaf * noahmp%energy_state_VegAreaProjDir(noahmp_c) / Tmp0 * (1.0 - Tmp1/Tmp0 * log((Tmp1+Tmp0)/Tmp1) )
    UpscatCoeffLeafDir = (1.0 + OpticDepthDif * OpticDepthDir) / (ScatCoeffLeaf * OpticDepthDif * OpticDepthDir) * SingleScatAlb
    UpscatCoeffLeafDif = 0.5 * (noahmp%energy_state_ReflectanceVeg(IndSwBnd, noahmp_c) + noahmp%energy_state_TransmittanceVeg(IndSwBnd, noahmp_c) + (noahmp%energy_state_ReflectanceVeg(IndSwBnd, noahmp_c)-noahmp%energy_state_TransmittanceVeg(IndSwBnd, noahmp_c))*((1.0+LeafOrientIndex)/2.0)**2)/ScatCoeffLeaf
    if ( noahmp%energy_state_TemperatureCanopy(noahmp_c) > ConstFreezePoint ) then
      Tmp0 = ScatCoeffLeaf
      Tmp1 = UpscatCoeffLeafDir
      Tmp2 = UpscatCoeffLeafDif
    else
      Tmp0 = (1.0 - noahmp%water_state_CanopyWetFrac(noahmp_c)) * ScatCoeffLeaf + noahmp%water_state_CanopyWetFrac(noahmp_c) * noahmp%energy_param_ScatterCoeffSnow(IndSwBnd, noahmp_c)
      Tmp1 = ((1.0 - noahmp%water_state_CanopyWetFrac(noahmp_c)) * ScatCoeffLeaf * UpscatCoeffLeafDir + noahmp%water_state_CanopyWetFrac(noahmp_c) * noahmp%energy_param_ScatterCoeffSnow(IndSwBnd, noahmp_c) * noahmp%energy_param_UpscatterCoeffSnowDir(noahmp_c) ) / Tmp0
      Tmp2 = ((1.0 - noahmp%water_state_CanopyWetFrac(noahmp_c)) * ScatCoeffLeaf * UpscatCoeffLeafDif + noahmp%water_state_CanopyWetFrac(noahmp_c) * noahmp%energy_param_ScatterCoeffSnow(IndSwBnd, noahmp_c) * noahmp%energy_param_UpscatterCoeffSnowDif(noahmp_c) ) / Tmp0
    endif
    ScatCoeffCan = Tmp0
    UpscatCoeffCanDir = Tmp1
    UpscatCoeffCanDif = Tmp2
    B = 1.0 - ScatCoeffCan + ScatCoeffCan * UpscatCoeffCanDif
    C = ScatCoeffCan * UpscatCoeffCanDif
    Tmp0 = OpticDepthDif * OpticDepthDir
    D = Tmp0 * ScatCoeffCan * UpscatCoeffCanDir
    F = Tmp0 * ScatCoeffCan * (1.0 - UpscatCoeffCanDir)
    Tmp1 = B * B - C * C
    H = sqrt(Tmp1) / OpticDepthDif
    Sigma = Tmp0 * Tmp0 - Tmp1
    if ( abs(Sigma) < 1.0e-6 ) Sigma = sign(1.0e-6, Sigma)
    P1 = B + OpticDepthDif * H
    P2 = B - OpticDepthDif * H
    P3 = B + Tmp0
    P4 = B - Tmp0
    S1 = exp( -H * noahmp%energy_state_VegAreaIndEff(noahmp_c) )
    S2 = exp( -OpticDepthDir * noahmp%energy_state_VegAreaIndEff(noahmp_c) )
    if ( IndSwDif == 0 ) then
      U1 = B - C / noahmp%energy_state_AlbedoGrdDir(IndSwBnd, noahmp_c)
      U2 = B - C * noahmp%energy_state_AlbedoGrdDir(IndSwBnd, noahmp_c)
      U3 = F + C * noahmp%energy_state_AlbedoGrdDir(IndSwBnd, noahmp_c)
    else
      U1 = B - C / noahmp%energy_state_AlbedoGrdDif(IndSwBnd, noahmp_c)
      U2 = B - C * noahmp%energy_state_AlbedoGrdDif(IndSwBnd, noahmp_c)
      U3 = F + C * noahmp%energy_state_AlbedoGrdDif(IndSwBnd, noahmp_c)
    endif
    Tmp2 = U1 - OpticDepthDif * H
    Tmp3 = U1 + OpticDepthDif * H
    D1 = P1 * Tmp2 / S1 - P2 * Tmp3 * S1
    Tmp4 = U2 + OpticDepthDif * H
    Tmp5 = U2 - OpticDepthDif * H
    D2 = Tmp4 / S1 - Tmp5 * S1
    H1 = -D * P4 - C * F
    Tmp6 = D - H1 * P3 / Sigma
    Tmp7 = ( D - C - H1 / Sigma * (U1+Tmp0) ) * S2
    H2 = ( Tmp6 * Tmp2 / S1 - P2 * Tmp7 ) / D1
    H3 = - ( Tmp6 * Tmp3 * S1 - P1 * Tmp7 ) / D1
    H4 = -F * P3 - C * D
    Tmp8 = H4 / Sigma
    Tmp9 = ( U3 - Tmp8 * (U2-Tmp0) ) * S2
    H5 = - ( Tmp8 * Tmp4 / S1 + Tmp9 ) / D2
    H6 = ( Tmp8 * Tmp5 * S1 + Tmp9 ) / D2
    H7 = (C * Tmp2) / (D1 * S1)
    H8 = (-C * Tmp3 * S1) / D1
    H9 = Tmp4 / (D2 * S1)
    H10 = (-Tmp5 * S1) / D2
    if ( IndSwDif == 0 ) then
      RadSwTransDir = S2 * (1.0 - noahmp%energy_state_GapCanopyDir(noahmp_c)) + noahmp%energy_state_GapCanopyDir(noahmp_c)
      RadSwTransDif = (H4 * S2 / Sigma + H5 * S1 + H6 / S1) * (1.0 - noahmp%energy_state_GapCanopyDir(noahmp_c))
    else
      RadSwTransDir = 0.0
      RadSwTransDif = (H9 * S1 + H10 / S1) * (1.0 - noahmp%energy_state_GapCanopyDif(noahmp_c)) + noahmp%energy_state_GapCanopyDif(noahmp_c)
    endif
    if ( IndSwDif == 0 ) then
      noahmp%energy_flux_RadSwDirTranGrdDir(IndSwBnd, noahmp_c) = RadSwTransDir
      noahmp%energy_flux_RadSwDifTranGrdDir(IndSwBnd, noahmp_c) = RadSwTransDif
    else
      noahmp%energy_flux_RadSwDirTranGrdDif(IndSwBnd, noahmp_c) = RadSwTransDir
      noahmp%energy_flux_RadSwDifTranGrdDif(IndSwBnd, noahmp_c) = RadSwTransDif
    endif
    if ( IndSwDif == 0 ) then
      RadSwReflTot = (H1 / Sigma + H2 + H3) * (1.0 - noahmp%energy_state_GapCanopyDir(noahmp_c)) + noahmp%energy_state_AlbedoGrdDir(IndSwBnd, noahmp_c) * noahmp%energy_state_GapCanopyDir(noahmp_c)
      RadSwReflCan = (H1 / Sigma + H2 + H3) * (1.0 - noahmp%energy_state_GapCanopyDir(noahmp_c))
      RadSwReflGrd = noahmp%energy_state_AlbedoGrdDir(IndSwBnd, noahmp_c) * noahmp%energy_state_GapCanopyDir(noahmp_c)
    else
      RadSwReflTot = (H7 + H8) * (1.0 - noahmp%energy_state_GapCanopyDif(noahmp_c)) + noahmp%energy_state_AlbedoGrdDif(IndSwBnd, noahmp_c) * noahmp%energy_state_GapCanopyDif(noahmp_c)
      RadSwReflCan = (H7 + H8) * (1.0 - noahmp%energy_state_GapCanopyDif(noahmp_c)) + noahmp%energy_state_AlbedoGrdDif(IndSwBnd, noahmp_c) * noahmp%energy_state_GapCanopyDif(noahmp_c)
      RadSwReflGrd = 0
    endif
    if ( IndSwDif == 0 ) then
      noahmp%energy_state_AlbedoSfcDir(IndSwBnd, noahmp_c) = RadSwReflTot
      noahmp%energy_flux_RadSwReflVegDir(IndSwBnd, noahmp_c) = RadSwReflCan
      noahmp%energy_flux_RadSwReflGrdDir(IndSwBnd, noahmp_c) = RadSwReflGrd
    else
      noahmp%energy_state_AlbedoSfcDif(IndSwBnd, noahmp_c) = RadSwReflTot
      noahmp%energy_flux_RadSwReflVegDif(IndSwBnd, noahmp_c) = RadSwReflCan
      noahmp%energy_flux_RadSwReflGrdDif(IndSwBnd, noahmp_c) = RadSwReflGrd
    endif
    if ( IndSwDif == 0 ) then
      noahmp%energy_flux_RadSwAbsVegDir(IndSwBnd, noahmp_c) = 1.0 - noahmp%energy_state_AlbedoSfcDir(IndSwBnd, noahmp_c) - (1.0 - noahmp%energy_state_AlbedoGrdDir(IndSwBnd, noahmp_c))*noahmp%energy_flux_RadSwDirTranGrdDir(IndSwBnd, noahmp_c) - (1.0 - noahmp%energy_state_AlbedoGrdDif(IndSwBnd, noahmp_c))*noahmp%energy_flux_RadSwDifTranGrdDir(IndSwBnd, noahmp_c)
    else
      noahmp%energy_flux_RadSwAbsVegDif(IndSwBnd, noahmp_c) = 1.0 - noahmp%energy_state_AlbedoSfcDif(IndSwBnd, noahmp_c) - (1.0 - noahmp%energy_state_AlbedoGrdDir(IndSwBnd, noahmp_c))*noahmp%energy_flux_RadSwDirTranGrdDif(IndSwBnd, noahmp_c) - (1.0 - noahmp%energy_state_AlbedoGrdDif(IndSwBnd, noahmp_c))*noahmp%energy_flux_RadSwDifTranGrdDif(IndSwBnd, noahmp_c)
    endif
  end subroutine CanopyRadiationTwoStream
end module lean_canopyradiationtwostreammod

! Source: physics_noahmp/src/SurfaceAlbedoMod.F90
module lean_surfacealbedomod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_snowagingbatsmod, only : SnowAgingBats
  use lean_snowalbedobatsmod, only : SnowAlbedoBats
  use lean_groundalbedomod, only : GroundAlbedo
  use lean_canopyradiationtwostreammod, only : CanopyRadiationTwoStream
  implicit none
  contains
  subroutine SurfaceAlbedo(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: IndBand
    integer :: IndDif
    real(kind=kind_noahmp) :: LeafWgt
    real(kind=kind_noahmp) :: StemWgt
    real(kind=kind_noahmp) :: MinThr
    real(kind=kind_noahmp) :: LightExtDir
    MinThr = 1.0e-06
    noahmp%energy_state_GapBtwCanopy(noahmp_c) = 0.0
    noahmp%energy_state_GapInCanopy(noahmp_c) = 0.0
    noahmp%energy_state_VegAreaProjDir(noahmp_c) = 0.0
    noahmp%energy_state_ReflectanceVeg(:, noahmp_c) = 0.0
    noahmp%energy_state_TransmittanceVeg(:, noahmp_c) = 0.0
    noahmp%energy_state_CanopySunlitFrac(noahmp_c) = 0.0
    do IndBand = 1, 2
      noahmp%energy_state_AlbedoSfcDir(IndBand, noahmp_c) = 0.0
      noahmp%energy_state_AlbedoSfcDif(IndBand, noahmp_c) = 0.0
      noahmp%energy_state_AlbedoGrdDir(IndBand, noahmp_c) = 0.0
      noahmp%energy_state_AlbedoGrdDif(IndBand, noahmp_c) = 0.0
      noahmp%energy_state_AlbedoSnowDir(IndBand, noahmp_c) = 0.0
      noahmp%energy_state_AlbedoSnowDif(IndBand, noahmp_c) = 0.0
      noahmp%energy_flux_RadSwAbsVegDir(IndBand, noahmp_c) = 0.0
      noahmp%energy_flux_RadSwAbsVegDif(IndBand, noahmp_c) = 0.0
      noahmp%energy_flux_RadSwDirTranGrdDir(IndBand, noahmp_c) = 0.0
      noahmp%energy_flux_RadSwDirTranGrdDif(IndBand, noahmp_c) = 0.0
      noahmp%energy_flux_RadSwDifTranGrdDir(IndBand, noahmp_c) = 0.0
      noahmp%energy_flux_RadSwDifTranGrdDif(IndBand, noahmp_c) = 0.0
      noahmp%energy_flux_RadSwReflVegDir(IndBand, noahmp_c) = 0.0
      noahmp%energy_flux_RadSwReflVegDif(IndBand, noahmp_c) = 0.0
      noahmp%energy_flux_RadSwReflGrdDir(IndBand, noahmp_c) = 0.0
      noahmp%energy_flux_RadSwReflGrdDif(IndBand, noahmp_c) = 0.0
    enddo
    noahmp%energy_state_VegAreaIndEff(noahmp_c) = noahmp%energy_state_LeafAreaIndEff(noahmp_c) + noahmp%energy_state_StemAreaIndEff(noahmp_c)
    if ( noahmp%config_domain_CosSolarZenithAngle(noahmp_c) > 0 ) then
      LeafWgt = noahmp%energy_state_LeafAreaIndEff(noahmp_c) / max(noahmp%energy_state_VegAreaIndEff(noahmp_c), MinThr)
      StemWgt = noahmp%energy_state_StemAreaIndEff(noahmp_c) / max(noahmp%energy_state_VegAreaIndEff(noahmp_c), MinThr)
      do IndBand = 1, 2
        noahmp%energy_state_ReflectanceVeg(IndBand, noahmp_c) = max(noahmp%energy_param_ReflectanceLeaf(IndBand, noahmp_c)*LeafWgt+noahmp%energy_param_ReflectanceStem(IndBand, noahmp_c)*StemWgt, MinThr)
        noahmp%energy_state_TransmittanceVeg(IndBand, noahmp_c) = max(noahmp%energy_param_TransmittanceLeaf(IndBand, noahmp_c)*LeafWgt+noahmp%energy_param_TransmittanceStem(IndBand, noahmp_c)*StemWgt, MinThr)
      enddo
      call SnowAgingBats(noahmp, noahmp_c)
      call SnowAlbedoBats(noahmp, noahmp_c)
      call GroundAlbedo(noahmp, noahmp_c)
      do IndBand = 1, 2
        IndDif = 0
        call CanopyRadiationTwoStream(noahmp, noahmp_c, IndBand, IndDif)
        IndDif = 1
        call CanopyRadiationTwoStream(noahmp, noahmp_c, IndBand, IndDif)
      enddo
      LightExtDir = noahmp%energy_state_VegAreaProjDir(noahmp_c) / noahmp%config_domain_CosSolarZenithAngle(noahmp_c) * sqrt(1.0-noahmp%energy_state_ReflectanceVeg(1, noahmp_c)-noahmp%energy_state_TransmittanceVeg(1, noahmp_c))
      noahmp%energy_state_CanopySunlitFrac(noahmp_c) = (1.0 - exp(-LightExtDir*noahmp%energy_state_VegAreaIndEff(noahmp_c))) / max(LightExtDir*noahmp%energy_state_VegAreaIndEff(noahmp_c), MinThr)
      LightExtDir = noahmp%energy_state_CanopySunlitFrac(noahmp_c)
      if ( LightExtDir < 0.01 ) then
        LeafWgt = 0.0
      else
        LeafWgt = LightExtDir
      endif
      noahmp%energy_state_CanopySunlitFrac(noahmp_c) = LeafWgt
    endif
    noahmp%energy_state_CanopyShadeFrac(noahmp_c) = 1.0 - noahmp%energy_state_CanopySunlitFrac(noahmp_c)
    noahmp%energy_state_LeafAreaIndSunlit(noahmp_c) = noahmp%energy_state_LeafAreaIndEff(noahmp_c) * noahmp%energy_state_CanopySunlitFrac(noahmp_c)
    noahmp%energy_state_LeafAreaIndShade(noahmp_c) = noahmp%energy_state_LeafAreaIndEff(noahmp_c) * noahmp%energy_state_CanopyShadeFrac(noahmp_c)
  end subroutine SurfaceAlbedo
end module lean_surfacealbedomod

! Source: physics_noahmp/src/SurfaceRadiationMod.F90
module lean_surfaceradiationmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine SurfaceRadiation(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: IndBand
    real(kind=kind_noahmp) :: MinThr
    real(kind=kind_noahmp) :: RadSwAbsGrdTmp
    real(kind=kind_noahmp) :: RadSwReflSfcNir
    real(kind=kind_noahmp) :: RadSwReflSfcVis
    real(kind=kind_noahmp) :: LeafAreaIndFrac
    real(kind=kind_noahmp) :: RadSwTranGrdDir
    real(kind=kind_noahmp) :: RadSwTranGrdDif
    real(kind=kind_noahmp), dimension(1:2) :: RadSwAbsCanDir
    real(kind=kind_noahmp), dimension(1:2) :: RadSwAbsCanDif
    MinThr = 1.0e-6
    RadSwAbsCanDir = 0.0
    RadSwAbsCanDif = 0.0
    noahmp%energy_flux_RadSwAbsGrd(noahmp_c) = 0.0
    noahmp%energy_flux_RadSwAbsVeg(noahmp_c) = 0.0
    noahmp%energy_flux_RadSwAbsSfc(noahmp_c) = 0.0
    noahmp%energy_flux_RadSwReflSfc(noahmp_c) = 0.0
    noahmp%energy_flux_RadSwReflVeg(noahmp_c) = 0.0
    noahmp%energy_flux_RadSwReflGrd(noahmp_c) = 0.0
    noahmp%energy_flux_RadPhotoActAbsSunlit(noahmp_c) = 0.0
    noahmp%energy_flux_RadPhotoActAbsShade(noahmp_c) = 0.0
    do IndBand = 1, 2
      RadSwAbsCanDir(IndBand) = noahmp%energy_flux_RadSwDownDir(IndBand, noahmp_c) * noahmp%energy_flux_RadSwAbsVegDir(IndBand, noahmp_c)
      RadSwAbsCanDif(IndBand) = noahmp%energy_flux_RadSwDownDif(IndBand, noahmp_c) * noahmp%energy_flux_RadSwAbsVegDif(IndBand, noahmp_c)
      noahmp%energy_flux_RadSwAbsVeg(noahmp_c) = noahmp%energy_flux_RadSwAbsVeg(noahmp_c) + RadSwAbsCanDir(IndBand) + RadSwAbsCanDif(IndBand)
      noahmp%energy_flux_RadSwAbsSfc(noahmp_c) = noahmp%energy_flux_RadSwAbsSfc(noahmp_c) + RadSwAbsCanDir(IndBand) + RadSwAbsCanDif(IndBand)
      RadSwTranGrdDir = noahmp%energy_flux_RadSwDownDir(IndBand, noahmp_c) * noahmp%energy_flux_RadSwDirTranGrdDir(IndBand, noahmp_c)
      RadSwTranGrdDif = noahmp%energy_flux_RadSwDownDir(IndBand, noahmp_c) * noahmp%energy_flux_RadSwDifTranGrdDir(IndBand, noahmp_c) + noahmp%energy_flux_RadSwDownDif(IndBand, noahmp_c) * noahmp%energy_flux_RadSwDifTranGrdDif(IndBand, noahmp_c)
      RadSwAbsGrdTmp = RadSwTranGrdDir * (1.0 - noahmp%energy_state_AlbedoGrdDir(IndBand, noahmp_c)) + RadSwTranGrdDif * (1.0 - noahmp%energy_state_AlbedoGrdDif(IndBand, noahmp_c))
      noahmp%energy_flux_RadSwAbsGrd(noahmp_c) = noahmp%energy_flux_RadSwAbsGrd(noahmp_c) + RadSwAbsGrdTmp
      noahmp%energy_flux_RadSwAbsSfc(noahmp_c) = noahmp%energy_flux_RadSwAbsSfc(noahmp_c) + RadSwAbsGrdTmp
    enddo
    LeafAreaIndFrac = noahmp%energy_state_LeafAreaIndEff(noahmp_c) / max(noahmp%energy_state_VegAreaIndEff(noahmp_c), MinThr)
    if ( noahmp%energy_state_CanopySunlitFrac(noahmp_c) > 0.0 ) then
      noahmp%energy_flux_RadPhotoActAbsSunlit(noahmp_c) = (RadSwAbsCanDir(1) + noahmp%energy_state_CanopySunlitFrac(noahmp_c) * RadSwAbsCanDif(1)) * LeafAreaIndFrac / max(noahmp%energy_state_LeafAreaIndSunlit(noahmp_c), MinThr)
      noahmp%energy_flux_RadPhotoActAbsShade(noahmp_c) = (noahmp%energy_state_CanopyShadeFrac(noahmp_c) * RadSwAbsCanDif(1)) * LeafAreaIndFrac / max(noahmp%energy_state_LeafAreaIndShade(noahmp_c), MinThr)
    else
      noahmp%energy_flux_RadPhotoActAbsSunlit(noahmp_c) = 0.0
      noahmp%energy_flux_RadPhotoActAbsShade(noahmp_c) = (RadSwAbsCanDir(1) + RadSwAbsCanDif(1)) * LeafAreaIndFrac / max(noahmp%energy_state_LeafAreaIndShade(noahmp_c), &
        & MinThr)
    endif
    RadSwReflSfcVis = noahmp%energy_state_AlbedoSfcDir(1, noahmp_c) * noahmp%energy_flux_RadSwDownDir(1, noahmp_c) + noahmp%energy_state_AlbedoSfcDif(1, noahmp_c) * noahmp%energy_flux_RadSwDownDif(1, noahmp_c)
    RadSwReflSfcNir = noahmp%energy_state_AlbedoSfcDir(2, noahmp_c) * noahmp%energy_flux_RadSwDownDir(2, noahmp_c) + noahmp%energy_state_AlbedoSfcDif(2, noahmp_c) * noahmp%energy_flux_RadSwDownDif(2, noahmp_c)
    noahmp%energy_flux_RadSwReflSfc(noahmp_c) = RadSwReflSfcVis + RadSwReflSfcNir
    noahmp%energy_flux_RadSwReflVeg(noahmp_c) = noahmp%energy_flux_RadSwReflVegDir(1, noahmp_c)*noahmp%energy_flux_RadSwDownDir(1, noahmp_c) + noahmp%energy_flux_RadSwReflVegDif(1, noahmp_c)*noahmp%energy_flux_RadSwDownDif(1, noahmp_c) + noahmp%energy_flux_RadSwReflVegDir(2, noahmp_c)*noahmp%energy_flux_RadSwDownDir(2, noahmp_c) + noahmp%energy_flux_RadSwReflVegDif(2, noahmp_c)*noahmp%energy_flux_RadSwDownDif(2, noahmp_c)
    noahmp%energy_flux_RadSwReflGrd(noahmp_c) = noahmp%energy_flux_RadSwReflGrdDir(1, noahmp_c)*noahmp%energy_flux_RadSwDownDir(1, noahmp_c) + noahmp%energy_flux_RadSwReflGrdDif(1, noahmp_c)*noahmp%energy_flux_RadSwDownDif(1, noahmp_c) + noahmp%energy_flux_RadSwReflGrdDir(2, noahmp_c)*noahmp%energy_flux_RadSwDownDir(2, noahmp_c) + noahmp%energy_flux_RadSwReflGrdDif(2, noahmp_c)*noahmp%energy_flux_RadSwDownDif(2, noahmp_c)
  end subroutine SurfaceRadiation
end module lean_surfaceradiationmod

! Source: physics_noahmp/src/SurfaceEmissivityMod.F90
module lean_surfaceemissivitymod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine SurfaceEmissivity(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    noahmp%energy_state_EmissivityVeg(noahmp_c) = 1.0 - exp(-(noahmp%energy_state_LeafAreaIndEff(noahmp_c) + noahmp%energy_state_StemAreaIndEff(noahmp_c)) / 1.0)
    noahmp%energy_state_EmissivityGrd(noahmp_c) = noahmp%energy_param_EmissivitySoilLake(1, noahmp_c) * (1.0-noahmp%water_state_SnowCoverFrac(noahmp_c)) + noahmp%energy_param_EmissivitySnow(noahmp_c) * noahmp%water_state_SnowCoverFrac(noahmp_c)
    noahmp%energy_state_EmissivitySfc(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * (noahmp%energy_state_EmissivityGrd(noahmp_c)*(1-noahmp%energy_state_EmissivityVeg(noahmp_c)) + noahmp%energy_state_EmissivityVeg(noahmp_c) + noahmp%energy_state_EmissivityVeg(noahmp_c)*(1-noahmp%energy_state_EmissivityVeg(noahmp_c))*(1-noahmp%energy_state_EmissivityGrd(noahmp_c))) + (1-noahmp%energy_state_VegFrac(noahmp_c)) * noahmp%energy_state_EmissivityGrd(noahmp_c)
  end subroutine SurfaceEmissivity
end module lean_surfaceemissivitymod

! Source: physics_noahmp/src/SoilWaterTranspirationMod.F90
module lean_soilwatertranspirationmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine SoilWaterTranspiration(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: IndSoil
    real(kind=kind_noahmp) :: SoilWetFac
    real(kind=kind_noahmp) :: MinThr
    MinThr = 1.0e-6
    noahmp%water_state_SoilTranspFacAcc(noahmp_c) = 0.0
    do IndSoil = 1, noahmp%water_param_NumSoilLayerRoot(noahmp_c)
      SoilWetFac = (noahmp%water_state_SoilLiqWater(IndSoil, noahmp_c) - noahmp%water_param_SoilMoistureWilt(IndSoil, noahmp_c)) / (noahmp%water_param_SoilMoistureFieldCap(IndSoil, noahmp_c) - noahmp%water_param_SoilMoistureWilt(IndSoil, noahmp_c))
      SoilWetFac = min(1.0, max(0.0,SoilWetFac))
      noahmp%water_state_SoilTranspFac(IndSoil, noahmp_c) = max(MinThr, &
        & noahmp%config_domain_ThicknessSnowSoilLayer(IndSoil, noahmp_c) / (-noahmp%config_domain_DepthSoilLayer(noahmp%water_param_NumSoilLayerRoot(noahmp_c), noahmp_c)) * SoilWetFac)
      noahmp%water_state_SoilTranspFacAcc(noahmp_c) = noahmp%water_state_SoilTranspFacAcc(noahmp_c) + noahmp%water_state_SoilTranspFac(IndSoil, noahmp_c)
    enddo
    noahmp%water_state_SoilTranspFacAcc(noahmp_c) = max(MinThr, noahmp%water_state_SoilTranspFacAcc(noahmp_c))
    noahmp%water_state_SoilTranspFac(1:noahmp%water_param_NumSoilLayerRoot(noahmp_c), noahmp_c) = noahmp%water_state_SoilTranspFac(1:noahmp%water_param_NumSoilLayerRoot(noahmp_c), noahmp_c) / noahmp%water_state_SoilTranspFacAcc(noahmp_c)
  end subroutine SoilWaterTranspiration
end module lean_soilwatertranspirationmod

! Source: physics_noahmp/src/ResistanceGroundEvaporationMod.F90
module lean_resistancegroundevaporationmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine ResistanceGroundEvaporation(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    real(kind=kind_noahmp) :: SoilEvapFac
    real(kind=kind_noahmp) :: DrySoilThickness
    real(kind=kind_noahmp) :: VapDiffuseRed
    real(kind=kind_noahmp) :: SoilMatPotentialSfc
    SoilEvapFac = max(0.0, noahmp%water_state_SoilLiqWater(1, noahmp_c)/noahmp%water_param_SoilMoistureSat(1, noahmp_c))
    DrySoilThickness = (-noahmp%config_domain_DepthSoilLayer(1, noahmp_c)) * (exp((1.0 - min(1.0, &
      & noahmp%water_state_SoilLiqWater(1, noahmp_c)/noahmp%water_param_SoilMoistureSat(1, noahmp_c))) ** noahmp%energy_param_ResistanceSoilExp(noahmp_c)) - 1.0) / (2.71828-1.0)
    VapDiffuseRed = 2.2e-5 * noahmp%water_param_SoilMoistureSat(1, noahmp_c) * noahmp%water_param_SoilMoistureSat(1, noahmp_c) * (1.0 - noahmp%water_param_SoilMoistureWilt(1, noahmp_c)/noahmp%water_param_SoilMoistureSat(1, noahmp_c)) ** (2.0 + 3.0/noahmp%water_param_SoilExpCoeffB(1, noahmp_c))
#ifdef LEAN_NOAHMP_RSF3
    ! Lean departure (build switch LEAN_NOAHMP_RSF3, on in flavor lean, off in mpas; docs/fixes.md): the soil part of MPAS's option 4
    ! resistance uses Noah-MP's option 3 (Sellers 1992 adjusted to a lower resistance over wet soil) instead of Sakaguchi and Zeng;
    ! option 4's snow weighting below stays.
    noahmp%energy_state_ResistanceGrdEvap(noahmp_c) = exp(8.25 - 6.0*SoilEvapFac)
#else
    noahmp%energy_state_ResistanceGrdEvap(noahmp_c) = DrySoilThickness / VapDiffuseRed
#endif
    noahmp%energy_state_ResistanceGrdEvap(noahmp_c) = 1.0 / (noahmp%water_state_SnowCoverFrac(noahmp_c) * (1.0/noahmp%energy_param_ResistanceSnowSfc(noahmp_c)) + (1.0-noahmp%water_state_SnowCoverFrac(noahmp_c)) * (1.0/max(noahmp%energy_state_ResistanceGrdEvap(noahmp_c),0.001)))
    if ( (noahmp%water_state_SoilLiqWater(1, noahmp_c) < 0.01) .and. (noahmp%water_state_SnowDepth(noahmp_c) == 0.0) ) noahmp%energy_state_ResistanceGrdEvap(noahmp_c) = 1.0e6
    SoilMatPotentialSfc = -noahmp%water_param_SoilMatPotentialSat(1, noahmp_c) * (max(0.01, &
      & noahmp%water_state_SoilLiqWater(1, noahmp_c)) / noahmp%water_param_SoilMoistureSat(1, noahmp_c)) ** (-noahmp%water_param_SoilExpCoeffB(1, noahmp_c))
    noahmp%energy_state_RelHumidityGrd(noahmp_c) = noahmp%water_state_SnowCoverFrac(noahmp_c) + (1.0-noahmp%water_state_SnowCoverFrac(noahmp_c)) * exp(SoilMatPotentialSfc*ConstGravityAcc/(ConstGasWaterVapor*noahmp%energy_state_TemperatureGrd(noahmp_c)))
    if ( (noahmp%config_domain_FlagUrban(noahmp_c) .eqv. .true.) .and. (noahmp%water_state_SnowDepth(noahmp_c) == 0.0) ) then
      noahmp%energy_state_ResistanceGrdEvap(noahmp_c) = 1.0e6
    endif
  end subroutine ResistanceGroundEvaporation
end module lean_resistancegroundevaporationmod

! Source: physics_noahmp/src/PsychrometricVariableMod.F90
module lean_psychrometricvariablemod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine PsychrometricVariable(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    if ( noahmp%energy_state_TemperatureCanopy(noahmp_c) > ConstFreezePoint ) then
      noahmp%energy_state_LatHeatVapCanopy(noahmp_c) = ConstLatHeatEvap
      noahmp%energy_state_FlagFrozenCanopy(noahmp_c) = .false.
    else
      noahmp%energy_state_LatHeatVapCanopy(noahmp_c) = ConstLatHeatSublim
      noahmp%energy_state_FlagFrozenCanopy(noahmp_c) = .true.
    endif
    noahmp%energy_state_PsychConstCanopy(noahmp_c) = ConstHeatCapacAir * noahmp%forcing_PressureAirRefHeight(noahmp_c) / (0.622*noahmp%energy_state_LatHeatVapCanopy(noahmp_c))
    if ( noahmp%energy_state_TemperatureGrd(noahmp_c) > ConstFreezePoint ) then
      noahmp%energy_state_LatHeatVapGrd(noahmp_c) = ConstLatHeatEvap
      noahmp%energy_state_FlagFrozenGround(noahmp_c) = .false.
    else
      noahmp%energy_state_LatHeatVapGrd(noahmp_c) = ConstLatHeatSublim
      noahmp%energy_state_FlagFrozenGround(noahmp_c) = .true.
    endif
    noahmp%energy_state_PsychConstGrd(noahmp_c) = ConstHeatCapacAir * noahmp%forcing_PressureAirRefHeight(noahmp_c) / (0.622*noahmp%energy_state_LatHeatVapGrd(noahmp_c))
  end subroutine PsychrometricVariable
end module lean_psychrometricvariablemod

! Source: physics_noahmp/src/VaporPressureSaturationMod.F90
module lean_vaporpressuresaturationmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine VaporPressureSaturation(T, VapPresSatWat, VapPresSatIce, VapPresSatWatD, VapPresSatIceD)
 !$acc routine seq
    implicit none
    real(kind=kind_noahmp), intent(in) :: T
    real(kind=kind_noahmp), intent(out) :: VapPresSatWat
    real(kind=kind_noahmp), intent(out) :: VapPresSatIce
    real(kind=kind_noahmp), intent(out) :: VapPresSatWatD
    real(kind=kind_noahmp), intent(out) :: VapPresSatIceD
    real(kind=kind_noahmp), parameter :: A0 = 6.107799961
    real(kind=kind_noahmp), parameter :: A1 = 4.436518521e-01
    real(kind=kind_noahmp), parameter :: A2 = 1.428945805e-02
    real(kind=kind_noahmp), parameter :: A3 = 2.650648471e-04
    real(kind=kind_noahmp), parameter :: A4 = 3.031240396e-06
    real(kind=kind_noahmp), parameter :: A5 = 2.034080948e-08
    real(kind=kind_noahmp), parameter :: A6 = 6.136820929e-11
    real(kind=kind_noahmp), parameter :: B0 = 6.109177956
    real(kind=kind_noahmp), parameter :: B1 = 5.034698970e-01
    real(kind=kind_noahmp), parameter :: B2 = 1.886013408e-02
    real(kind=kind_noahmp), parameter :: B3 = 4.176223716e-04
    real(kind=kind_noahmp), parameter :: B4 = 5.824720280e-06
    real(kind=kind_noahmp), parameter :: B5 = 4.838803174e-08
    real(kind=kind_noahmp), parameter :: B6 = 1.838826904e-10
    real(kind=kind_noahmp), parameter :: C0 = 4.438099984e-01
    real(kind=kind_noahmp), parameter :: C1 = 2.857002636e-02
    real(kind=kind_noahmp), parameter :: C2 = 7.938054040e-04
    real(kind=kind_noahmp), parameter :: C3 = 1.215215065e-05
    real(kind=kind_noahmp), parameter :: C4 = 1.036561403e-07
    real(kind=kind_noahmp), parameter :: C5 = 3.532421810e-10
    real(kind=kind_noahmp), parameter :: C6 = -7.090244804e-13
    real(kind=kind_noahmp), parameter :: D0 = 5.030305237e-01
    real(kind=kind_noahmp), parameter :: D1 = 3.773255020e-02
    real(kind=kind_noahmp), parameter :: D2 = 1.267995369e-03
    real(kind=kind_noahmp), parameter :: D3 = 2.477563108e-05
    real(kind=kind_noahmp), parameter :: D4 = 3.005693132e-07
    real(kind=kind_noahmp), parameter :: D5 = 2.158542548e-09
    real(kind=kind_noahmp), parameter :: D6 = 7.131097725e-12
    VapPresSatWat = 100.0 * (A0 + T * (A1 + T * (A2 + T * (A3 + T * ( A4 + T * (A5 + T*A6) ) ) ) ) )
    VapPresSatIce = 100.0 * (B0 + T * (B1 + T * (B2 + T * (B3 + T * ( B4 + T * (B5 + T*B6) ) ) ) ) )
    VapPresSatWatD = 100.0 * (C0 + T * (C1 + T * (C2 + T * (C3 + T * ( C4 + T * (C5 + T*C6) ) ) ) ) )
    VapPresSatIceD = 100.0 * (D0 + T * (D1 + T * (D2 + T * (D3 + T * ( D4 + T * (D5 + T*D6) ) ) ) ) )
  end subroutine VaporPressureSaturation
end module lean_vaporpressuresaturationmod

! Source: physics_noahmp/src/ResistanceAboveCanopyMostMod.F90
module lean_resistanceabovecanopymostmod
 use lean_phys_fault, only: physics_fault
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine ResistanceAboveCanopyMOST(noahmp, noahmp_c, IterationInd, HeatSensibleTmp, MoStabParaSgn)
 !$acc routine seq
    implicit none
    integer , intent(in ) :: IterationInd
    integer , intent(inout) :: MoStabParaSgn
    real(kind=kind_noahmp), intent(in ) :: HeatSensibleTmp
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    real(kind=kind_noahmp) :: MPE
    real(kind=kind_noahmp) :: TMPCM
    real(kind=kind_noahmp) :: TMPCH
    real(kind=kind_noahmp) :: FMNEW
    real(kind=kind_noahmp) :: FHNEW
    real(kind=kind_noahmp) :: MOZOLD
    real(kind=kind_noahmp) :: TMP1,TMP2,TMP3,TMP4,TMP5
    real(kind=kind_noahmp) :: TVIR
    real(kind=kind_noahmp) :: TMPCM2
    real(kind=kind_noahmp) :: TMPCH2
    real(kind=kind_noahmp) :: FM2NEW
    real(kind=kind_noahmp) :: FH2NEW
    real(kind=kind_noahmp) :: TMP12,TMP22,TMP32
    real(kind=kind_noahmp) :: CMFM, CHFH, CM2FM2, CH2FH2
    MPE = 1.0e-6
    MOZOLD = noahmp%energy_state_MoStabParaAbvCan(noahmp_c)
    if ( noahmp%energy_state_RefHeightAboveGrd(noahmp_c) <= noahmp%energy_state_ZeroPlaneDispSfc(noahmp_c) ) then
      call physics_fault(4)
    endif
    TMPCM = log((noahmp%energy_state_RefHeightAboveGrd(noahmp_c) - noahmp%energy_state_ZeroPlaneDispSfc(noahmp_c)) / noahmp%energy_state_RoughLenMomSfc(noahmp_c))
    TMPCH = log((noahmp%energy_state_RefHeightAboveGrd(noahmp_c) - noahmp%energy_state_ZeroPlaneDispSfc(noahmp_c)) / noahmp%energy_state_RoughLenShCanopy(noahmp_c))
    TMPCM2 = log((2.0 + noahmp%energy_state_RoughLenMomSfc(noahmp_c)) / noahmp%energy_state_RoughLenMomSfc(noahmp_c))
    TMPCH2 = log((2.0 + noahmp%energy_state_RoughLenShCanopy(noahmp_c)) / noahmp%energy_state_RoughLenShCanopy(noahmp_c))
    if ( IterationInd == 1 ) then
      noahmp%energy_state_FrictionVelVeg(noahmp_c) = 0.0
      noahmp%energy_state_MoStabParaAbvCan(noahmp_c) = 0.0
      noahmp%energy_state_MoLengthAbvCan(noahmp_c) = 0.0
      noahmp%energy_state_MoStabParaVeg2m(noahmp_c) = 0.0
    else
      TVIR = (1.0 + 0.61*noahmp%forcing_SpecHumidityRefHeight(noahmp_c)) * noahmp%forcing_TemperatureAirRefHeight(noahmp_c)
      TMP1 = ConstVonKarman * (ConstGravityAcc/TVIR) * HeatSensibleTmp / (noahmp%energy_state_DensityAirRefHeight(noahmp_c)*ConstHeatCapacAir)
      if ( abs(TMP1) <= MPE ) TMP1 = MPE
      noahmp%energy_state_MoLengthAbvCan(noahmp_c) = -1.0 * noahmp%energy_state_FrictionVelVeg(noahmp_c)**3 / TMP1
      noahmp%energy_state_MoStabParaAbvCan(noahmp_c) = min((noahmp%energy_state_RefHeightAboveGrd(noahmp_c) - noahmp%energy_state_ZeroPlaneDispSfc(noahmp_c)) / noahmp%energy_state_MoLengthAbvCan(noahmp_c), 1.0)
#ifdef LEAN_NOAHMP_T2Z
      ! Lean departure (build switch LEAN_NOAHMP_T2Z, on in flavor lean, off in mpas; docs/fixes.md): MPAS caps z/L at 1 at the first
      ! level and at 2 m apart, from the same L. Past the cap the flux acts as if L = z, while 2 m still sees the true short L, so
      ! as a calm night grows more stable T2 turns back from the surface towards the first level. Here 2 m takes the capped L of
      ! the flux. In unstable air, with no cap, this is the same number. T2 and Q2 only: nothing else reads the 2 m values.
      noahmp%energy_state_MoStabParaVeg2m(noahmp_c) = noahmp%energy_state_MoStabParaAbvCan(noahmp_c) * (2.0 + noahmp%energy_state_RoughLenShCanopy(noahmp_c)) / (noahmp%energy_state_RefHeightAboveGrd(noahmp_c) - noahmp%energy_state_ZeroPlaneDispSfc(noahmp_c))
#else
      noahmp%energy_state_MoStabParaVeg2m(noahmp_c) = min((2.0 + noahmp%energy_state_RoughLenShCanopy(noahmp_c)) / noahmp%energy_state_MoLengthAbvCan(noahmp_c), 1.0)
#endif
    endif
    if ( MOZOLD*noahmp%energy_state_MoStabParaAbvCan(noahmp_c) < 0.0 ) MoStabParaSgn = MoStabParaSgn + 1
    if ( MoStabParaSgn >= 2 ) then
      noahmp%energy_state_MoStabParaAbvCan(noahmp_c) = 0.0
      noahmp%energy_state_MoStabCorrMomAbvCan(noahmp_c) = 0.0
      noahmp%energy_state_MoStabCorrShAbvCan(noahmp_c) = 0.0
      noahmp%energy_state_MoStabParaVeg2m(noahmp_c) = 0.0
      noahmp%energy_state_MoStabCorrMomVeg2m(noahmp_c) = 0.0
      noahmp%energy_state_MoStabCorrShVeg2m(noahmp_c) = 0.0
    endif
    if ( noahmp%energy_state_MoStabParaAbvCan(noahmp_c) < 0.0 ) then
      TMP1 = (1.0 - 16.0 * noahmp%energy_state_MoStabParaAbvCan(noahmp_c))**0.25
      TMP2 = log((1.0 + TMP1*TMP1) / 2.0)
      TMP3 = log((1.0 + TMP1) / 2.0)
      FMNEW = 2.0 * TMP3 + TMP2 - 2.0 * atan(TMP1) + 1.5707963
      FHNEW = 2 * TMP2
      TMP12 = (1.0 - 16.0 * noahmp%energy_state_MoStabParaVeg2m(noahmp_c))**0.25
      TMP22 = log((1.0 + TMP12*TMP12) / 2.0)
      TMP32 = log((1.0 + TMP12) / 2.0)
      FM2NEW = 2.0 * TMP32 + TMP22 - 2.0 * atan(TMP12) + 1.5707963
      FH2NEW = 2 * TMP22
    else
      FMNEW = -5.0 * noahmp%energy_state_MoStabParaAbvCan(noahmp_c)
      FHNEW = FMNEW
      FM2NEW = -5.0 * noahmp%energy_state_MoStabParaVeg2m(noahmp_c)
      FH2NEW = FM2NEW
    endif
    if ( IterationInd == 1 ) then
      noahmp%energy_state_MoStabCorrMomAbvCan(noahmp_c) = FMNEW
      noahmp%energy_state_MoStabCorrShAbvCan(noahmp_c) = FHNEW
      noahmp%energy_state_MoStabCorrMomVeg2m(noahmp_c) = FM2NEW
      noahmp%energy_state_MoStabCorrShVeg2m(noahmp_c) = FH2NEW
    else
      noahmp%energy_state_MoStabCorrMomAbvCan(noahmp_c) = 0.5 * (noahmp%energy_state_MoStabCorrMomAbvCan(noahmp_c) + FMNEW)
      noahmp%energy_state_MoStabCorrShAbvCan(noahmp_c) = 0.5 * (noahmp%energy_state_MoStabCorrShAbvCan(noahmp_c) + FHNEW)
      noahmp%energy_state_MoStabCorrMomVeg2m(noahmp_c) = 0.5 * (noahmp%energy_state_MoStabCorrMomVeg2m(noahmp_c) + FM2NEW)
      noahmp%energy_state_MoStabCorrShVeg2m(noahmp_c) = 0.5 * (noahmp%energy_state_MoStabCorrShVeg2m(noahmp_c) + FH2NEW)
    endif
    noahmp%energy_state_MoStabCorrShAbvCan(noahmp_c) = min(noahmp%energy_state_MoStabCorrShAbvCan(noahmp_c) , 0.9*TMPCH)
    noahmp%energy_state_MoStabCorrMomAbvCan(noahmp_c) = min(noahmp%energy_state_MoStabCorrMomAbvCan(noahmp_c), 0.9*TMPCM)
    noahmp%energy_state_MoStabCorrShVeg2m(noahmp_c) = min(noahmp%energy_state_MoStabCorrShVeg2m(noahmp_c) , 0.9*TMPCH2)
    noahmp%energy_state_MoStabCorrMomVeg2m(noahmp_c) = min(noahmp%energy_state_MoStabCorrMomVeg2m(noahmp_c) , 0.9*TMPCM2)
    CMFM = TMPCM - noahmp%energy_state_MoStabCorrMomAbvCan(noahmp_c)
    CHFH = TMPCH - noahmp%energy_state_MoStabCorrShAbvCan(noahmp_c)
    CM2FM2 = TMPCM2 - noahmp%energy_state_MoStabCorrMomVeg2m(noahmp_c)
    CH2FH2 = TMPCH2 - noahmp%energy_state_MoStabCorrShVeg2m(noahmp_c)
    if ( abs(CMFM) <= MPE ) CMFM = MPE
    if ( abs(CHFH) <= MPE ) CHFH = MPE
    if ( abs(CM2FM2) <= MPE ) CM2FM2 = MPE
    if ( abs(CH2FH2) <= MPE ) CH2FH2 = MPE
    noahmp%energy_state_ExchCoeffMomAbvCan(noahmp_c) = ConstVonKarman * ConstVonKarman / (CMFM * CMFM)
    noahmp%energy_state_ExchCoeffShAbvCan(noahmp_c) = ConstVonKarman * ConstVonKarman / (CMFM * CHFH)
    noahmp%energy_state_FrictionVelVeg(noahmp_c) = noahmp%energy_state_WindSpdRefHeight(noahmp_c) * sqrt(noahmp%energy_state_ExchCoeffMomAbvCan(noahmp_c))
    noahmp%energy_state_ExchCoeffSh2mVegMo(noahmp_c) = ConstVonKarman * noahmp%energy_state_FrictionVelVeg(noahmp_c) / CH2FH2
    noahmp%energy_state_ResistanceMomAbvCan(noahmp_c) = max(1.0, 1.0/(noahmp%energy_state_ExchCoeffMomAbvCan(noahmp_c)*noahmp%energy_state_WindSpdRefHeight(noahmp_c)))
    noahmp%energy_state_ResistanceShAbvCan(noahmp_c) = max(1.0, 1.0/(noahmp%energy_state_ExchCoeffShAbvCan(noahmp_c)*noahmp%energy_state_WindSpdRefHeight(noahmp_c)))
    noahmp%energy_state_ResistanceLhAbvCan(noahmp_c) = noahmp%energy_state_ResistanceShAbvCan(noahmp_c)
  end subroutine ResistanceAboveCanopyMOST
end module lean_resistanceabovecanopymostmod

! Also from: physics_noahmp/src/ResistanceAboveCanopyChen97Mod.F90
module lean_resistanceabovecanopychen97mod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine ResistanceAboveCanopyChen97(noahmp, noahmp_c, IterationInd)
 !$acc routine seq
    implicit none
    integer , intent(in ) :: IterationInd
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: ILECH, ITR
    real(kind=kind_noahmp) :: ZZ, PSLMU, PSLMS, PSLHU, PSLHS
    real(kind=kind_noahmp) :: XX, PSPMU, YY, PSPMS, PSPHU, PSPHS
    real(kind=kind_noahmp) :: ZILFC, ZU, ZT, RDZ, CXCH, DTHV, DU2
    real(kind=kind_noahmp) :: BTGH, ZSLU, ZSLT, RLOGU, RLOGT, RLMA
    real(kind=kind_noahmp) :: ZETALT, ZETALU, ZETAU, ZETAT, XLU4
    real(kind=kind_noahmp) :: XLT4, XU4, XT4, XLU, XLT, XU, XT
    real(kind=kind_noahmp) :: PSMZ, SIMM, PSHZ, SIMH, USTARK, RLMN
    integer , parameter :: ITRMX = 5
    real(kind=kind_noahmp), parameter :: WWST = 1.2
    real(kind=kind_noahmp), parameter :: WWST2 = WWST * WWST
    real(kind=kind_noahmp), parameter :: VKRM = 0.40
    real(kind=kind_noahmp), parameter :: EXCM = 0.001
    real(kind=kind_noahmp), parameter :: BETA = 1.0 / 270.0
    real(kind=kind_noahmp), parameter :: BTG = BETA * ConstGravityAcc
    real(kind=kind_noahmp), parameter :: ELFC = VKRM * BTG
    real(kind=kind_noahmp), parameter :: WOLD = 0.15
    real(kind=kind_noahmp), parameter :: WNEW = 1.0 - WOLD
    real(kind=kind_noahmp), parameter :: PIHF = 3.14159265 / 2.0
    real(kind=kind_noahmp), parameter :: EPSU2 = 1.0e-4
    real(kind=kind_noahmp), parameter :: EPSUST = 0.07
    real(kind=kind_noahmp), parameter :: EPSIT = 1.0e-4
    real(kind=kind_noahmp), parameter :: EPSA = 1.0e-8
    real(kind=kind_noahmp), parameter :: ZTMIN = -5.0
    real(kind=kind_noahmp), parameter :: ZTMAX = 1.0
    real(kind=kind_noahmp), parameter :: HPBL = 1000.0
    real(kind=kind_noahmp), parameter :: SQVISC = 258.2
    real(kind=kind_noahmp), parameter :: RIC = 0.183
    real(kind=kind_noahmp), parameter :: RRIC = 1.0 / RIC
    real(kind=kind_noahmp), parameter :: FHNEU = 0.8
    real(kind=kind_noahmp), parameter :: RFC = 0.191
    real(kind=kind_noahmp), parameter :: RFAC = RIC / ( FHNEU * RFC * RFC )
    PSLMU(ZZ) = -0.96 * log(1.0 - 4.5 * ZZ)
    PSLMS(ZZ) = ZZ * RRIC - 2.076 * (1.0 - 1.0/(ZZ + 1.0))
    PSLHU(ZZ) = -0.96 * log(1.0 - 4.5 * ZZ)
    PSLHS(ZZ) = ZZ * RFAC - 2.076 * (1.0 - 1.0/(ZZ + 1.0))
    PSPMU(XX) = -2.0*log( (XX+1.0)*0.5 ) - log( (XX*XX+1.0)*0.5 ) + 2.0*atan(XX) - PIHF
    PSPMS(YY) = 5.0 * YY
    PSPHU(XX) = -2.0 * log( (XX*XX + 1.0)*0.5 )
    PSPHS(YY) = 5.0 * YY
    ILECH = 0
    ZILFC = -noahmp%energy_param_ZilitinkevichCoeff(noahmp_c) * VKRM * SQVISC
    ZU = noahmp%energy_state_RoughLenMomSfc(noahmp_c)
    RDZ = 1.0 / noahmp%energy_state_RefHeightAboveGrd(noahmp_c)
    CXCH = EXCM * RDZ
    DTHV = noahmp%energy_state_TemperaturePotRefHeight(noahmp_c) - noahmp%energy_state_TemperatureCanopyAir(noahmp_c)
    DU2 = max(noahmp%energy_state_WindSpdRefHeight(noahmp_c)*noahmp%energy_state_WindSpdRefHeight(noahmp_c), EPSU2)
    BTGH = BTG * HPBL
    if ( IterationInd == 1 ) then
      if ( (BTGH*noahmp%energy_state_ExchCoeffShAbvCan(noahmp_c)*DTHV) /= 0.0 ) then
        noahmp%energy_state_FrictionVelVertVeg(noahmp_c) = WWST2 * abs(BTGH*noahmp%energy_state_ExchCoeffShAbvCan(noahmp_c)*DTHV)**(2.0/3.0)
      else
        noahmp%energy_state_FrictionVelVertVeg(noahmp_c) = 0.0
      endif
      noahmp%energy_state_FrictionVelVeg(noahmp_c) = max(sqrt(noahmp%energy_state_ExchCoeffMomAbvCan(noahmp_c)*sqrt(DU2+noahmp%energy_state_FrictionVelVertVeg(noahmp_c))), EPSUST)
      noahmp%energy_state_MoStabParaAbvCan(noahmp_c) = ELFC * noahmp%energy_state_ExchCoeffShAbvCan(noahmp_c) * DTHV / noahmp%energy_state_FrictionVelVeg(noahmp_c)**3
    endif
    ZT = max(1.0e-6, exp(ZILFC*sqrt(noahmp%energy_state_FrictionVelVeg(noahmp_c)*noahmp%energy_state_RoughLenMomSfc(noahmp_c)))*noahmp%energy_state_RoughLenMomSfc(noahmp_c))
    ZSLU = noahmp%energy_state_RefHeightAboveGrd(noahmp_c) + ZU
    ZSLT = noahmp%energy_state_RefHeightAboveGrd(noahmp_c) + ZT
    RLOGU = log(ZSLU/ZU)
    RLOGT = log(ZSLT/ZT)
    ZETALT = max(ZSLT*noahmp%energy_state_MoStabParaAbvCan(noahmp_c), ZTMIN)
    noahmp%energy_state_MoStabParaAbvCan(noahmp_c) = ZETALT / ZSLT
    ZETALU = ZSLU * noahmp%energy_state_MoStabParaAbvCan(noahmp_c)
    ZETAU = ZU * noahmp%energy_state_MoStabParaAbvCan(noahmp_c)
    ZETAT = ZT * noahmp%energy_state_MoStabParaAbvCan(noahmp_c)
    if ( ILECH == 0 ) then
      if ( noahmp%energy_state_MoStabParaAbvCan(noahmp_c) < 0.0 ) then
        XLU4 = 1.0 - 16.0 * ZETALU
        XLT4 = 1.0 - 16.0 * ZETALT
        XU4 = 1.0 - 16.0 * ZETAU
        XT4 = 1.0 - 16.0 * ZETAT
        XLU = sqrt(sqrt(XLU4))
        XLT = sqrt(sqrt(XLT4))
        XU = sqrt(sqrt(XU4))
        XT = sqrt(sqrt(XT4))
        PSMZ = PSPMU(XU)
        SIMM = PSPMU(XLU) - PSMZ + RLOGU
        PSHZ = PSPHU(XT)
        SIMH = PSPHU(XLT) - PSHZ + RLOGT
      else
        ZETALU = min(ZETALU, ZTMAX)
        ZETALT = min(ZETALT, ZTMAX)
        ZETAU = min(ZETAU, ZTMAX/(ZSLU/ZU))
        ZETAT = min(ZETAT, ZTMAX/(ZSLT/ZT))
        PSMZ = PSPMS(ZETAU)
        SIMM = PSPMS(ZETALU) - PSMZ + RLOGU
        PSHZ = PSPHS(ZETAT)
        SIMH = PSPHS(ZETALT) - PSHZ + RLOGT
      endif
    else
      if ( noahmp%energy_state_MoStabParaAbvCan(noahmp_c) < 0.0 ) then
        PSMZ = PSLMU(ZETAU)
        SIMM = PSLMU(ZETALU) - PSMZ + RLOGU
        PSHZ = PSLHU(ZETAT)
        SIMH = PSLHU(ZETALT) - PSHZ + RLOGT
      else
        ZETALU = min(ZETALU, ZTMAX)
        ZETALT = min(ZETALT, ZTMAX)
        PSMZ = PSLMS(ZETAU)
        SIMM = PSLMS(ZETALU) - PSMZ + RLOGU
        PSHZ = PSLHS(ZETAT)
        SIMH = PSLHS(ZETALT) - PSHZ + RLOGT
      endif
    endif
    noahmp%energy_state_FrictionVelVeg(noahmp_c) = max(sqrt(noahmp%energy_state_ExchCoeffMomAbvCan(noahmp_c)*sqrt(DU2+noahmp%energy_state_FrictionVelVertVeg(noahmp_c))), EPSUST)
    ZT = max(1.0e-6, exp(ZILFC*sqrt(noahmp%energy_state_FrictionVelVeg(noahmp_c)*noahmp%energy_state_RoughLenMomSfc(noahmp_c)))*noahmp%energy_state_RoughLenMomSfc(noahmp_c))
    ZSLT = noahmp%energy_state_RefHeightAboveGrd(noahmp_c) + ZT
    RLOGT = log(ZSLT/ZT)
    USTARK = noahmp%energy_state_FrictionVelVeg(noahmp_c) * VKRM
    if ( SIMM < 1.0e-6 ) SIMM = 1.0e-6
    noahmp%energy_state_ExchCoeffMomAbvCan(noahmp_c) = max(USTARK/SIMM, CXCH)
    if ( SIMH < 1.0e-6 ) SIMH = 1.0e-6
    noahmp%energy_state_ExchCoeffShAbvCan(noahmp_c) = max(USTARK/SIMH, CXCH)
    if ( (BTGH*noahmp%energy_state_ExchCoeffShAbvCan(noahmp_c)*DTHV) /= 0.0 ) then
      noahmp%energy_state_FrictionVelVertVeg(noahmp_c) = WWST2 * abs(BTGH*noahmp%energy_state_ExchCoeffShAbvCan(noahmp_c)*DTHV)**(2.0/3.0)
    else
      noahmp%energy_state_FrictionVelVertVeg(noahmp_c) = 0.0
    endif
    RLMN = ELFC * noahmp%energy_state_ExchCoeffShAbvCan(noahmp_c) * DTHV / noahmp%energy_state_FrictionVelVeg(noahmp_c)**3
    RLMA = noahmp%energy_state_MoStabParaAbvCan(noahmp_c) * WOLD + RLMN * WNEW
    noahmp%energy_state_MoStabParaAbvCan(noahmp_c) = RLMA
    noahmp%energy_state_ExchCoeffShAbvCan(noahmp_c) = noahmp%energy_state_ExchCoeffShAbvCan(noahmp_c) / noahmp%energy_state_WindSpdRefHeight(noahmp_c)
    noahmp%energy_state_ExchCoeffMomAbvCan(noahmp_c) = noahmp%energy_state_ExchCoeffMomAbvCan(noahmp_c) / noahmp%energy_state_WindSpdRefHeight(noahmp_c)
    noahmp%energy_state_ResistanceMomAbvCan(noahmp_c) = max(1.0, 1.0/(noahmp%energy_state_ExchCoeffMomAbvCan(noahmp_c)*noahmp%energy_state_WindSpdRefHeight(noahmp_c)))
    noahmp%energy_state_ResistanceShAbvCan(noahmp_c) = max(1.0, 1.0/(noahmp%energy_state_ExchCoeffShAbvCan(noahmp_c)*noahmp%energy_state_WindSpdRefHeight(noahmp_c)))
    noahmp%energy_state_ResistanceLhAbvCan(noahmp_c) = noahmp%energy_state_ResistanceShAbvCan(noahmp_c)
  end subroutine ResistanceAboveCanopyChen97
end module lean_resistanceabovecanopychen97mod

! Source: physics_noahmp/src/ResistanceLeafToGroundMod.F90
module lean_resistanceleaftogroundmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine ResistanceLeafToGround(noahmp, noahmp_c, IndIter, VegAreaIndEff, HeatSenGrdTmp)
 !$acc routine seq
    implicit none
    integer , intent(in ) :: IndIter
    real(kind=kind_noahmp), intent(in ) :: HeatSenGrdTmp
    real(kind=kind_noahmp), intent(in ) :: VegAreaIndEff
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    real(kind=kind_noahmp) :: MPE
    real(kind=kind_noahmp) :: KH
    real(kind=kind_noahmp) :: TMP1
    real(kind=kind_noahmp) :: TMP2
    real(kind=kind_noahmp) :: TMPRAH2
    real(kind=kind_noahmp) :: TMPRB
    real(kind=kind_noahmp) :: FHGNEW
    MPE = 1.0e-6
    noahmp%energy_state_MoStabParaUndCan(noahmp_c) = 0.0
    noahmp%energy_state_MoLengthUndCan(noahmp_c) = 0.0
    if ( IndIter > 1 ) then
      TMP1 = ConstVonKarman * (ConstGravityAcc / noahmp%energy_state_TemperatureCanopyAir(noahmp_c)) * HeatSenGrdTmp / (noahmp%energy_state_DensityAirRefHeight(noahmp_c) * ConstHeatCapacAir)
      if ( abs(TMP1) <= MPE ) TMP1 = MPE
      noahmp%energy_state_MoLengthUndCan(noahmp_c) = -1.0 * noahmp%energy_state_FrictionVelVeg(noahmp_c)**3 / TMP1
      noahmp%energy_state_MoStabParaUndCan(noahmp_c) = min((noahmp%energy_state_ZeroPlaneDispSfc(noahmp_c)-noahmp%energy_state_RoughLenMomGrd(noahmp_c))/noahmp%energy_state_MoLengthUndCan(noahmp_c), 1.0)
    endif
    if ( noahmp%energy_state_MoStabParaUndCan(noahmp_c) < 0.0 ) then
      FHGNEW = (1.0 - 15.0 * noahmp%energy_state_MoStabParaUndCan(noahmp_c))**(-0.25)
    else
      FHGNEW = 1.0 + 4.7 * noahmp%energy_state_MoStabParaUndCan(noahmp_c)
    endif
    if ( IndIter == 1 ) then
      noahmp%energy_state_MoStabCorrShUndCan(noahmp_c) = FHGNEW
    else
      noahmp%energy_state_MoStabCorrShUndCan(noahmp_c) = 0.5 * (noahmp%energy_state_MoStabCorrShUndCan(noahmp_c) + FHGNEW)
    endif
    noahmp%energy_state_WindExtCoeffCanopy(noahmp_c) = (noahmp%energy_param_CanopyWindExtFac(noahmp_c) * VegAreaIndEff * noahmp%energy_state_CanopyHeight(noahmp_c) * noahmp%energy_state_MoStabCorrShUndCan(noahmp_c))**0.5
    TMP1 = exp(-noahmp%energy_state_WindExtCoeffCanopy(noahmp_c) * noahmp%energy_state_RoughLenShVegGrd(noahmp_c) / noahmp%energy_state_CanopyHeight(noahmp_c))
    TMP2 = exp(-noahmp%energy_state_WindExtCoeffCanopy(noahmp_c) * (noahmp%energy_state_RoughLenShCanopy(noahmp_c) + noahmp%energy_state_ZeroPlaneDispSfc(noahmp_c)) / noahmp%energy_state_CanopyHeight(noahmp_c))
    TMPRAH2 = noahmp%energy_state_CanopyHeight(noahmp_c) * exp(noahmp%energy_state_WindExtCoeffCanopy(noahmp_c)) / noahmp%energy_state_WindExtCoeffCanopy(noahmp_c) * (TMP1-TMP2)
    KH = max(ConstVonKarman*noahmp%energy_state_FrictionVelVeg(noahmp_c)*(noahmp%energy_state_CanopyHeight(noahmp_c)-noahmp%energy_state_ZeroPlaneDispSfc(noahmp_c)), MPE)
    noahmp%energy_state_ResistanceMomUndCan(noahmp_c) = 0.0
    noahmp%energy_state_ResistanceShUndCan(noahmp_c) = TMPRAH2 / KH
    noahmp%energy_state_ResistanceLhUndCan(noahmp_c) = noahmp%energy_state_ResistanceShUndCan(noahmp_c)
    TMPRB = noahmp%energy_state_WindExtCoeffCanopy(noahmp_c) * 50.0 / (1.0 - exp(-noahmp%energy_state_WindExtCoeffCanopy(noahmp_c)/2.0))
    noahmp%energy_state_ResistanceLeafBoundary(noahmp_c) = TMPRB * sqrt(noahmp%energy_param_LeafDimLength(noahmp_c) / noahmp%energy_state_WindSpdCanopyTop(noahmp_c))
    noahmp%energy_state_ResistanceLeafBoundary(noahmp_c) = min(max(noahmp%energy_state_ResistanceLeafBoundary(noahmp_c), 5.0), 50.0)
  end subroutine ResistanceLeafToGround
end module lean_resistanceleaftogroundmod

! Source: physics_noahmp/src/ResistanceCanopyStomataBallBerryMod.F90
module lean_resistancecanopystomataballberrymod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine ResistanceCanopyStomataBallBerry(noahmp, noahmp_c, IndexShade)
 !$acc routine seq
    implicit none
    integer , intent(in ) :: IndexShade
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: IndIter
    integer, parameter :: NumIter = 3
    real(kind=kind_noahmp) :: RadPhotoActAbsTmp
    real(kind=kind_noahmp) :: ResistanceStomataTmp
    real(kind=kind_noahmp) :: PhotosynLeafTmp
    real(kind=kind_noahmp) :: NitrogenFoliageFac
    real(kind=kind_noahmp) :: CarboxylRateMax
    real(kind=kind_noahmp) :: MPE
    real(kind=kind_noahmp) :: RLB
    real(kind=kind_noahmp) :: TC
    real(kind=kind_noahmp) :: CS
    real(kind=kind_noahmp) :: KC
    real(kind=kind_noahmp) :: KO
    real(kind=kind_noahmp) :: A,B,C,Q
    real(kind=kind_noahmp) :: R1,R2
    real(kind=kind_noahmp) :: PPF
    real(kind=kind_noahmp) :: WC
    real(kind=kind_noahmp) :: WJ
    real(kind=kind_noahmp) :: WE
    real(kind=kind_noahmp) :: CP
    real(kind=kind_noahmp) :: CI
    real(kind=kind_noahmp) :: AWC
    real(kind=kind_noahmp) :: J
    real(kind=kind_noahmp) :: CEA
    real(kind=kind_noahmp) :: CF
    real(kind=kind_noahmp) :: T
    real(kind=kind_noahmp) :: F1
    real(kind=kind_noahmp) :: F2
    real(kind=kind_noahmp) :: AB
    real(kind=kind_noahmp) :: BC
    F1(AB, BC) = AB**( (BC - 25.0) / 10.0 )
    F2(AB) = 1.0 + exp( (-2.2e05 + 710.0 * (AB + 273.16)) / (8.314 * (AB + 273.16)) )
    MPE = 1.0e-6
    CF = noahmp%forcing_PressureAirRefHeight(noahmp_c) / (8.314 * noahmp%forcing_TemperatureAirRefHeight(noahmp_c)) * 1.0e06
    ResistanceStomataTmp = 1.0 / noahmp%energy_param_ConductanceLeafMin(noahmp_c) * CF
    PhotosynLeafTmp = 0.0
    if ( IndexShade == 0 ) RadPhotoActAbsTmp = noahmp%energy_flux_RadPhotoActAbsSunlit(noahmp_c) / max(noahmp%energy_state_VegFrac(noahmp_c),1.0e-6)
    if ( IndexShade == 1 ) RadPhotoActAbsTmp = noahmp%energy_flux_RadPhotoActAbsShade(noahmp_c) / max(noahmp%energy_state_VegFrac(noahmp_c),1.0e-6)
    if ( RadPhotoActAbsTmp > 0.0 ) then
      NitrogenFoliageFac = min(noahmp%biochem_state_NitrogenConcFoliage(noahmp_c)/max(MPE, noahmp%biochem_param_NitrogenConcFoliageMax(noahmp_c)), 1.0)
      TC = noahmp%energy_state_TemperatureCanopy(noahmp_c) - ConstFreezePoint
      PPF = 4.6 * RadPhotoActAbsTmp
      J = PPF * noahmp%biochem_param_QuantumEfficiency25C(noahmp_c)
      KC = noahmp%energy_param_Co2MmConst25C(noahmp_c) * F1(noahmp%energy_param_Co2MmConstQ10(noahmp_c), TC)
      KO = noahmp%energy_param_O2MmConst25C(noahmp_c) * F1(noahmp%energy_param_O2MmConstQ10(noahmp_c), TC)
      AWC = KC * ( 1.0 + noahmp%energy_state_PressureAtmosO2(noahmp_c) / KO )
      CP = 0.5 * KC / KO * noahmp%energy_state_PressureAtmosO2(noahmp_c) * 0.21
      CarboxylRateMax = noahmp%biochem_param_CarboxylRateMax25C(noahmp_c) / F2(TC) * NitrogenFoliageFac * noahmp%water_state_SoilTranspFacAcc(noahmp_c) * F1(noahmp%biochem_param_CarboxylRateMaxQ10(noahmp_c), TC)
      CI = 0.7 * noahmp%energy_state_PressureAtmosCO2(noahmp_c) * noahmp%biochem_param_PhotosynPathC3(noahmp_c) + 0.4 * noahmp%energy_state_PressureAtmosCO2(noahmp_c) * (1.0 - noahmp%biochem_param_PhotosynPathC3(noahmp_c))
      RLB = noahmp%energy_state_ResistanceLeafBoundary(noahmp_c) / CF
      CEA = max(0.25*noahmp%energy_state_VapPresSatCanopy(noahmp_c)*noahmp%biochem_param_PhotosynPathC3(noahmp_c) + 0.40*noahmp%energy_state_VapPresSatCanopy(noahmp_c)*(1.0-noahmp%biochem_param_PhotosynPathC3(noahmp_c)), &
        & min(noahmp%energy_state_PressureVaporCanAir(noahmp_c),noahmp%energy_state_VapPresSatCanopy(noahmp_c)))
      do IndIter = 1, NumIter
        WJ = max(CI-CP, 0.0) * J / (CI + 2.0*CP) * noahmp%biochem_param_PhotosynPathC3(noahmp_c) + J * (1.0 - noahmp%biochem_param_PhotosynPathC3(noahmp_c))
        WC = max(CI-CP, &
          & 0.0) * CarboxylRateMax / (CI + AWC) * noahmp%biochem_param_PhotosynPathC3(noahmp_c) + CarboxylRateMax * (1.0 - noahmp%biochem_param_PhotosynPathC3(noahmp_c))
        WE = 0.5 * CarboxylRateMax * noahmp%biochem_param_PhotosynPathC3(noahmp_c) + 4000.0 * CarboxylRateMax * CI / noahmp%forcing_PressureAirRefHeight(noahmp_c) * (1.0 - noahmp%biochem_param_PhotosynPathC3(noahmp_c))
        PhotosynLeafTmp = min(WJ, WC, WE) * noahmp%biochem_state_IndexGrowSeason(noahmp_c)
        CS = max(noahmp%energy_state_PressureAtmosCO2(noahmp_c)-1.37*RLB*noahmp%forcing_PressureAirRefHeight(noahmp_c)*PhotosynLeafTmp, MPE)
        A = noahmp%biochem_param_SlopeConductToPhotosyn(noahmp_c) * PhotosynLeafTmp * noahmp%forcing_PressureAirRefHeight(noahmp_c) * CEA / (CS * noahmp%energy_state_VapPresSatCanopy(noahmp_c)) + noahmp%energy_param_ConductanceLeafMin(noahmp_c)
        B = (noahmp%biochem_param_SlopeConductToPhotosyn(noahmp_c) * PhotosynLeafTmp * noahmp%forcing_PressureAirRefHeight(noahmp_c) / CS + noahmp%energy_param_ConductanceLeafMin(noahmp_c)) * RLB - 1.0
        C = -RLB
        if ( B >= 0.0 ) then
          Q = -0.5 * (B + sqrt(B*B-4.0*A*C))
        else
          Q = -0.5 * (B - sqrt(B*B-4.0*A*C))
        endif
        R1 = Q / A
        R2 = C / Q
        ResistanceStomataTmp = max(R1, R2)
        CI = max(CS-PhotosynLeafTmp*noahmp%forcing_PressureAirRefHeight(noahmp_c)*1.65*ResistanceStomataTmp, 0.0)
      enddo
      ResistanceStomataTmp = ResistanceStomataTmp * CF
    endif
    if ( IndexShade == 0 ) then
      noahmp%energy_state_ResistanceStomataSunlit(noahmp_c) = ResistanceStomataTmp
      noahmp%biochem_flux_PhotosynLeafSunlit(noahmp_c) = PhotosynLeafTmp
    endif
    if ( IndexShade == 1 ) then
      noahmp%energy_state_ResistanceStomataShade(noahmp_c) = ResistanceStomataTmp
      noahmp%biochem_flux_PhotosynLeafShade(noahmp_c) = PhotosynLeafTmp
    endif
  end subroutine ResistanceCanopyStomataBallBerry
end module lean_resistancecanopystomataballberrymod

! Source: physics_noahmp/src/SurfaceEnergyFluxVegetatedMod.F90
module lean_surfaceenergyfluxvegetatedmod
 use lean_phys_fault, only: physics_fault
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_vaporpressuresaturationmod, only : VaporPressureSaturation
  use lean_resistanceabovecanopymostmod, only : ResistanceAboveCanopyMOST
  use lean_resistanceabovecanopychen97mod, only : ResistanceAboveCanopyChen97
  use lean_resistanceleaftogroundmod, only : ResistanceLeafToGround
  use lean_resistancecanopystomataballberrymod, only : ResistanceCanopyStomataBallBerry
  implicit none
  contains
  subroutine SurfaceEnergyFluxVegetated(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: IndIter
    integer :: LastIter
    integer :: MoStabParaSgn
    integer :: IndexShade
    integer, parameter :: NumIterC = 20
    integer, parameter :: NumIterG = 5
    real(kind=kind_noahmp) :: ExchCoeffShAbvCanTmp
    real(kind=kind_noahmp) :: TemperatureCanChg
    real(kind=kind_noahmp) :: TemperatureGrdChg
    real(kind=kind_noahmp) :: LwCoeffAir
    real(kind=kind_noahmp) :: LwCoeffCan
    real(kind=kind_noahmp) :: ShCoeff
    real(kind=kind_noahmp) :: LhCoeff
    real(kind=kind_noahmp) :: GrdHeatCoeff
    real(kind=kind_noahmp) :: TranspHeatCoeff
    real(kind=kind_noahmp) :: TempShGhTmp
    real(kind=kind_noahmp) :: ExchCoeffShFrac
    real(kind=kind_noahmp) :: VapPresLhTot
    real(kind=kind_noahmp) :: ExchCoeffEtFrac
    real(kind=kind_noahmp) :: VapPresSatWatTmp
    real(kind=kind_noahmp) :: VapPresSatIceTmp
    real(kind=kind_noahmp) :: VapPresSatWatTmpD
    real(kind=kind_noahmp) :: VapPresSatIceTmpD
    real(kind=kind_noahmp) :: FluxTotCoeff
    real(kind=kind_noahmp) :: EnergyResTmp
    real(kind=kind_noahmp) :: ExchCoeffShLeafTmp
    real(kind=kind_noahmp) :: ExchCoeffTot
    real(kind=kind_noahmp) :: ShCanTmp
    real(kind=kind_noahmp) :: ShGrdTmp
    real(kind=kind_noahmp) :: MoistureFluxSfc
    real(kind=kind_noahmp) :: VegAreaIndTmp
    real(kind=kind_noahmp) :: LeafAreaIndSunEff
    real(kind=kind_noahmp) :: LeafAreaIndShdEff
    real(kind=kind_noahmp) :: TempTmp
    real(kind=kind_noahmp) :: TempUnitConv
    real(kind=kind_noahmp) :: HeatCapacCan
    TempUnitConv(TempTmp) = min(50.0, max(-50.0, (TempTmp - ConstFreezePoint)))
    associate( OptSurfaceDrag => noahmp_opt_sfc )
    LastIter = 0
    noahmp%energy_state_FrictionVelVeg(noahmp_c) = 0.1
    TemperatureCanChg = 0.0
    TemperatureGrdChg = 0.0
    noahmp%energy_state_MoStabParaAbvCan(noahmp_c) = 0.0
    MoStabParaSgn = 0
    noahmp%energy_state_MoStabCorrShVeg2m(noahmp_c) = 0.0
    ShGrdTmp = 0.0
    ShCanTmp = 0.0
    MoistureFluxSfc = 0.0
    VegAreaIndTmp = min(6.0, noahmp%energy_state_VegAreaIndEff(noahmp_c))
    LeafAreaIndSunEff = min(6.0, noahmp%energy_state_LeafAreaIndSunlit(noahmp_c))
    LeafAreaIndShdEff = min(6.0, noahmp%energy_state_LeafAreaIndShade(noahmp_c))
    TempTmp = TempUnitConv(noahmp%energy_state_TemperatureGrdVeg(noahmp_c))
    call VaporPressureSaturation(TempTmp, VapPresSatWatTmp, VapPresSatIceTmp, VapPresSatWatTmpD, &
      & VapPresSatIceTmpD)
    if ( TempTmp > 0.0 ) then
      noahmp%energy_state_VapPresSatGrdVeg(noahmp_c) = VapPresSatWatTmp
    else
      noahmp%energy_state_VapPresSatGrdVeg(noahmp_c) = VapPresSatIceTmp
    endif
    noahmp%energy_state_CanopyHeight(noahmp_c) = noahmp%energy_param_HeightCanopyTop(noahmp_c)
    noahmp%energy_state_WindSpdCanopyTop(noahmp_c) = noahmp%energy_state_WindSpdRefHeight(noahmp_c) * log((noahmp%energy_state_CanopyHeight(noahmp_c) - noahmp%energy_state_ZeroPlaneDispSfc(noahmp_c) + noahmp%energy_state_RoughLenMomSfc(noahmp_c))/noahmp%energy_state_RoughLenMomSfc(noahmp_c)) / log(noahmp%energy_state_RefHeightAboveGrd(noahmp_c)/noahmp%energy_state_RoughLenMomSfc(noahmp_c))
    if ( (noahmp%energy_state_CanopyHeight(noahmp_c)-noahmp%energy_state_ZeroPlaneDispSfc(noahmp_c)) <= 0.0 ) then
      call physics_fault(5)
    endif
    LwCoeffAir = -noahmp%energy_state_EmissivityVeg(noahmp_c) * (1.0 + (1.0-noahmp%energy_state_EmissivityVeg(noahmp_c))*(1.0-noahmp%energy_state_EmissivityGrd(noahmp_c))) * noahmp%forcing_RadLwDownRefHeight(noahmp_c) - noahmp%energy_state_EmissivityVeg(noahmp_c) * noahmp%energy_state_EmissivityGrd(noahmp_c) * ConstStefanBoltzmann * noahmp%energy_state_TemperatureGrdVeg(noahmp_c)**4
    LwCoeffCan = (2.0 - noahmp%energy_state_EmissivityVeg(noahmp_c) * (1.0-noahmp%energy_state_EmissivityGrd(noahmp_c))) * noahmp%energy_state_EmissivityVeg(noahmp_c) * ConstStefanBoltzmann
    loop1: do IndIter = 1, NumIterC
    if ( IndIter == 1 ) then
      noahmp%energy_state_RoughLenShCanopy(noahmp_c) = noahmp%energy_state_RoughLenMomSfc(noahmp_c)
      noahmp%energy_state_RoughLenShVegGrd(noahmp_c) = noahmp%energy_state_RoughLenMomGrd(noahmp_c)
    else
      noahmp%energy_state_RoughLenShCanopy(noahmp_c) = noahmp%energy_state_RoughLenMomSfc(noahmp_c)
      noahmp%energy_state_RoughLenShVegGrd(noahmp_c) = noahmp%energy_state_RoughLenMomGrd(noahmp_c)
    endif
 if (noahmp_opt_sfc == 2) then
    call ResistanceAboveCanopyChen97(noahmp, noahmp_c, IndIter)
 else
    call ResistanceAboveCanopyMOST(noahmp, noahmp_c, IndIter, ShCanTmp, MoStabParaSgn)
 end if
    call ResistanceLeafToGround(noahmp, noahmp_c, IndIter, VegAreaIndTmp, ShGrdTmp)
    TempTmp = TempUnitConv(noahmp%energy_state_TemperatureCanopy(noahmp_c))
    call VaporPressureSaturation(TempTmp, VapPresSatWatTmp, VapPresSatIceTmp, VapPresSatWatTmpD, &
      & VapPresSatIceTmpD)
    if ( TempTmp > 0.0 ) then
      noahmp%energy_state_VapPresSatCanopy(noahmp_c) = VapPresSatWatTmp
      noahmp%energy_state_VapPresSatCanTempD(noahmp_c) = VapPresSatWatTmpD
    else
      noahmp%energy_state_VapPresSatCanopy(noahmp_c) = VapPresSatIceTmp
      noahmp%energy_state_VapPresSatCanTempD(noahmp_c) = VapPresSatIceTmpD
    endif
    if ( IndIter == 1 ) then
      IndexShade = 0
      call ResistanceCanopyStomataBallBerry(noahmp, noahmp_c, IndexShade)
      IndexShade = 1
      call ResistanceCanopyStomataBallBerry(noahmp, noahmp_c, IndexShade)
    endif
    ExchCoeffShAbvCanTmp = 1.0 / noahmp%energy_state_ResistanceShAbvCan(noahmp_c)
    ExchCoeffShLeafTmp = 2.0 * VegAreaIndTmp / noahmp%energy_state_ResistanceLeafBoundary(noahmp_c)
    GrdHeatCoeff = 1.0 / noahmp%energy_state_ResistanceShUndCan(noahmp_c)
    ExchCoeffTot = ExchCoeffShAbvCanTmp + ExchCoeffShLeafTmp + GrdHeatCoeff
    TempShGhTmp = (noahmp%forcing_TemperatureAirRefHeight(noahmp_c)*ExchCoeffShAbvCanTmp + noahmp%energy_state_TemperatureGrdVeg(noahmp_c)*GrdHeatCoeff) / ExchCoeffTot
    ExchCoeffShFrac = ExchCoeffShLeafTmp / ExchCoeffTot
    ShCoeff = (1.0 - ExchCoeffShFrac) * noahmp%energy_state_DensityAirRefHeight(noahmp_c) * ConstHeatCapacAir * ExchCoeffShLeafTmp
    noahmp%energy_state_ExchCoeffLhAbvCan(noahmp_c) = 1.0 / noahmp%energy_state_ResistanceLhAbvCan(noahmp_c)
    noahmp%energy_state_ExchCoeffLhEvap(noahmp_c) = noahmp%water_state_CanopyWetFrac(noahmp_c) * VegAreaIndTmp / noahmp%energy_state_ResistanceLeafBoundary(noahmp_c)
    noahmp%energy_state_ExchCoeffLhTransp(noahmp_c) = (1.0 - noahmp%water_state_CanopyWetFrac(noahmp_c)) * (LeafAreaIndSunEff/(noahmp%energy_state_ResistanceLeafBoundary(noahmp_c)+noahmp%energy_state_ResistanceStomataSunlit(noahmp_c)) + LeafAreaIndShdEff/(noahmp%energy_state_ResistanceLeafBoundary(noahmp_c)+noahmp%energy_state_ResistanceStomataShade(noahmp_c)))
    noahmp%energy_state_ExchCoeffLhUndCan(noahmp_c) = 1.0 / (noahmp%energy_state_ResistanceLhUndCan(noahmp_c) + noahmp%energy_state_ResistanceGrdEvap(noahmp_c))
    ExchCoeffTot = noahmp%energy_state_ExchCoeffLhAbvCan(noahmp_c) + noahmp%energy_state_ExchCoeffLhEvap(noahmp_c) + noahmp%energy_state_ExchCoeffLhTransp(noahmp_c) + noahmp%energy_state_ExchCoeffLhUndCan(noahmp_c)
    VapPresLhTot = (noahmp%energy_state_PressureVaporRefHeight(noahmp_c)*noahmp%energy_state_ExchCoeffLhAbvCan(noahmp_c) + noahmp%energy_state_VapPresSatGrdVeg(noahmp_c)*noahmp%energy_state_ExchCoeffLhUndCan(noahmp_c) ) / ExchCoeffTot
    ExchCoeffEtFrac = (noahmp%energy_state_ExchCoeffLhEvap(noahmp_c) + noahmp%energy_state_ExchCoeffLhTransp(noahmp_c)) / ExchCoeffTot
    LhCoeff = (1.0 - ExchCoeffEtFrac) * noahmp%energy_state_ExchCoeffLhEvap(noahmp_c) * noahmp%energy_state_DensityAirRefHeight(noahmp_c) * ConstHeatCapacAir / noahmp%energy_state_PsychConstCanopy(noahmp_c)
    TranspHeatCoeff = (1.0 - ExchCoeffEtFrac) * noahmp%energy_state_ExchCoeffLhTransp(noahmp_c) * noahmp%energy_state_DensityAirRefHeight(noahmp_c) * ConstHeatCapacAir / noahmp%energy_state_PsychConstCanopy(noahmp_c)
    noahmp%energy_state_TemperatureCanopyAir(noahmp_c) = TempShGhTmp + ExchCoeffShFrac * noahmp%energy_state_TemperatureCanopy(noahmp_c)
    noahmp%energy_state_PressureVaporCanAir(noahmp_c) = VapPresLhTot + ExchCoeffEtFrac * noahmp%energy_state_VapPresSatCanopy(noahmp_c)
    noahmp%energy_flux_RadLwNetCanopy(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * (LwCoeffAir + LwCoeffCan * noahmp%energy_state_TemperatureCanopy(noahmp_c)**4)
    noahmp%energy_flux_HeatSensibleCanopy(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%energy_state_DensityAirRefHeight(noahmp_c) * ConstHeatCapacAir * ExchCoeffShLeafTmp * (noahmp%energy_state_TemperatureCanopy(noahmp_c) - noahmp%energy_state_TemperatureCanopyAir(noahmp_c))
    noahmp%energy_flux_HeatLatentCanEvap(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%energy_state_DensityAirRefHeight(noahmp_c) * ConstHeatCapacAir * noahmp%energy_state_ExchCoeffLhEvap(noahmp_c) * (noahmp%energy_state_VapPresSatCanopy(noahmp_c) - noahmp%energy_state_PressureVaporCanAir(noahmp_c)) / noahmp%energy_state_PsychConstCanopy(noahmp_c)
    noahmp%energy_flux_HeatLatentCanTransp(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%energy_state_DensityAirRefHeight(noahmp_c) * ConstHeatCapacAir * noahmp%energy_state_ExchCoeffLhTransp(noahmp_c) * (noahmp%energy_state_VapPresSatCanopy(noahmp_c) - noahmp%energy_state_PressureVaporCanAir(noahmp_c)) / noahmp%energy_state_PsychConstCanopy(noahmp_c)
    if ( noahmp%energy_state_TemperatureCanopy(noahmp_c) > ConstFreezePoint ) then
      noahmp%energy_flux_HeatLatentCanEvap(noahmp_c) = min(noahmp%water_state_CanopyLiqWater(noahmp_c)*noahmp%energy_state_LatHeatVapCanopy(noahmp_c)/noahmp%config_domain_MainTimeStep(noahmp_c), noahmp%energy_flux_HeatLatentCanEvap(noahmp_c))
    else
      noahmp%energy_flux_HeatLatentCanEvap(noahmp_c) = min(noahmp%water_state_CanopyIce(noahmp_c)*noahmp%energy_state_LatHeatVapCanopy(noahmp_c)/noahmp%config_domain_MainTimeStep(noahmp_c), noahmp%energy_flux_HeatLatentCanEvap(noahmp_c))
    endif
    HeatCapacCan = noahmp%energy_param_HeatCapacCanFac(noahmp_c)*VegAreaIndTmp*ConstHeatCapacWater + noahmp%water_state_CanopyLiqWater(noahmp_c)*ConstHeatCapacWater/ConstDensityWater + noahmp%water_state_CanopyIce(noahmp_c)*ConstHeatCapacIce/ConstDensityIce
    EnergyResTmp = noahmp%energy_flux_RadSwAbsVeg(noahmp_c) - noahmp%energy_flux_RadLwNetCanopy(noahmp_c) - noahmp%energy_flux_HeatSensibleCanopy(noahmp_c) - noahmp%energy_flux_HeatLatentCanEvap(noahmp_c) - noahmp%energy_flux_HeatLatentCanTransp(noahmp_c) + noahmp%energy_flux_HeatPrecipAdvCanopy(noahmp_c)
    FluxTotCoeff = noahmp%energy_state_VegFrac(noahmp_c) * (4.0*LwCoeffCan*noahmp%energy_state_TemperatureCanopy(noahmp_c)**3 + ShCoeff + (LhCoeff+TranspHeatCoeff)*noahmp%energy_state_VapPresSatCanTempD(noahmp_c) + HeatCapacCan/noahmp%config_domain_MainTimeStep(noahmp_c))
    TemperatureCanChg = EnergyResTmp / FluxTotCoeff
    noahmp%energy_flux_RadLwNetCanopy(noahmp_c) = noahmp%energy_flux_RadLwNetCanopy(noahmp_c) + noahmp%energy_state_VegFrac(noahmp_c) * 4.0 * LwCoeffCan * noahmp%energy_state_TemperatureCanopy(noahmp_c)**3 * TemperatureCanChg
    noahmp%energy_flux_HeatSensibleCanopy(noahmp_c) = noahmp%energy_flux_HeatSensibleCanopy(noahmp_c) + noahmp%energy_state_VegFrac(noahmp_c) * ShCoeff * TemperatureCanChg
    noahmp%energy_flux_HeatLatentCanEvap(noahmp_c) = noahmp%energy_flux_HeatLatentCanEvap(noahmp_c) + noahmp%energy_state_VegFrac(noahmp_c) * LhCoeff * noahmp%energy_state_VapPresSatCanTempD(noahmp_c) * TemperatureCanChg
    noahmp%energy_flux_HeatLatentCanTransp(noahmp_c) = noahmp%energy_flux_HeatLatentCanTransp(noahmp_c) + noahmp%energy_state_VegFrac(noahmp_c) * TranspHeatCoeff * noahmp%energy_state_VapPresSatCanTempD(noahmp_c) * TemperatureCanChg
    noahmp%energy_flux_HeatCanStorageChg(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * HeatCapacCan / noahmp%config_domain_MainTimeStep(noahmp_c) * TemperatureCanChg
    noahmp%energy_state_TemperatureCanopy(noahmp_c) = noahmp%energy_state_TemperatureCanopy(noahmp_c) + TemperatureCanChg
    ShCanTmp = noahmp%energy_state_DensityAirRefHeight(noahmp_c) * ConstHeatCapacAir * (noahmp%energy_state_TemperatureCanopyAir(noahmp_c)-noahmp%forcing_TemperatureAirRefHeight(noahmp_c)) / noahmp%energy_state_ResistanceShAbvCan(noahmp_c)
    ShGrdTmp = noahmp%energy_state_DensityAirRefHeight(noahmp_c) * ConstHeatCapacAir * (noahmp%energy_state_TemperatureGrdVeg(noahmp_c)-noahmp%energy_state_TemperatureCanopyAir(noahmp_c)) / noahmp%energy_state_ResistanceShUndCan(noahmp_c)
    noahmp%energy_state_SpecHumiditySfc(noahmp_c) = (0.622 * noahmp%energy_state_PressureVaporCanAir(noahmp_c)) / (noahmp%forcing_PressureAirRefHeight(noahmp_c) - 0.378 * noahmp%energy_state_PressureVaporCanAir(noahmp_c))
    if ( LastIter == 1 ) then
      exit loop1
    endif
    if ( (IndIter >= 5) .and. (abs(TemperatureCanChg) <= 0.01) .and. (LastIter == 0) ) then
      LastIter = 1
    endif
  enddo loop1
  LwCoeffAir = -noahmp%energy_state_EmissivityGrd(noahmp_c) * (1.0 - noahmp%energy_state_EmissivityVeg(noahmp_c)) * noahmp%forcing_RadLwDownRefHeight(noahmp_c) - noahmp%energy_state_EmissivityGrd(noahmp_c) * noahmp%energy_state_EmissivityVeg(noahmp_c) * ConstStefanBoltzmann * noahmp%energy_state_TemperatureCanopy(noahmp_c)**4
  LwCoeffCan = noahmp%energy_state_EmissivityGrd(noahmp_c) * ConstStefanBoltzmann
  ShCoeff = noahmp%energy_state_DensityAirRefHeight(noahmp_c) * ConstHeatCapacAir / noahmp%energy_state_ResistanceShUndCan(noahmp_c)
  LhCoeff = noahmp%energy_state_DensityAirRefHeight(noahmp_c) * ConstHeatCapacAir / (noahmp%energy_state_PsychConstGrd(noahmp_c) * (noahmp%energy_state_ResistanceLhUndCan(noahmp_c)+noahmp%energy_state_ResistanceGrdEvap(noahmp_c)))
  GrdHeatCoeff = 2.0 * noahmp%energy_state_ThermConductSoilSnow(noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, noahmp_c) / noahmp%config_domain_ThicknessSnowSoilLayer(noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, noahmp_c)
  loop2: do IndIter = 1, NumIterG
  TempTmp = TempUnitConv(noahmp%energy_state_TemperatureGrdVeg(noahmp_c))
  call VaporPressureSaturation(TempTmp, VapPresSatWatTmp, VapPresSatIceTmp, VapPresSatWatTmpD, &
    & VapPresSatIceTmpD)
  if ( TempTmp > 0.0 ) then
    noahmp%energy_state_VapPresSatGrdVeg(noahmp_c) = VapPresSatWatTmp
    noahmp%energy_state_VapPresSatGrdVegTempD(noahmp_c) = VapPresSatWatTmpD
  else
    noahmp%energy_state_VapPresSatGrdVeg(noahmp_c) = VapPresSatIceTmp
    noahmp%energy_state_VapPresSatGrdVegTempD(noahmp_c) = VapPresSatIceTmpD
  endif
  noahmp%energy_flux_RadLwNetVegGrd(noahmp_c) = LwCoeffCan * noahmp%energy_state_TemperatureGrdVeg(noahmp_c)**4 + LwCoeffAir
  noahmp%energy_flux_HeatSensibleVegGrd(noahmp_c) = ShCoeff * (noahmp%energy_state_TemperatureGrdVeg(noahmp_c) - noahmp%energy_state_TemperatureCanopyAir(noahmp_c))
  noahmp%energy_flux_HeatLatentVegGrd(noahmp_c) = LhCoeff * (noahmp%energy_state_VapPresSatGrdVeg(noahmp_c)*noahmp%energy_state_RelHumidityGrd(noahmp_c) - noahmp%energy_state_PressureVaporCanAir(noahmp_c))
  noahmp%energy_flux_HeatGroundVegGrd(noahmp_c) = GrdHeatCoeff * (noahmp%energy_state_TemperatureGrdVeg(noahmp_c) - noahmp%energy_state_TemperatureSoilSnow(noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, noahmp_c))
  EnergyResTmp = noahmp%energy_flux_RadSwAbsGrd(noahmp_c) - noahmp%energy_flux_RadLwNetVegGrd(noahmp_c) - noahmp%energy_flux_HeatSensibleVegGrd(noahmp_c) - noahmp%energy_flux_HeatLatentVegGrd(noahmp_c) - noahmp%energy_flux_HeatGroundVegGrd(noahmp_c) + noahmp%energy_flux_HeatPrecipAdvVegGrd(noahmp_c)
  FluxTotCoeff = 4.0 * LwCoeffCan * noahmp%energy_state_TemperatureGrdVeg(noahmp_c)**3 + ShCoeff + LhCoeff*noahmp%energy_state_VapPresSatGrdVegTempD(noahmp_c) + GrdHeatCoeff
  TemperatureGrdChg = EnergyResTmp / FluxTotCoeff
  noahmp%energy_flux_RadLwNetVegGrd(noahmp_c) = noahmp%energy_flux_RadLwNetVegGrd(noahmp_c) + 4.0 * LwCoeffCan * noahmp%energy_state_TemperatureGrdVeg(noahmp_c)**3 * TemperatureGrdChg
  noahmp%energy_flux_HeatSensibleVegGrd(noahmp_c) = noahmp%energy_flux_HeatSensibleVegGrd(noahmp_c) + ShCoeff * TemperatureGrdChg
  noahmp%energy_flux_HeatLatentVegGrd(noahmp_c) = noahmp%energy_flux_HeatLatentVegGrd(noahmp_c) + LhCoeff * noahmp%energy_state_VapPresSatGrdVegTempD(noahmp_c) * TemperatureGrdChg
  noahmp%energy_flux_HeatGroundVegGrd(noahmp_c) = noahmp%energy_flux_HeatGroundVegGrd(noahmp_c) + GrdHeatCoeff * TemperatureGrdChg
  noahmp%energy_state_TemperatureGrdVeg(noahmp_c) = noahmp%energy_state_TemperatureGrdVeg(noahmp_c) + TemperatureGrdChg
enddo loop2
if ( (noahmp%water_state_SnowDepth(noahmp_c) > 0.05) .and. (noahmp%energy_state_TemperatureGrdVeg(noahmp_c) > ConstFreezePoint) ) then
  noahmp%energy_state_TemperatureGrdVeg(noahmp_c) = ConstFreezePoint
  noahmp%energy_flux_RadLwNetVegGrd(noahmp_c) = LwCoeffCan * noahmp%energy_state_TemperatureGrdVeg(noahmp_c)**4 - noahmp%energy_state_EmissivityGrd(noahmp_c) * (1.0-noahmp%energy_state_EmissivityVeg(noahmp_c)) * noahmp%forcing_RadLwDownRefHeight(noahmp_c) - noahmp%energy_state_EmissivityGrd(noahmp_c) * noahmp%energy_state_EmissivityVeg(noahmp_c) * ConstStefanBoltzmann * noahmp%energy_state_TemperatureCanopy(noahmp_c)**4
  noahmp%energy_flux_HeatSensibleVegGrd(noahmp_c) = ShCoeff * (noahmp%energy_state_TemperatureGrdVeg(noahmp_c) - noahmp%energy_state_TemperatureCanopyAir(noahmp_c))
  noahmp%energy_flux_HeatLatentVegGrd(noahmp_c) = LhCoeff * (noahmp%energy_state_VapPresSatGrdVeg(noahmp_c)*noahmp%energy_state_RelHumidityGrd(noahmp_c) - noahmp%energy_state_PressureVaporCanAir(noahmp_c))
  noahmp%energy_flux_HeatGroundVegGrd(noahmp_c) = noahmp%energy_flux_RadSwAbsGrd(noahmp_c) + noahmp%energy_flux_HeatPrecipAdvVegGrd(noahmp_c) - (noahmp%energy_flux_RadLwNetVegGrd(noahmp_c) + noahmp%energy_flux_HeatSensibleVegGrd(noahmp_c) + noahmp%energy_flux_HeatLatentVegGrd(noahmp_c))
endif
noahmp%energy_state_WindStressEwVeg(noahmp_c) = -noahmp%energy_state_DensityAirRefHeight(noahmp_c) * noahmp%energy_state_ExchCoeffMomAbvCan(noahmp_c) * noahmp%energy_state_WindSpdRefHeight(noahmp_c) * noahmp%forcing_WindEastwardRefHeight(noahmp_c)
noahmp%energy_state_WindStressNsVeg(noahmp_c) = -noahmp%energy_state_DensityAirRefHeight(noahmp_c) * noahmp%energy_state_ExchCoeffMomAbvCan(noahmp_c) * noahmp%energy_state_WindSpdRefHeight(noahmp_c) * noahmp%forcing_WindNorthwardRefHeight(noahmp_c)
noahmp%energy_state_ExchCoeffSh2mVeg(noahmp_c) = noahmp%energy_state_FrictionVelVeg(noahmp_c) * ConstVonKarman / (log((2.0+noahmp%energy_state_RoughLenShCanopy(noahmp_c))/noahmp%energy_state_RoughLenShCanopy(noahmp_c)) - noahmp%energy_state_MoStabCorrShVeg2m(noahmp_c))
if ( noahmp%energy_state_ExchCoeffSh2mVeg(noahmp_c) < 1.0e-5 ) then
  noahmp%energy_state_TemperatureAir2mVeg(noahmp_c) = noahmp%energy_state_TemperatureCanopyAir(noahmp_c)
  noahmp%energy_state_SpecHumidity2mVeg(noahmp_c) = noahmp%energy_state_SpecHumiditySfc(noahmp_c)
else
  noahmp%energy_state_TemperatureAir2mVeg(noahmp_c) = noahmp%energy_state_TemperatureCanopyAir(noahmp_c) - (noahmp%energy_flux_HeatSensibleVegGrd(noahmp_c) + noahmp%energy_flux_HeatSensibleCanopy(noahmp_c)/noahmp%energy_state_VegFrac(noahmp_c)) / (noahmp%energy_state_DensityAirRefHeight(noahmp_c) * ConstHeatCapacAir) * 1.0 / noahmp%energy_state_ExchCoeffSh2mVeg(noahmp_c)
  noahmp%energy_state_SpecHumidity2mVeg(noahmp_c) = noahmp%energy_state_SpecHumiditySfc(noahmp_c) - ((noahmp%energy_flux_HeatLatentCanEvap(noahmp_c)+noahmp%energy_flux_HeatLatentCanTransp(noahmp_c))/noahmp%energy_state_VegFrac(noahmp_c) + noahmp%energy_flux_HeatLatentVegGrd(noahmp_c)) / (noahmp%energy_state_LatHeatVapCanopy(noahmp_c) * noahmp%energy_state_DensityAirRefHeight(noahmp_c)) * 1.0 / noahmp%energy_state_ExchCoeffSh2mVeg(noahmp_c)
endif
noahmp%energy_state_ExchCoeffShAbvCan(noahmp_c) = ExchCoeffShAbvCanTmp
noahmp%energy_state_ExchCoeffShLeaf(noahmp_c) = ExchCoeffShLeafTmp
noahmp%energy_state_ExchCoeffShUndCan(noahmp_c) = 1.0 / noahmp%energy_state_ResistanceShUndCan(noahmp_c)
end associate
end subroutine SurfaceEnergyFluxVegetated
end module lean_surfaceenergyfluxvegetatedmod

! Source: physics_noahmp/src/ResistanceBareGroundMostMod.F90
module lean_resistancebaregroundmostmod
 use lean_phys_fault, only: physics_fault
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine ResistanceBareGroundMOST(noahmp, noahmp_c, IndIter, HeatSensibleTmp, MoStabParaSgn)
 !$acc routine seq
    implicit none
    integer , intent(in ) :: IndIter
    integer , intent(inout) :: MoStabParaSgn
    real(kind=kind_noahmp), intent(in ) :: HeatSensibleTmp
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    real(kind=kind_noahmp) :: MPE
    real(kind=kind_noahmp) :: TMPCM
    real(kind=kind_noahmp) :: TMPCH
    real(kind=kind_noahmp) :: FMNEW
    real(kind=kind_noahmp) :: FHNEW
    real(kind=kind_noahmp) :: MOZOLD
    real(kind=kind_noahmp) :: TMP1,TMP2,TMP3,TMP4,TMP5
    real(kind=kind_noahmp) :: TVIR
    real(kind=kind_noahmp) :: TMPCM2
    real(kind=kind_noahmp) :: TMPCH2
    real(kind=kind_noahmp) :: FM2NEW
    real(kind=kind_noahmp) :: FH2NEW
    real(kind=kind_noahmp) :: TMP12,TMP22,TMP32
    real(kind=kind_noahmp) :: CMFM, CHFH, CM2FM2, CH2FH2
    MPE = 1.0e-6
    MOZOLD = noahmp%energy_state_MoStabParaBare(noahmp_c)
    if ( noahmp%energy_state_RefHeightAboveGrd(noahmp_c) <= noahmp%energy_state_ZeroPlaneDispGrd(noahmp_c) ) then
      call physics_fault(6)
    endif
    TMPCM = log((noahmp%energy_state_RefHeightAboveGrd(noahmp_c) - noahmp%energy_state_ZeroPlaneDispGrd(noahmp_c)) / noahmp%energy_state_RoughLenMomGrd(noahmp_c))
    TMPCH = log((noahmp%energy_state_RefHeightAboveGrd(noahmp_c) - noahmp%energy_state_ZeroPlaneDispGrd(noahmp_c)) / noahmp%energy_state_RoughLenShBareGrd(noahmp_c))
    TMPCM2 = log((2.0 + noahmp%energy_state_RoughLenMomGrd(noahmp_c)) / noahmp%energy_state_RoughLenMomGrd(noahmp_c))
    TMPCH2 = log((2.0 + noahmp%energy_state_RoughLenShBareGrd(noahmp_c)) / noahmp%energy_state_RoughLenShBareGrd(noahmp_c))
    if ( IndIter == 1 ) then
      noahmp%energy_state_FrictionVelBare(noahmp_c) = 0.0
      noahmp%energy_state_MoStabParaBare(noahmp_c) = 0.0
      noahmp%energy_state_MoLengthBare(noahmp_c) = 0.0
      noahmp%energy_state_MoStabParaBare2m(noahmp_c) = 0.0
    else
      TVIR = (1.0 + 0.61*noahmp%forcing_SpecHumidityRefHeight(noahmp_c)) * noahmp%forcing_TemperatureAirRefHeight(noahmp_c)
      TMP1 = ConstVonKarman * (ConstGravityAcc/TVIR) * HeatSensibleTmp / (noahmp%energy_state_DensityAirRefHeight(noahmp_c)*ConstHeatCapacAir)
      if ( abs(TMP1) <= MPE ) TMP1 = MPE
      noahmp%energy_state_MoLengthBare(noahmp_c) = -1.0 * noahmp%energy_state_FrictionVelBare(noahmp_c)**3 / TMP1
      noahmp%energy_state_MoStabParaBare(noahmp_c) = min((noahmp%energy_state_RefHeightAboveGrd(noahmp_c) - noahmp%energy_state_ZeroPlaneDispGrd(noahmp_c)) / noahmp%energy_state_MoLengthBare(noahmp_c), 1.0)
#ifdef LEAN_NOAHMP_T2Z
      ! Lean departure (build switch LEAN_NOAHMP_T2Z, on in flavor lean, off in mpas; docs/fixes.md): MPAS caps z/L at 1 at the first
      ! level and at 2 m apart, from the same L. Past the cap the flux acts as if L = z, while 2 m still sees the true short L, so
      ! as a calm night grows more stable T2 turns back from the surface towards the first level. Here 2 m takes the capped L of
      ! the flux. In unstable air, with no cap, this is the same number. T2 and Q2 only: nothing else reads the 2 m values.
      noahmp%energy_state_MoStabParaBare2m(noahmp_c) = noahmp%energy_state_MoStabParaBare(noahmp_c) * (2.0 + noahmp%energy_state_RoughLenShBareGrd(noahmp_c)) / (noahmp%energy_state_RefHeightAboveGrd(noahmp_c) - noahmp%energy_state_ZeroPlaneDispGrd(noahmp_c))
#else
      noahmp%energy_state_MoStabParaBare2m(noahmp_c) = min((2.0 + noahmp%energy_state_RoughLenShBareGrd(noahmp_c)) / noahmp%energy_state_MoLengthBare(noahmp_c), 1.0)
#endif
    endif
    if ( MOZOLD*noahmp%energy_state_MoStabParaBare(noahmp_c) < 0.0 ) MoStabParaSgn = MoStabParaSgn + 1
    if ( MoStabParaSgn >= 2 ) then
      noahmp%energy_state_MoStabParaBare(noahmp_c) = 0.0
      noahmp%energy_state_MoStabCorrMomBare(noahmp_c) = 0.0
      noahmp%energy_state_MoStabCorrShBare(noahmp_c) = 0.0
      noahmp%energy_state_MoStabParaBare2m(noahmp_c) = 0.0
      noahmp%energy_state_MoStabCorrMomBare2m(noahmp_c) = 0.0
      noahmp%energy_state_MoStabCorrShBare2m(noahmp_c) = 0.0
    endif
    if ( noahmp%energy_state_MoStabParaBare(noahmp_c) < 0.0 ) then
      TMP1 = (1.0 - 16.0 * noahmp%energy_state_MoStabParaBare(noahmp_c))**0.25
      TMP2 = log((1.0 + TMP1*TMP1) / 2.0)
      TMP3 = log((1.0 + TMP1) / 2.0)
      FMNEW = 2.0 * TMP3 + TMP2 - 2.0 * atan(TMP1) + 1.5707963
      FHNEW = 2 * TMP2
      TMP12 = (1.0 - 16.0 * noahmp%energy_state_MoStabParaBare2m(noahmp_c))**0.25
      TMP22 = log((1.0 + TMP12*TMP12) / 2.0)
      TMP32 = log((1.0 + TMP12) / 2.0)
      FM2NEW = 2.0 * TMP32 + TMP22 - 2.0 * atan(TMP12) + 1.5707963
      FH2NEW = 2 * TMP22
    else
      FMNEW = -5.0 * noahmp%energy_state_MoStabParaBare(noahmp_c)
      FHNEW = FMNEW
      FM2NEW = -5.0 * noahmp%energy_state_MoStabParaBare2m(noahmp_c)
      FH2NEW = FM2NEW
    endif
    if ( IndIter == 1 ) then
      noahmp%energy_state_MoStabCorrMomBare(noahmp_c) = FMNEW
      noahmp%energy_state_MoStabCorrShBare(noahmp_c) = FHNEW
      noahmp%energy_state_MoStabCorrMomBare2m(noahmp_c) = FM2NEW
      noahmp%energy_state_MoStabCorrShBare2m(noahmp_c) = FH2NEW
    else
      noahmp%energy_state_MoStabCorrMomBare(noahmp_c) = 0.5 * (noahmp%energy_state_MoStabCorrMomBare(noahmp_c) + FMNEW)
      noahmp%energy_state_MoStabCorrShBare(noahmp_c) = 0.5 * (noahmp%energy_state_MoStabCorrShBare(noahmp_c) + FHNEW)
      noahmp%energy_state_MoStabCorrMomBare2m(noahmp_c) = 0.5 * (noahmp%energy_state_MoStabCorrMomBare2m(noahmp_c) + FM2NEW)
      noahmp%energy_state_MoStabCorrShBare2m(noahmp_c) = 0.5 * (noahmp%energy_state_MoStabCorrShBare2m(noahmp_c) + FH2NEW)
    endif
    noahmp%energy_state_MoStabCorrShBare(noahmp_c) = min(noahmp%energy_state_MoStabCorrShBare(noahmp_c) , 0.9*TMPCH )
    noahmp%energy_state_MoStabCorrMomBare(noahmp_c) = min(noahmp%energy_state_MoStabCorrMomBare(noahmp_c) , 0.9*TMPCM )
    noahmp%energy_state_MoStabCorrShBare2m(noahmp_c) = min(noahmp%energy_state_MoStabCorrShBare2m(noahmp_c) , 0.9*TMPCH2)
    noahmp%energy_state_MoStabCorrMomBare2m(noahmp_c) = min(noahmp%energy_state_MoStabCorrMomBare2m(noahmp_c), 0.9*TMPCM2)
    CMFM = TMPCM - noahmp%energy_state_MoStabCorrMomBare(noahmp_c)
    CHFH = TMPCH - noahmp%energy_state_MoStabCorrShBare(noahmp_c)
    CM2FM2 = TMPCM2 - noahmp%energy_state_MoStabCorrMomBare2m(noahmp_c)
    CH2FH2 = TMPCH2 - noahmp%energy_state_MoStabCorrShBare2m(noahmp_c)
    if ( abs(CMFM) <= MPE ) CMFM = MPE
    if ( abs(CHFH) <= MPE ) CHFH = MPE
    if ( abs(CM2FM2) <= MPE ) CM2FM2 = MPE
    if ( abs(CH2FH2) <= MPE ) CH2FH2 = MPE
    noahmp%energy_state_ExchCoeffMomBare(noahmp_c) = ConstVonKarman * ConstVonKarman / (CMFM * CMFM)
    noahmp%energy_state_ExchCoeffShBare(noahmp_c) = ConstVonKarman * ConstVonKarman / (CMFM * CHFH)
    noahmp%energy_state_FrictionVelBare(noahmp_c) = noahmp%energy_state_WindSpdRefHeight(noahmp_c) * sqrt(noahmp%energy_state_ExchCoeffMomBare(noahmp_c))
    noahmp%energy_state_ExchCoeffSh2mBareMo(noahmp_c) = ConstVonKarman * noahmp%energy_state_FrictionVelBare(noahmp_c) / CH2FH2
    noahmp%energy_state_ResistanceMomBareGrd(noahmp_c) = max(1.0, 1.0/(noahmp%energy_state_ExchCoeffMomBare(noahmp_c)*noahmp%energy_state_WindSpdRefHeight(noahmp_c)))
    noahmp%energy_state_ResistanceShBareGrd(noahmp_c) = max(1.0, 1.0/(noahmp%energy_state_ExchCoeffShBare(noahmp_c)*noahmp%energy_state_WindSpdRefHeight(noahmp_c)))
    noahmp%energy_state_ResistanceLhBareGrd(noahmp_c) = noahmp%energy_state_ResistanceShBareGrd(noahmp_c)
  end subroutine ResistanceBareGroundMOST
end module lean_resistancebaregroundmostmod

! Also from: physics_noahmp/src/ResistanceBareGroundChen97Mod.F90
module lean_resistancebaregroundchen97mod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine ResistanceBareGroundChen97(noahmp, noahmp_c, IndIter)
 !$acc routine seq
    implicit none
    integer , intent(in ) :: IndIter
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: ILECH, ITR
    real(kind=kind_noahmp) :: ZZ, PSLMU, PSLMS, PSLHU, PSLHS
    real(kind=kind_noahmp) :: XX, PSPMU, YY, PSPMS, PSPHU, PSPHS
    real(kind=kind_noahmp) :: ZILFC, ZU, ZT, RDZ, CXCH, DTHV, DU2
    real(kind=kind_noahmp) :: BTGH, ZSLU, ZSLT, RLOGU, RLOGT, RLMA
    real(kind=kind_noahmp) :: ZETALT, ZETALU, ZETAU, ZETAT, XLU4
    real(kind=kind_noahmp) :: XLT4, XU4, XT4, XLU, XLT, XU, XT
    real(kind=kind_noahmp) :: PSMZ, SIMM, PSHZ, SIMH, USTARK, RLMN
    integer , parameter :: ITRMX = 5
    real(kind=kind_noahmp), parameter :: WWST = 1.2
    real(kind=kind_noahmp), parameter :: WWST2 = WWST * WWST
    real(kind=kind_noahmp), parameter :: VKRM = 0.40
    real(kind=kind_noahmp), parameter :: EXCM = 0.001
    real(kind=kind_noahmp), parameter :: BETA = 1.0 / 270.0
    real(kind=kind_noahmp), parameter :: BTG = BETA * ConstGravityAcc
    real(kind=kind_noahmp), parameter :: ELFC = VKRM * BTG
    real(kind=kind_noahmp), parameter :: WOLD = 0.15
    real(kind=kind_noahmp), parameter :: WNEW = 1.0 - WOLD
    real(kind=kind_noahmp), parameter :: PIHF = 3.14159265 / 2.0
    real(kind=kind_noahmp), parameter :: EPSU2 = 1.0e-4
    real(kind=kind_noahmp), parameter :: EPSUST = 0.07
    real(kind=kind_noahmp), parameter :: EPSIT = 1.0e-4
    real(kind=kind_noahmp), parameter :: EPSA = 1.0e-8
    real(kind=kind_noahmp), parameter :: ZTMIN = -5.0
    real(kind=kind_noahmp), parameter :: ZTMAX = 1.0
    real(kind=kind_noahmp), parameter :: HPBL = 1000.0
    real(kind=kind_noahmp), parameter :: SQVISC = 258.2
    real(kind=kind_noahmp), parameter :: RIC = 0.183
    real(kind=kind_noahmp), parameter :: RRIC = 1.0 / RIC
    real(kind=kind_noahmp), parameter :: FHNEU = 0.8
    real(kind=kind_noahmp), parameter :: RFC = 0.191
    real(kind=kind_noahmp), parameter :: RFAC = RIC / ( FHNEU * RFC * RFC )
    PSLMU(ZZ) = -0.96 * log(1.0 - 4.5 * ZZ)
    PSLMS(ZZ) = ZZ * RRIC - 2.076 * (1.0 - 1.0/(ZZ + 1.0))
    PSLHU(ZZ) = -0.96 * log(1.0 - 4.5 * ZZ)
    PSLHS(ZZ) = ZZ * RFAC - 2.076 * (1.0 - 1.0/(ZZ + 1.0))
    PSPMU(XX) = -2.0*log( (XX+1.0)*0.5 ) - log( (XX*XX+1.0)*0.5 ) + 2.0*atan(XX) - PIHF
    PSPMS(YY) = 5.0 * YY
    PSPHU(XX) = -2.0 * log( (XX*XX + 1.0)*0.5 )
    PSPHS(YY) = 5.0 * YY
    ILECH = 0
    ZILFC = -noahmp%energy_param_ZilitinkevichCoeff(noahmp_c) * VKRM * SQVISC
    ZU = noahmp%energy_state_RoughLenMomGrd(noahmp_c)
    RDZ = 1.0 / noahmp%energy_state_RefHeightAboveGrd(noahmp_c)
    CXCH = EXCM * RDZ
    DTHV = noahmp%energy_state_TemperaturePotRefHeight(noahmp_c) - noahmp%energy_state_TemperatureGrdBare(noahmp_c)
    DU2 = max(noahmp%energy_state_WindSpdRefHeight(noahmp_c)*noahmp%energy_state_WindSpdRefHeight(noahmp_c), EPSU2)
    BTGH = BTG * HPBL
    if ( IndIter == 1 ) then
      if ( (BTGH*noahmp%energy_state_ExchCoeffShBare(noahmp_c)*DTHV) /= 0.0 ) then
        noahmp%energy_state_FrictionVelVertBare(noahmp_c) = WWST2 * abs(BTGH*noahmp%energy_state_ExchCoeffShBare(noahmp_c)*DTHV)**(2.0/3.0)
      else
        noahmp%energy_state_FrictionVelVertBare(noahmp_c) = 0.0
      endif
      noahmp%energy_state_FrictionVelBare(noahmp_c) = max(sqrt(noahmp%energy_state_ExchCoeffMomBare(noahmp_c)*sqrt(DU2+noahmp%energy_state_FrictionVelVertBare(noahmp_c))), EPSUST)
      noahmp%energy_state_MoStabParaBare(noahmp_c) = ELFC * noahmp%energy_state_ExchCoeffShBare(noahmp_c) * DTHV / noahmp%energy_state_FrictionVelBare(noahmp_c)**3
    endif
    ZT = max(1.0e-6, exp(ZILFC*sqrt(noahmp%energy_state_FrictionVelBare(noahmp_c)*noahmp%energy_state_RoughLenMomGrd(noahmp_c)))*noahmp%energy_state_RoughLenMomGrd(noahmp_c))
    ZSLU = noahmp%energy_state_RefHeightAboveGrd(noahmp_c) + ZU
    ZSLT = noahmp%energy_state_RefHeightAboveGrd(noahmp_c) + ZT
    RLOGU = log(ZSLU / ZU)
    RLOGT = log(ZSLT / ZT)
    ZETALT = max(ZSLT*noahmp%energy_state_MoStabParaBare(noahmp_c), ZTMIN)
    noahmp%energy_state_MoStabParaBare(noahmp_c) = ZETALT / ZSLT
    ZETALU = ZSLU * noahmp%energy_state_MoStabParaBare(noahmp_c)
    ZETAU = ZU * noahmp%energy_state_MoStabParaBare(noahmp_c)
    ZETAT = ZT * noahmp%energy_state_MoStabParaBare(noahmp_c)
    if ( ILECH == 0 ) then
      if ( noahmp%energy_state_MoStabParaBare(noahmp_c) < 0.0 ) then
        XLU4 = 1.0 - 16.0 * ZETALU
        XLT4 = 1.0 - 16.0 * ZETALT
        XU4 = 1.0 - 16.0 * ZETAU
        XT4 = 1.0 - 16.0 * ZETAT
        XLU = sqrt(sqrt(XLU4))
        XLT = sqrt(sqrt(XLT4))
        XU = sqrt(sqrt(XU4))
        XT = sqrt(sqrt(XT4))
        PSMZ = PSPMU(XU)
        SIMM = PSPMU(XLU) - PSMZ + RLOGU
        PSHZ = PSPHU(XT)
        SIMH = PSPHU(XLT) - PSHZ + RLOGT
      else
        ZETALU = min(ZETALU, ZTMAX)
        ZETALT = min(ZETALT, ZTMAX)
        ZETAU = min(ZETAU, ZTMAX/(ZSLU/ZU))
        ZETAT = min(ZETAT, ZTMAX/(ZSLT/ZT))
        PSMZ = PSPMS(ZETAU)
        SIMM = PSPMS(ZETALU) - PSMZ + RLOGU
        PSHZ = PSPHS(ZETAT)
        SIMH = PSPHS(ZETALT) - PSHZ + RLOGT
      endif
    else
      if ( noahmp%energy_state_MoStabParaBare(noahmp_c) < 0.0 ) then
        PSMZ = PSLMU(ZETAU)
        SIMM = PSLMU(ZETALU) - PSMZ + RLOGU
        PSHZ = PSLHU(ZETAT)
        SIMH = PSLHU(ZETALT) - PSHZ + RLOGT
      else
        ZETALU = min(ZETALU, ZTMAX)
        ZETALT = min(ZETALT, ZTMAX)
        PSMZ = PSLMS(ZETAU)
        SIMM = PSLMS(ZETALU) - PSMZ + RLOGU
        PSHZ = PSLHS(ZETAT)
        SIMH = PSLHS(ZETALT) - PSHZ + RLOGT
      endif
    endif
    noahmp%energy_state_FrictionVelBare(noahmp_c) = max(sqrt(noahmp%energy_state_ExchCoeffMomBare(noahmp_c)*sqrt(DU2+noahmp%energy_state_FrictionVelVertBare(noahmp_c))), EPSUST)
    ZT = max(1.0e-6, exp(ZILFC*sqrt(noahmp%energy_state_FrictionVelBare(noahmp_c)*noahmp%energy_state_RoughLenMomGrd(noahmp_c)))*noahmp%energy_state_RoughLenMomGrd(noahmp_c))
    ZSLT = noahmp%energy_state_RefHeightAboveGrd(noahmp_c) + ZT
    RLOGT = log(ZSLT/ZT)
    USTARK = noahmp%energy_state_FrictionVelBare(noahmp_c) * VKRM
    if ( SIMM < 1.0e-6 ) SIMM = 1.0e-6
    noahmp%energy_state_ExchCoeffMomBare(noahmp_c) = max(USTARK/SIMM, CXCH)
    if ( SIMH < 1.0e-6 ) SIMH = 1.0e-6
    noahmp%energy_state_ExchCoeffShBare(noahmp_c) = max(USTARK/SIMH, CXCH)
    if ( BTGH*noahmp%energy_state_ExchCoeffShBare(noahmp_c)*DTHV /= 0.0 ) then
      noahmp%energy_state_FrictionVelVertBare(noahmp_c) = WWST2 * abs(BTGH*noahmp%energy_state_ExchCoeffShBare(noahmp_c)*DTHV)**(2.0/3.0)
    else
      noahmp%energy_state_FrictionVelVertBare(noahmp_c) = 0.0
    endif
    RLMN = ELFC * noahmp%energy_state_ExchCoeffShBare(noahmp_c) * DTHV / noahmp%energy_state_FrictionVelBare(noahmp_c)**3
    RLMA = noahmp%energy_state_MoStabParaBare(noahmp_c) * WOLD + RLMN * WNEW
    noahmp%energy_state_MoStabParaBare(noahmp_c) = RLMA
    noahmp%energy_state_ExchCoeffShBare(noahmp_c) = noahmp%energy_state_ExchCoeffShBare(noahmp_c) / noahmp%energy_state_WindSpdRefHeight(noahmp_c)
    noahmp%energy_state_ExchCoeffMomBare(noahmp_c) = noahmp%energy_state_ExchCoeffMomBare(noahmp_c) / noahmp%energy_state_WindSpdRefHeight(noahmp_c)
    if ( noahmp%water_state_SnowDepth(noahmp_c) > 0.0 ) then
      noahmp%energy_state_ExchCoeffMomBare(noahmp_c) = min(0.01, noahmp%energy_state_ExchCoeffMomBare(noahmp_c))
      noahmp%energy_state_ExchCoeffShBare(noahmp_c) = min(0.01, noahmp%energy_state_ExchCoeffShBare(noahmp_c))
    endif
    noahmp%energy_state_ResistanceMomBareGrd(noahmp_c) = max(1.0, 1.0/(noahmp%energy_state_ExchCoeffMomBare(noahmp_c)*noahmp%energy_state_WindSpdRefHeight(noahmp_c)))
    noahmp%energy_state_ResistanceShBareGrd(noahmp_c) = max(1.0, 1.0/(noahmp%energy_state_ExchCoeffShBare(noahmp_c)*noahmp%energy_state_WindSpdRefHeight(noahmp_c)))
    noahmp%energy_state_ResistanceLhBareGrd(noahmp_c) = noahmp%energy_state_ResistanceShBareGrd(noahmp_c)
  end subroutine ResistanceBareGroundChen97
end module lean_resistancebaregroundchen97mod

! Source: physics_noahmp/src/SurfaceEnergyFluxBareGroundMod.F90
module lean_surfaceenergyfluxbaregroundmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_vaporpressuresaturationmod, only : VaporPressureSaturation
  use lean_resistancebaregroundmostmod, only : ResistanceBareGroundMOST
  use lean_resistancebaregroundchen97mod, only : ResistanceBareGroundChen97
  implicit none
  contains
  subroutine SurfaceEnergyFluxBareGround(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: IndIter
    integer :: MoStabParaSgn
    integer, parameter :: NumIter = 5
    real(kind=kind_noahmp) :: TemperatureGrdChg
    real(kind=kind_noahmp) :: LwRadCoeff
    real(kind=kind_noahmp) :: ShCoeff
    real(kind=kind_noahmp) :: LhCoeff
    real(kind=kind_noahmp) :: GrdHeatCoeff
    real(kind=kind_noahmp) :: ExchCoeffShTmp
    real(kind=kind_noahmp) :: ExchCoeffMomTmp
    real(kind=kind_noahmp) :: MoistureFluxSfc
    real(kind=kind_noahmp) :: VapPresSatWatTmp
    real(kind=kind_noahmp) :: VapPresSatIceTmp
    real(kind=kind_noahmp) :: VapPresSatWatTmpD
    real(kind=kind_noahmp) :: VapPresSatIceTmpD
    real(kind=kind_noahmp) :: FluxTotCoeff
    real(kind=kind_noahmp) :: EnergyResTmp
    real(kind=kind_noahmp) :: HeatSensibleTmp
    real(kind=kind_noahmp) :: TempTmp
    real(kind=kind_noahmp) :: TempUnitConv
    TempUnitConv(TempTmp) = min(50.0, max(-50.0, (TempTmp-ConstFreezePoint)))
    associate( OptSurfaceDrag => noahmp_opt_sfc )
    TemperatureGrdChg = 0.0
    noahmp%energy_state_MoStabParaBare(noahmp_c) = 0.0
    MoStabParaSgn = 0
    noahmp%energy_state_MoStabCorrShBare2m(noahmp_c) = 0.0
    MoistureFluxSfc = 0.0
    noahmp%energy_state_FrictionVelBare(noahmp_c) = 0.1
    HeatSensibleTmp = 0.0
    LwRadCoeff = noahmp%energy_state_EmissivityGrd(noahmp_c) * ConstStefanBoltzmann
    GrdHeatCoeff = 2.0*noahmp%energy_state_ThermConductSoilSnow(noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, noahmp_c)/noahmp%config_domain_ThicknessSnowSoilLayer(noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, noahmp_c)
    loop3: do IndIter = 1, NumIter
    if ( IndIter == 1 ) then
      noahmp%energy_state_RoughLenShBareGrd(noahmp_c) = noahmp%energy_state_RoughLenMomGrd(noahmp_c)
    else
      noahmp%energy_state_RoughLenShBareGrd(noahmp_c) = noahmp%energy_state_RoughLenMomGrd(noahmp_c)
    endif
 if (noahmp_opt_sfc == 2) then
    call ResistanceBareGroundChen97(noahmp, noahmp_c, IndIter)
 else
    call ResistanceBareGroundMOST(noahmp, noahmp_c, IndIter, HeatSensibleTmp, MoStabParaSgn)
 end if
    ExchCoeffMomTmp = 1.0 / noahmp%energy_state_ResistanceMomBareGrd(noahmp_c)
    ExchCoeffShTmp = 1.0 / noahmp%energy_state_ResistanceShBareGrd(noahmp_c)
    TempTmp = TempUnitConv(noahmp%energy_state_TemperatureGrdBare(noahmp_c))
    call VaporPressureSaturation(TempTmp, VapPresSatWatTmp, VapPresSatIceTmp, VapPresSatWatTmpD, &
      & VapPresSatIceTmpD)
    if ( TempTmp > 0.0 ) then
      noahmp%energy_state_VapPresSatGrdBare(noahmp_c) = VapPresSatWatTmp
      noahmp%energy_state_VapPresSatGrdBareTempD(noahmp_c) = VapPresSatWatTmpD
    else
      noahmp%energy_state_VapPresSatGrdBare(noahmp_c) = VapPresSatIceTmp
      noahmp%energy_state_VapPresSatGrdBareTempD(noahmp_c) = VapPresSatIceTmpD
    endif
    ShCoeff = noahmp%energy_state_DensityAirRefHeight(noahmp_c) * ConstHeatCapacAir / noahmp%energy_state_ResistanceShBareGrd(noahmp_c)
    LhCoeff = noahmp%energy_state_DensityAirRefHeight(noahmp_c) * ConstHeatCapacAir / noahmp%energy_state_PsychConstGrd(noahmp_c) / (noahmp%energy_state_ResistanceGrdEvap(noahmp_c)+noahmp%energy_state_ResistanceLhBareGrd(noahmp_c))
    noahmp%energy_flux_RadLwNetBareGrd(noahmp_c) = LwRadCoeff * runtime_fourth_power(noahmp%energy_state_TemperatureGrdBare(noahmp_c)) - noahmp%energy_state_EmissivityGrd(noahmp_c) * noahmp%forcing_RadLwDownRefHeight(noahmp_c)
    noahmp%energy_flux_HeatSensibleBareGrd(noahmp_c) = ShCoeff * (noahmp%energy_state_TemperatureGrdBare(noahmp_c) - noahmp%forcing_TemperatureAirRefHeight(noahmp_c))
    noahmp%energy_flux_HeatLatentBareGrd(noahmp_c) = LhCoeff * (noahmp%energy_state_VapPresSatGrdBare(noahmp_c)*noahmp%energy_state_RelHumidityGrd(noahmp_c) - noahmp%energy_state_PressureVaporRefHeight(noahmp_c))
    noahmp%energy_flux_HeatGroundBareGrd(noahmp_c) = GrdHeatCoeff * (noahmp%energy_state_TemperatureGrdBare(noahmp_c) - noahmp%energy_state_TemperatureSoilSnow(noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, noahmp_c))
    EnergyResTmp = noahmp%energy_flux_RadSwAbsGrd(noahmp_c) - noahmp%energy_flux_RadLwNetBareGrd(noahmp_c) - noahmp%energy_flux_HeatSensibleBareGrd(noahmp_c) - noahmp%energy_flux_HeatLatentBareGrd(noahmp_c) - noahmp%energy_flux_HeatGroundBareGrd(noahmp_c) + noahmp%energy_flux_HeatPrecipAdvBareGrd(noahmp_c)
    FluxTotCoeff = 4.0*LwRadCoeff*noahmp%energy_state_TemperatureGrdBare(noahmp_c)**3 + ShCoeff + LhCoeff*noahmp%energy_state_VapPresSatGrdBareTempD(noahmp_c) + GrdHeatCoeff
    TemperatureGrdChg = EnergyResTmp / FluxTotCoeff
    noahmp%energy_flux_RadLwNetBareGrd(noahmp_c) = noahmp%energy_flux_RadLwNetBareGrd(noahmp_c) + 4.0 * LwRadCoeff * noahmp%energy_state_TemperatureGrdBare(noahmp_c)**3 * TemperatureGrdChg
    noahmp%energy_flux_HeatSensibleBareGrd(noahmp_c) = noahmp%energy_flux_HeatSensibleBareGrd(noahmp_c) + ShCoeff * TemperatureGrdChg
    noahmp%energy_flux_HeatLatentBareGrd(noahmp_c) = noahmp%energy_flux_HeatLatentBareGrd(noahmp_c) + LhCoeff * noahmp%energy_state_VapPresSatGrdBareTempD(noahmp_c) * TemperatureGrdChg
    noahmp%energy_flux_HeatGroundBareGrd(noahmp_c) = noahmp%energy_flux_HeatGroundBareGrd(noahmp_c) + GrdHeatCoeff * TemperatureGrdChg
    noahmp%energy_state_TemperatureGrdBare(noahmp_c) = noahmp%energy_state_TemperatureGrdBare(noahmp_c) + TemperatureGrdChg
    HeatSensibleTmp = ShCoeff * (noahmp%energy_state_TemperatureGrdBare(noahmp_c) - noahmp%forcing_TemperatureAirRefHeight(noahmp_c))
    TempTmp = TempUnitConv(noahmp%energy_state_TemperatureGrdBare(noahmp_c))
    call VaporPressureSaturation(TempTmp, VapPresSatWatTmp, VapPresSatIceTmp, VapPresSatWatTmpD, &
      & VapPresSatIceTmpD)
    if ( TempTmp > 0.0 ) then
      noahmp%energy_state_VapPresSatGrdBare(noahmp_c) = VapPresSatWatTmp
    else
      noahmp%energy_state_VapPresSatGrdBare(noahmp_c) = VapPresSatIceTmp
    endif
    noahmp%energy_state_SpecHumiditySfc(noahmp_c) = 0.622 * (noahmp%energy_state_VapPresSatGrdBare(noahmp_c)*noahmp%energy_state_RelHumidityGrd(noahmp_c)) / (noahmp%forcing_PressureAirRefHeight(noahmp_c) - 0.378 * (noahmp%energy_state_VapPresSatGrdBare(noahmp_c)*noahmp%energy_state_RelHumidityGrd(noahmp_c)))
    MoistureFluxSfc = (noahmp%energy_state_SpecHumiditySfc(noahmp_c) - noahmp%forcing_SpecHumidityRefHeight(noahmp_c)) * LhCoeff * noahmp%energy_state_PsychConstGrd(noahmp_c) / ConstHeatCapacAir
  enddo loop3
  if ( (noahmp%water_state_SnowDepth(noahmp_c) > 0.05) .and. (noahmp%energy_state_TemperatureGrdBare(noahmp_c) > ConstFreezePoint) ) then
    noahmp%energy_state_TemperatureGrdBare(noahmp_c) = ConstFreezePoint
    noahmp%energy_flux_RadLwNetBareGrd(noahmp_c) = LwRadCoeff * runtime_fourth_power(noahmp%energy_state_TemperatureGrdBare(noahmp_c)) - noahmp%energy_state_EmissivityGrd(noahmp_c) * noahmp%forcing_RadLwDownRefHeight(noahmp_c)
    noahmp%energy_flux_HeatSensibleBareGrd(noahmp_c) = ShCoeff * (noahmp%energy_state_TemperatureGrdBare(noahmp_c) - noahmp%forcing_TemperatureAirRefHeight(noahmp_c))
    noahmp%energy_flux_HeatLatentBareGrd(noahmp_c) = LhCoeff * (noahmp%energy_state_VapPresSatGrdBare(noahmp_c)*noahmp%energy_state_RelHumidityGrd(noahmp_c) - noahmp%energy_state_PressureVaporRefHeight(noahmp_c))
    noahmp%energy_flux_HeatGroundBareGrd(noahmp_c) = noahmp%energy_flux_RadSwAbsGrd(noahmp_c) + noahmp%energy_flux_HeatPrecipAdvBareGrd(noahmp_c) - (noahmp%energy_flux_RadLwNetBareGrd(noahmp_c) + noahmp%energy_flux_HeatSensibleBareGrd(noahmp_c) + noahmp%energy_flux_HeatLatentBareGrd(noahmp_c))
  endif
  noahmp%energy_state_WindStressEwBare(noahmp_c) = -noahmp%energy_state_DensityAirRefHeight(noahmp_c) * noahmp%energy_state_ExchCoeffMomBare(noahmp_c) * noahmp%energy_state_WindSpdRefHeight(noahmp_c) * noahmp%forcing_WindEastwardRefHeight(noahmp_c)
  noahmp%energy_state_WindStressNsBare(noahmp_c) = -noahmp%energy_state_DensityAirRefHeight(noahmp_c) * noahmp%energy_state_ExchCoeffMomBare(noahmp_c) * noahmp%energy_state_WindSpdRefHeight(noahmp_c) * noahmp%forcing_WindNorthwardRefHeight(noahmp_c)
  noahmp%energy_state_ExchCoeffSh2mBare(noahmp_c) = noahmp%energy_state_FrictionVelBare(noahmp_c) * ConstVonKarman / (log((2.0+noahmp%energy_state_RoughLenShBareGrd(noahmp_c))/noahmp%energy_state_RoughLenShBareGrd(noahmp_c)) - noahmp%energy_state_MoStabCorrShBare2m(noahmp_c))
  if ( noahmp%energy_state_ExchCoeffSh2mBare(noahmp_c) < 1.0e-5 ) then
    noahmp%energy_state_TemperatureAir2mBare(noahmp_c) = noahmp%energy_state_TemperatureGrdBare(noahmp_c)
    noahmp%energy_state_SpecHumidity2mBare(noahmp_c) = noahmp%energy_state_SpecHumiditySfc(noahmp_c)
  else
    noahmp%energy_state_TemperatureAir2mBare(noahmp_c) = noahmp%energy_state_TemperatureGrdBare(noahmp_c) - noahmp%energy_flux_HeatSensibleBareGrd(noahmp_c) / (noahmp%energy_state_DensityAirRefHeight(noahmp_c)*ConstHeatCapacAir) * 1.0 / noahmp%energy_state_ExchCoeffSh2mBare(noahmp_c)
    noahmp%energy_state_SpecHumidity2mBare(noahmp_c) = noahmp%energy_state_SpecHumiditySfc(noahmp_c) - noahmp%energy_flux_HeatLatentBareGrd(noahmp_c) / (noahmp%energy_state_LatHeatVapGrd(noahmp_c)*noahmp%energy_state_DensityAirRefHeight(noahmp_c)) * (1.0/noahmp%energy_state_ExchCoeffSh2mBare(noahmp_c) + noahmp%energy_state_ResistanceGrdEvap(noahmp_c))
  endif
  if ( noahmp%config_domain_FlagUrban(noahmp_c) .eqv. .true. ) noahmp%energy_state_SpecHumidity2mBare(noahmp_c) = noahmp%energy_state_SpecHumiditySfc(noahmp_c)
  noahmp%energy_state_ExchCoeffShBare(noahmp_c) = ExchCoeffShTmp
  end associate
end subroutine SurfaceEnergyFluxBareGround
end module lean_surfaceenergyfluxbaregroundmod

! Source: physics_noahmp/src/MatrixSolverTriDiagonalMod.F90
module lean_matrixsolvertridiagonalmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine MatrixSolverTriDiagonal(P, A, B, C, D, Delta, IndTopLayer, NumSoilLayer, NumSnowLayerMax)
 !$acc routine seq
    implicit none
    integer , intent(in) :: IndTopLayer
    integer , intent(in) :: NumSoilLayer
    integer , intent(in) :: NumSnowLayerMax
    real(kind=kind_noahmp), dimension(-NumSnowLayerMax+1:NumSoilLayer), intent(in) :: A, B, D
    real(kind=kind_noahmp), dimension(-NumSnowLayerMax+1:NumSoilLayer), intent(inout) :: C,P,Delta
    integer :: K, KK
    C (NumSoilLayer) = 0.0
    P (IndTopLayer) = - C (IndTopLayer) / B (IndTopLayer)
    Delta (IndTopLayer) = D (IndTopLayer) / B (IndTopLayer)
    do K = IndTopLayer+1, NumSoilLayer
      P (K) = - C (K) * ( 1.0 / (B (K) + A (K) * P (K -1)) )
      Delta (K) = (D (K) - A (K) * Delta (K -1)) * (1.0 / (B (K) + A (K) * P (K -1)))
    enddo
    P (NumSoilLayer) = Delta (NumSoilLayer)
    do K = IndTopLayer+1, NumSoilLayer
      KK = NumSoilLayer - K + (IndTopLayer-1) + 1
      P (KK) = P (KK) * P (KK +1) + Delta (KK)
    enddo
  end subroutine MatrixSolverTriDiagonal
end module lean_matrixsolvertridiagonalmod

! Source: physics_noahmp/src/SoilSnowTemperatureSolverMod.F90
module lean_soilsnowtemperaturesolvermod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_matrixsolvertridiagonalmod, only : MatrixSolverTriDiagonal
  implicit none
  contains
  subroutine SoilSnowTemperatureSolver(noahmp, noahmp_c, TimeStep, MatLeft1, MatLeft2, MatLeft3, MatRight)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    real(kind=kind_noahmp), intent(in) :: TimeStep
    real(kind=kind_noahmp), dimension(-2:4), intent(inout) :: MatRight
    real(kind=kind_noahmp), dimension(-2:4), intent(inout) :: MatLeft1
    real(kind=kind_noahmp), dimension(-2:4), intent(inout) :: MatLeft2
    real(kind=kind_noahmp), dimension(-2:4), intent(inout) :: MatLeft3
    integer :: LoopInd
    real(kind=kind_noahmp), dimension(-2:4) :: MatRightTmp
    real(kind=kind_noahmp), dimension(-2:4) :: MatLeft3Tmp
    MatRightTmp = 0.0
    MatLeft3Tmp = 0.0
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 4
      MatRight(LoopInd) = MatRight(LoopInd) * TimeStep
      MatLeft1(LoopInd) = MatLeft1(LoopInd) * TimeStep
      MatLeft2(LoopInd) = 1.0 + MatLeft2(LoopInd) * TimeStep
      MatLeft3(LoopInd) = MatLeft3(LoopInd) * TimeStep
    enddo
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 4
      MatRightTmp(LoopInd) = MatRight(LoopInd)
      MatLeft3Tmp(LoopInd) = MatLeft3(LoopInd)
    enddo
    call MatrixSolverTriDiagonal(MatLeft3,MatLeft1,MatLeft2,MatLeft3Tmp,MatRightTmp, MatRight, &
      & noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1,4,3)
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 4
      noahmp%energy_state_TemperatureSoilSnow(LoopInd, noahmp_c) = noahmp%energy_state_TemperatureSoilSnow(LoopInd, noahmp_c) + MatLeft3(LoopInd)
    enddo
  end subroutine SoilSnowTemperatureSolver
end module lean_soilsnowtemperaturesolvermod

! Source: physics_noahmp/src/SoilSnowThermalDiffusionMod.F90
module lean_soilsnowthermaldiffusionmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine SoilSnowThermalDiffusion(noahmp, noahmp_c, MatLeft1, MatLeft2, MatLeft3, MatRight)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    real(kind=kind_noahmp), dimension(-2:4), intent(inout) :: MatRight
    real(kind=kind_noahmp), dimension(-2:4), intent(inout) :: MatLeft1
    real(kind=kind_noahmp), dimension(-2:4), intent(inout) :: MatLeft2
    real(kind=kind_noahmp), dimension(-2:4), intent(inout) :: MatLeft3
    integer :: LoopInd
    real(kind=kind_noahmp) :: DepthSnowSoilTmp
    real(kind=kind_noahmp), dimension(-2:4) :: DepthSnowSoilInv
    real(kind=kind_noahmp), dimension(-2:4) :: HeatCapacPerArea
    real(kind=kind_noahmp), dimension(-2:4) :: TempGradDepth
    real(kind=kind_noahmp), dimension(-2:4) :: EnergyExcess
    MatRight(:) = 0.0
    MatLeft1(:) = 0.0
    MatLeft2(:) = 0.0
    MatLeft3(:) = 0.0
    DepthSnowSoilInv(:) = 0.0
    HeatCapacPerArea(:) = 0.0
    TempGradDepth(:) = 0.0
    EnergyExcess(:) = 0.0
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 4
      if ( LoopInd == (noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1) ) then
        HeatCapacPerArea(LoopInd) = - noahmp%config_domain_DepthSnowSoilLayer(LoopInd, noahmp_c) * noahmp%energy_state_HeatCapacSoilSnow(LoopInd, noahmp_c)
        DepthSnowSoilTmp = - noahmp%config_domain_DepthSnowSoilLayer(LoopInd+1, noahmp_c)
        DepthSnowSoilInv(LoopInd) = 2.0 / DepthSnowSoilTmp
        TempGradDepth(LoopInd) = 2.0 * (noahmp%energy_state_TemperatureSoilSnow(LoopInd, noahmp_c) - noahmp%energy_state_TemperatureSoilSnow(LoopInd+1, noahmp_c)) / DepthSnowSoilTmp
        EnergyExcess(LoopInd) = noahmp%energy_state_ThermConductSoilSnow(LoopInd, noahmp_c) * TempGradDepth(LoopInd) - noahmp%energy_flux_HeatGroundTotMean(noahmp_c) - noahmp%energy_flux_RadSwPenetrateGrd(LoopInd, noahmp_c)
      elseif ( LoopInd < 4 ) then
        HeatCapacPerArea(LoopInd) = (noahmp%config_domain_DepthSnowSoilLayer(LoopInd-1, noahmp_c) - noahmp%config_domain_DepthSnowSoilLayer(LoopInd, noahmp_c)) * noahmp%energy_state_HeatCapacSoilSnow(LoopInd, noahmp_c)
        DepthSnowSoilTmp = noahmp%config_domain_DepthSnowSoilLayer(LoopInd-1, noahmp_c) - noahmp%config_domain_DepthSnowSoilLayer(LoopInd+1, noahmp_c)
        DepthSnowSoilInv(LoopInd) = 2.0 / DepthSnowSoilTmp
        TempGradDepth(LoopInd) = 2.0 * (noahmp%energy_state_TemperatureSoilSnow(LoopInd, noahmp_c) - noahmp%energy_state_TemperatureSoilSnow(LoopInd+1, noahmp_c)) / DepthSnowSoilTmp
        EnergyExcess(LoopInd) = (noahmp%energy_state_ThermConductSoilSnow(LoopInd, noahmp_c)*TempGradDepth(LoopInd) - noahmp%energy_state_ThermConductSoilSnow(LoopInd-1, noahmp_c) * TempGradDepth(LoopInd-1) ) - noahmp%energy_flux_RadSwPenetrateGrd(LoopInd, noahmp_c)
      elseif ( LoopInd == 4 ) then
        HeatCapacPerArea(LoopInd) = (noahmp%config_domain_DepthSnowSoilLayer(LoopInd-1, noahmp_c) - noahmp%config_domain_DepthSnowSoilLayer(LoopInd, noahmp_c)) * noahmp%energy_state_HeatCapacSoilSnow(LoopInd, noahmp_c)
        DepthSnowSoilTmp = noahmp%config_domain_DepthSnowSoilLayer(LoopInd-1, noahmp_c) - noahmp%config_domain_DepthSnowSoilLayer(LoopInd, noahmp_c)
        TempGradDepth(LoopInd) = (noahmp%energy_state_TemperatureSoilSnow(LoopInd, noahmp_c) - noahmp%forcing_TemperatureSoilBottom(noahmp_c)) / (0.5*(noahmp%config_domain_DepthSnowSoilLayer(LoopInd-1, noahmp_c)+noahmp%config_domain_DepthSnowSoilLayer(LoopInd, noahmp_c)) - noahmp%energy_state_DepthSoilTempBotToSno(noahmp_c))
        noahmp%energy_flux_HeatFromSoilBot(noahmp_c) = -noahmp%energy_state_ThermConductSoilSnow(LoopInd, noahmp_c) * TempGradDepth(LoopInd)
        EnergyExcess(LoopInd) = (-noahmp%energy_flux_HeatFromSoilBot(noahmp_c) - noahmp%energy_state_ThermConductSoilSnow(LoopInd-1, noahmp_c) * TempGradDepth(LoopInd-1)) - noahmp%energy_flux_RadSwPenetrateGrd(LoopInd, noahmp_c)
      endif
    enddo
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 4
      if ( LoopInd == (noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1) ) then
        MatLeft1(LoopInd) = 0.0
        MatLeft3(LoopInd) = - noahmp%energy_state_ThermConductSoilSnow(LoopInd, noahmp_c) * DepthSnowSoilInv(LoopInd) / HeatCapacPerArea(LoopInd)
        MatLeft2(LoopInd) = - MatLeft3(LoopInd)
      elseif ( LoopInd < 4 ) then
        MatLeft1(LoopInd) = - noahmp%energy_state_ThermConductSoilSnow(LoopInd-1, noahmp_c) * DepthSnowSoilInv(LoopInd-1) / HeatCapacPerArea(LoopInd)
        MatLeft3(LoopInd) = - noahmp%energy_state_ThermConductSoilSnow(LoopInd , noahmp_c) * DepthSnowSoilInv(LoopInd ) / HeatCapacPerArea(LoopInd)
        MatLeft2(LoopInd) = - (MatLeft1(LoopInd) + MatLeft3 (LoopInd))
      elseif ( LoopInd == 4 ) then
        MatLeft1(LoopInd) = - noahmp%energy_state_ThermConductSoilSnow(LoopInd-1, noahmp_c) * DepthSnowSoilInv(LoopInd-1) / HeatCapacPerArea(LoopInd)
        MatLeft3(LoopInd) = 0.0
        MatLeft2(LoopInd) = - (MatLeft1(LoopInd) + MatLeft3(LoopInd))
      endif
      MatRight(LoopInd) = EnergyExcess(LoopInd) / (-HeatCapacPerArea(LoopInd))
    enddo
  end subroutine SoilSnowThermalDiffusion
end module lean_soilsnowthermaldiffusionmod

! Source: physics_noahmp/src/SoilSnowTemperatureMainMod.F90
module lean_soilsnowtemperaturemainmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_soilsnowtemperaturesolvermod, only : SoilSnowTemperatureSolver
  use lean_soilsnowthermaldiffusionmod, only : SoilSnowThermalDiffusion
  implicit none
  contains
  subroutine SoilSnowTemperatureMain(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    real(kind=kind_noahmp), dimension(-2:4) :: MatRight
    real(kind=kind_noahmp), dimension(-2:4) :: MatLeft1
    real(kind=kind_noahmp), dimension(-2:4) :: MatLeft2
    real(kind=kind_noahmp), dimension(-2:4) :: MatLeft3
    MatRight(:) = 0.0
    MatLeft1(:) = 0.0
    MatLeft2(:) = 0.0
    MatLeft3(:) = 0.0
    noahmp%energy_flux_RadSwPenetrateGrd(noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1:4, noahmp_c) = 0.0
    noahmp%energy_state_DepthSoilTempBotToSno(noahmp_c) = noahmp%config_domain_DepthSoilTempBottom(noahmp_c) - noahmp%water_state_SnowDepth(noahmp_c)
    call SoilSnowThermalDiffusion(noahmp, noahmp_c, MatLeft1, MatLeft2, MatLeft3, MatRight)
    call SoilSnowTemperatureSolver(noahmp, noahmp_c, noahmp%config_domain_SoilTimeStep(noahmp_c), MatLeft1, MatLeft2, MatLeft3, MatRight)
    noahmp%energy_flux_HeatFromSoilBot(noahmp_c) = noahmp%energy_flux_HeatFromSoilBot(noahmp_c) * noahmp%config_domain_SoilTimeStep(noahmp_c)
  end subroutine SoilSnowTemperatureMain
end module lean_soilsnowtemperaturemainmod

! Source: physics_noahmp/src/SoilWaterSupercoolNiu06Mod.F90
module lean_soilwatersupercoolniu06mod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine SoilWaterSupercoolNiu06(noahmp, noahmp_c, IndSoil, SoilWatSupercool, SoilTemperature)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer , intent(in ) :: IndSoil
    real(kind=kind_noahmp), intent(in ) :: SoilTemperature
    real(kind=kind_noahmp), intent(out ) :: SoilWatSupercool
    real(kind=kind_noahmp) :: SoilWatPotFrz
    SoilWatPotFrz = ConstLatHeatFusion * (ConstFreezePoint - SoilTemperature) / (ConstGravityAcc * SoilTemperature)
    SoilWatSupercool = noahmp%water_param_SoilMoistureSat(IndSoil, noahmp_c) * (SoilWatPotFrz / noahmp%water_param_SoilMatPotentialSat(IndSoil, noahmp_c))**(-1.0/noahmp%water_param_SoilExpCoeffB(IndSoil, noahmp_c))
  end subroutine SoilWaterSupercoolNiu06
end module lean_soilwatersupercoolniu06mod

! Source: physics_noahmp/src/SoilSnowWaterPhaseChangeMod.F90
module lean_soilsnowwaterphasechangemod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_soilwatersupercoolniu06mod, only : SoilWaterSupercoolNiu06
  implicit none
  contains
  subroutine SoilSnowWaterPhaseChange(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: LoopInd
    real(kind=kind_noahmp) :: EnergyResLeft
    real(kind=kind_noahmp) :: SnowWaterPrev
    real(kind=kind_noahmp) :: SnowWaterRatio
    real(kind=kind_noahmp) :: HeatLhTotPhsChg
    real(kind=kind_noahmp), dimension(-2:4) :: EnergyRes
    real(kind=kind_noahmp), dimension(-2:4) :: WaterPhaseChg
    real(kind=kind_noahmp), dimension(-2:4) :: MassWatTotInit
    real(kind=kind_noahmp), dimension(-2:4) :: MassWatIceInit
    real(kind=kind_noahmp), dimension(-2:4) :: MassWatLiqInit
    real(kind=kind_noahmp), dimension(-2:4) :: MassWatIceTmp
    real(kind=kind_noahmp), dimension(-2:4) :: MassWatLiqTmp
    EnergyRes = 0.0
    WaterPhaseChg = 0.0
    MassWatTotInit = 0.0
    MassWatIceInit = 0.0
    MassWatLiqInit = 0.0
    MassWatIceTmp = 0.0
    MassWatLiqTmp = 0.0
    noahmp%water_flux_MeltGroundSnow(noahmp_c) = 0.0
    noahmp%water_state_PondSfcThinSnwMelt(noahmp_c) = 0.0
    HeatLhTotPhsChg = 0.0
    do LoopInd = -3+1, 4
      noahmp%water_state_SoilSupercoolWater(LoopInd, noahmp_c) = 0.0
    enddo
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 0
      MassWatIceTmp(LoopInd) = noahmp%water_state_SnowIce(LoopInd, noahmp_c)
      MassWatLiqTmp(LoopInd) = noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c)
    enddo
    do LoopInd = 1, 4
      MassWatLiqTmp(LoopInd) = noahmp%water_state_SoilLiqWater(LoopInd, noahmp_c) * noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c) * 1000.0
      MassWatIceTmp(LoopInd) = (noahmp%water_state_SoilMoisture(LoopInd, noahmp_c) - noahmp%water_state_SoilLiqWater(LoopInd, noahmp_c)) * noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c) * 1000.0
    enddo
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 4
      noahmp%water_state_IndexPhaseChange(LoopInd, noahmp_c) = 0
      EnergyRes(LoopInd) = 0.0
      WaterPhaseChg(LoopInd) = 0.0
      MassWatIceInit(LoopInd) = MassWatIceTmp(LoopInd)
      MassWatLiqInit(LoopInd) = MassWatLiqTmp(LoopInd)
      MassWatTotInit(LoopInd) = MassWatIceTmp(LoopInd) + MassWatLiqTmp(LoopInd)
    enddo
    do LoopInd = 1, 4
      if ( noahmp%energy_state_TemperatureSoilSnow(LoopInd, noahmp_c) < ConstFreezePoint ) then
        call SoilWaterSupercoolNiu06(noahmp, noahmp_c, LoopInd, noahmp%water_state_SoilSupercoolWater(LoopInd, noahmp_c),noahmp%energy_state_TemperatureSoilSnow(LoopInd, noahmp_c))
        noahmp%water_state_SoilSupercoolWater(LoopInd, noahmp_c) = noahmp%water_state_SoilSupercoolWater(LoopInd, noahmp_c) * noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c) * 1000.0
      endif
    enddo
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 4
      if ( (MassWatIceTmp(LoopInd) > 0.0) .and. (noahmp%energy_state_TemperatureSoilSnow(LoopInd, noahmp_c) >= ConstFreezePoint) ) then
        noahmp%water_state_IndexPhaseChange(LoopInd, noahmp_c) = 1
      endif
      if ( (MassWatLiqTmp(LoopInd) > noahmp%water_state_SoilSupercoolWater(LoopInd, noahmp_c)) .and. (noahmp%energy_state_TemperatureSoilSnow(LoopInd, noahmp_c) < ConstFreezePoint) ) then
        noahmp%water_state_IndexPhaseChange(LoopInd, noahmp_c) = 2
      endif
      if ( (noahmp%config_domain_NumSnowLayerNeg(noahmp_c) == 0) .and. (noahmp%water_state_SnowWaterEquiv(noahmp_c) > 0.0) .and. (LoopInd == 1) ) then
        if ( noahmp%energy_state_TemperatureSoilSnow(LoopInd, noahmp_c) >= ConstFreezePoint ) then
          noahmp%water_state_IndexPhaseChange(LoopInd, noahmp_c) = 1
        endif
      endif
    enddo
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 4
      if ( noahmp%water_state_IndexPhaseChange(LoopInd, noahmp_c) > 0 ) then
        EnergyRes(LoopInd) = (noahmp%energy_state_TemperatureSoilSnow(LoopInd, noahmp_c)-ConstFreezePoint) / noahmp%energy_state_PhaseChgFacSoilSnow(LoopInd, noahmp_c)
        noahmp%energy_state_TemperatureSoilSnow(LoopInd, noahmp_c) = ConstFreezePoint
      endif
      if ( (noahmp%water_state_IndexPhaseChange(LoopInd, noahmp_c) == 1) .and. (EnergyRes(LoopInd) < 0.0) ) then
        EnergyRes(LoopInd) = 0.0
        noahmp%water_state_IndexPhaseChange(LoopInd, noahmp_c) = 0
      endif
      if ( (noahmp%water_state_IndexPhaseChange(LoopInd, noahmp_c) == 2) .and. (EnergyRes(LoopInd) > 0.0) ) then
        EnergyRes(LoopInd) = 0.0
        noahmp%water_state_IndexPhaseChange(LoopInd, noahmp_c) = 0
      endif
      WaterPhaseChg(LoopInd) = EnergyRes(LoopInd) * noahmp%config_domain_MainTimeStep(noahmp_c) / ConstLatHeatFusion
    enddo
    if ( (noahmp%config_domain_NumSnowLayerNeg(noahmp_c) == 0) .and. (noahmp%water_state_SnowWaterEquiv(noahmp_c) > 0.0) .and. (WaterPhaseChg(1) > 0.0) ) then
      SnowWaterPrev = noahmp%water_state_SnowWaterEquiv(noahmp_c)
      noahmp%water_state_SnowWaterEquiv(noahmp_c) = max(0.0, SnowWaterPrev-WaterPhaseChg(1))
      SnowWaterRatio = noahmp%water_state_SnowWaterEquiv(noahmp_c) / SnowWaterPrev
      noahmp%water_state_SnowDepth(noahmp_c) = max(0.0, SnowWaterRatio*noahmp%water_state_SnowDepth(noahmp_c) )
      noahmp%water_state_SnowDepth(noahmp_c) = min(max(noahmp%water_state_SnowDepth(noahmp_c),noahmp%water_state_SnowWaterEquiv(noahmp_c)/500.0), noahmp%water_state_SnowWaterEquiv(noahmp_c)/50.0)
      EnergyResLeft = EnergyRes(1) - ConstLatHeatFusion * (SnowWaterPrev - noahmp%water_state_SnowWaterEquiv(noahmp_c)) / noahmp%config_domain_MainTimeStep(noahmp_c)
      if ( EnergyResLeft > 0.0 ) then
        WaterPhaseChg(1) = EnergyResLeft * noahmp%config_domain_MainTimeStep(noahmp_c) / ConstLatHeatFusion
        EnergyRes(1) = EnergyResLeft
      else
        WaterPhaseChg(1) = 0.0
        EnergyRes(1) = 0.0
      endif
      noahmp%water_flux_MeltGroundSnow(noahmp_c) = max(0.0, (SnowWaterPrev-noahmp%water_state_SnowWaterEquiv(noahmp_c))) / noahmp%config_domain_MainTimeStep(noahmp_c)
      HeatLhTotPhsChg = ConstLatHeatFusion * noahmp%water_flux_MeltGroundSnow(noahmp_c)
      noahmp%water_state_PondSfcThinSnwMelt(noahmp_c) = SnowWaterPrev - noahmp%water_state_SnowWaterEquiv(noahmp_c)
    endif
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 4
      if ( (noahmp%water_state_IndexPhaseChange(LoopInd, noahmp_c) > 0) .and. (abs(EnergyRes(LoopInd)) > 0.0) ) then
        EnergyResLeft = 0.0
        if ( WaterPhaseChg(LoopInd) > 0.0 ) then
          MassWatIceTmp(LoopInd) = max(0.0, MassWatIceInit(LoopInd)-WaterPhaseChg(LoopInd))
          EnergyResLeft = EnergyRes(LoopInd) - ConstLatHeatFusion * (MassWatIceInit(LoopInd) - MassWatIceTmp(LoopInd)) / noahmp%config_domain_MainTimeStep(noahmp_c)
        elseif ( WaterPhaseChg(LoopInd) < 0.0 ) then
          if ( LoopInd <= 0 ) then
            MassWatIceTmp(LoopInd) = min(MassWatTotInit(LoopInd), MassWatIceInit(LoopInd)-WaterPhaseChg(LoopInd))
          else
            if ( MassWatTotInit(LoopInd) < noahmp%water_state_SoilSupercoolWater(LoopInd, noahmp_c) ) then
              MassWatIceTmp(LoopInd) = 0.0
            else
              MassWatIceTmp(LoopInd) = min(MassWatTotInit(LoopInd)-noahmp%water_state_SoilSupercoolWater(LoopInd, noahmp_c), &
                & MassWatIceInit(LoopInd)-WaterPhaseChg(LoopInd))
              MassWatIceTmp(LoopInd) = max(MassWatIceTmp(LoopInd), 0.0)
            endif
          endif
          EnergyResLeft = EnergyRes(LoopInd) - ConstLatHeatFusion * (MassWatIceInit(LoopInd) - MassWatIceTmp(LoopInd)) / noahmp%config_domain_MainTimeStep(noahmp_c)
        endif
        MassWatLiqTmp(LoopInd) = max(0.0, MassWatTotInit(LoopInd)-MassWatIceTmp(LoopInd))
        if ( abs(EnergyResLeft) > 0.0 ) then
          noahmp%energy_state_TemperatureSoilSnow(LoopInd, noahmp_c) = noahmp%energy_state_TemperatureSoilSnow(LoopInd, noahmp_c) + noahmp%energy_state_PhaseChgFacSoilSnow(LoopInd, noahmp_c) * EnergyResLeft
          if ( LoopInd <= 0 ) then
            if ( (MassWatLiqTmp(LoopInd)*MassWatIceTmp(LoopInd)) > 0.0 ) noahmp%energy_state_TemperatureSoilSnow(LoopInd, noahmp_c) = ConstFreezePoint
            if ( MassWatIceTmp(LoopInd) == 0.0 ) then
              noahmp%energy_state_TemperatureSoilSnow(LoopInd, noahmp_c) = ConstFreezePoint
              EnergyRes(LoopInd+1) = EnergyRes(LoopInd+1) + EnergyResLeft
              WaterPhaseChg(LoopInd+1) = EnergyRes(LoopInd+1) * noahmp%config_domain_MainTimeStep(noahmp_c) / ConstLatHeatFusion
            endif
          endif
        endif
        HeatLhTotPhsChg = HeatLhTotPhsChg + ConstLatHeatFusion * (MassWatIceInit(LoopInd) - MassWatIceTmp(LoopInd)) / noahmp%config_domain_MainTimeStep(noahmp_c)
        if ( LoopInd < 1 ) then
          noahmp%water_flux_MeltGroundSnow(noahmp_c) = noahmp%water_flux_MeltGroundSnow(noahmp_c) + max(0.0, (MassWatIceInit(LoopInd)-MassWatIceTmp(LoopInd))) / noahmp%config_domain_MainTimeStep(noahmp_c)
        endif
      endif
    enddo
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 0
      noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c) = MassWatLiqTmp(LoopInd)
      noahmp%water_state_SnowIce(LoopInd, noahmp_c) = MassWatIceTmp(LoopInd)
    enddo
    do LoopInd = 1, 4
      noahmp%water_state_SoilLiqWater(LoopInd, noahmp_c) = MassWatLiqTmp(LoopInd) / (1000.0 * noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c))
      noahmp%water_state_SoilMoisture(LoopInd, noahmp_c) = (MassWatLiqTmp(LoopInd)+MassWatIceTmp(LoopInd)) / (1000.0*noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c))
    enddo
  end subroutine SoilSnowWaterPhaseChange
end module lean_soilsnowwaterphasechangemod

! Source: physics_noahmp/src/EnergyMainMod.F90
module lean_energymainmod
 use lean_phys_fault, only: physics_fault
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_snowcovergroundniu07mod, only : SnowCoverGroundNiu07
  use lean_groundroughnesspropertymod, only : GroundRoughnessProperty
  use lean_groundthermalpropertymod, only : GroundThermalProperty
  use lean_surfacealbedomod, only : SurfaceAlbedo
  use lean_surfaceradiationmod, only : SurfaceRadiation
  use lean_surfaceemissivitymod, only : SurfaceEmissivity
  use lean_soilwatertranspirationmod, only : SoilWaterTranspiration
  use lean_resistancegroundevaporationmod, only : ResistanceGroundEvaporation
  use lean_psychrometricvariablemod, only : PsychrometricVariable
  use lean_surfaceenergyfluxvegetatedmod, only : SurfaceEnergyFluxVegetated
  use lean_surfaceenergyfluxbaregroundmod, only : SurfaceEnergyFluxBareGround
  use lean_soilsnowtemperaturemainmod, only : SoilSnowTemperatureMain
  use lean_soilsnowwaterphasechangemod, only : SoilSnowWaterPhaseChange
  implicit none
  contains
  subroutine EnergyMain(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    logical :: FlagVegSfc
    noahmp%energy_state_WindStressEwVeg(noahmp_c) = 0.0
    noahmp%energy_state_WindStressNsVeg(noahmp_c) = 0.0
    noahmp%energy_flux_RadLwNetCanopy(noahmp_c) = 0.0
    noahmp%energy_flux_HeatSensibleCanopy(noahmp_c) = 0.0
    noahmp%energy_flux_RadLwNetVegGrd(noahmp_c) = 0.0
    noahmp%energy_flux_HeatSensibleVegGrd(noahmp_c) = 0.0
    noahmp%energy_flux_HeatLatentVegGrd(noahmp_c) = 0.0
    noahmp%energy_flux_HeatLatentCanEvap(noahmp_c) = 0.0
    noahmp%energy_flux_HeatLatentCanTransp(noahmp_c) = 0.0
    noahmp%energy_flux_HeatGroundVegGrd(noahmp_c) = 0.0
    noahmp%biochem_flux_PhotosynLeafSunlit(noahmp_c) = 0.0
    noahmp%biochem_flux_PhotosynLeafShade(noahmp_c) = 0.0
    noahmp%energy_state_TemperatureAir2mVeg(noahmp_c) = 0.0
    noahmp%energy_state_SpecHumidity2mVeg(noahmp_c) = 0.0
    noahmp%energy_state_ExchCoeffShAbvCan(noahmp_c) = 0.0
    noahmp%energy_state_ExchCoeffShLeaf(noahmp_c) = 0.0
    noahmp%energy_state_ExchCoeffShUndCan(noahmp_c) = 0.0
    noahmp%energy_state_ExchCoeffSh2mVeg(noahmp_c) = 0.0
    noahmp%energy_flux_HeatPrecipAdvSfc(noahmp_c) = 0.0
    noahmp%energy_flux_HeatCanStorageChg(noahmp_c) = 0.0
    noahmp%energy_state_VegAreaIndEff(noahmp_c) = noahmp%energy_state_LeafAreaIndEff(noahmp_c) + noahmp%energy_state_StemAreaIndEff(noahmp_c)
    FlagVegSfc = .false.
    if ( noahmp%energy_state_VegAreaIndEff(noahmp_c) > 0.0 ) FlagVegSfc = .true.
    call SnowCoverGroundNiu07(noahmp, noahmp_c)
    call GroundRoughnessProperty(noahmp, noahmp_c, FlagVegSfc)
    call GroundThermalProperty(noahmp, noahmp_c)
    call SurfaceAlbedo(noahmp, noahmp_c)
    call SurfaceRadiation(noahmp, noahmp_c)
    call SurfaceEmissivity(noahmp, noahmp_c)
    call SoilWaterTranspiration(noahmp, noahmp_c)
    call ResistanceGroundEvaporation(noahmp, noahmp_c)
    call PsychrometricVariable(noahmp, noahmp_c)
    if ( (FlagVegSfc .eqv. .true.) .and. (noahmp%energy_state_VegFrac(noahmp_c) > 0) ) then
      noahmp%energy_state_TemperatureGrdVeg(noahmp_c) = noahmp%energy_state_TemperatureGrd(noahmp_c)
      noahmp%energy_state_ExchCoeffMomAbvCan(noahmp_c) = noahmp%energy_state_ExchCoeffMomSfc(noahmp_c)
      noahmp%energy_state_ExchCoeffShAbvCan(noahmp_c) = noahmp%energy_state_ExchCoeffShSfc(noahmp_c)
      call SurfaceEnergyFluxVegetated(noahmp, noahmp_c)
    endif
    noahmp%energy_state_TemperatureGrdBare(noahmp_c) = noahmp%energy_state_TemperatureGrd(noahmp_c)
    noahmp%energy_state_ExchCoeffMomBare(noahmp_c) = noahmp%energy_state_ExchCoeffMomSfc(noahmp_c)
    noahmp%energy_state_ExchCoeffShBare(noahmp_c) = noahmp%energy_state_ExchCoeffShSfc(noahmp_c)
    call SurfaceEnergyFluxBareGround(noahmp, noahmp_c)
    if ( (FlagVegSfc .eqv. .true.) .and. (noahmp%energy_state_VegFrac(noahmp_c) > 0) ) then
      noahmp%energy_state_WindStressEwSfc(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%energy_state_WindStressEwVeg(noahmp_c) + (1.0 - noahmp%energy_state_VegFrac(noahmp_c)) * noahmp%energy_state_WindStressEwBare(noahmp_c)
      noahmp%energy_state_WindStressNsSfc(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%energy_state_WindStressNsVeg(noahmp_c) + (1.0 - noahmp%energy_state_VegFrac(noahmp_c)) * noahmp%energy_state_WindStressNsBare(noahmp_c)
      noahmp%energy_flux_RadLwNetSfc(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%energy_flux_RadLwNetVegGrd(noahmp_c) + (1.0 - noahmp%energy_state_VegFrac(noahmp_c)) * noahmp%energy_flux_RadLwNetBareGrd(noahmp_c) + noahmp%energy_flux_RadLwNetCanopy(noahmp_c)
      noahmp%energy_flux_HeatSensibleSfc(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%energy_flux_HeatSensibleVegGrd(noahmp_c) + (1.0 - noahmp%energy_state_VegFrac(noahmp_c)) * noahmp%energy_flux_HeatSensibleBareGrd(noahmp_c) + noahmp%energy_flux_HeatSensibleCanopy(noahmp_c)
      noahmp%energy_flux_HeatLatentGrd(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%energy_flux_HeatLatentVegGrd(noahmp_c) + (1.0 - noahmp%energy_state_VegFrac(noahmp_c)) * noahmp%energy_flux_HeatLatentBareGrd(noahmp_c)
      noahmp%energy_flux_HeatGroundTot(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%energy_flux_HeatGroundVegGrd(noahmp_c) + (1.0 - noahmp%energy_state_VegFrac(noahmp_c)) * noahmp%energy_flux_HeatGroundBareGrd(noahmp_c)
      noahmp%energy_flux_HeatLatentCanopy(noahmp_c) = noahmp%energy_flux_HeatLatentCanEvap(noahmp_c)
      noahmp%energy_flux_HeatLatentTransp(noahmp_c) = noahmp%energy_flux_HeatLatentCanTransp(noahmp_c)
      noahmp%energy_flux_HeatPrecipAdvSfc(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%energy_flux_HeatPrecipAdvVegGrd(noahmp_c) + (1.0 - noahmp%energy_state_VegFrac(noahmp_c)) * noahmp%energy_flux_HeatPrecipAdvBareGrd(noahmp_c) + noahmp%energy_flux_HeatPrecipAdvCanopy(noahmp_c)
      noahmp%energy_state_TemperatureGrd(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%energy_state_TemperatureGrdVeg(noahmp_c) + (1.0 - noahmp%energy_state_VegFrac(noahmp_c)) * noahmp%energy_state_TemperatureGrdBare(noahmp_c)
      noahmp%energy_state_TemperatureAir2m(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%energy_state_TemperatureAir2mVeg(noahmp_c) + (1.0 - noahmp%energy_state_VegFrac(noahmp_c)) * noahmp%energy_state_TemperatureAir2mBare(noahmp_c)
      noahmp%energy_state_TemperatureSfc(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%energy_state_TemperatureCanopy(noahmp_c) + (1.0 - noahmp%energy_state_VegFrac(noahmp_c)) * noahmp%energy_state_TemperatureGrdBare(noahmp_c)
      noahmp%energy_state_ExchCoeffMomSfc(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%energy_state_ExchCoeffMomAbvCan(noahmp_c) + (1.0 - noahmp%energy_state_VegFrac(noahmp_c)) * noahmp%energy_state_ExchCoeffMomBare(noahmp_c)
      noahmp%energy_state_ExchCoeffShSfc(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%energy_state_ExchCoeffShAbvCan(noahmp_c) + (1.0 - noahmp%energy_state_VegFrac(noahmp_c)) * noahmp%energy_state_ExchCoeffShBare(noahmp_c)
      noahmp%energy_state_SpecHumidity2m(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%energy_state_SpecHumidity2mVeg(noahmp_c) + (1.0 - noahmp%energy_state_VegFrac(noahmp_c)) * noahmp%energy_state_SpecHumidity2mBare(noahmp_c)
      noahmp%energy_state_SpecHumiditySfcMean(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * (noahmp%energy_state_PressureVaporCanAir(noahmp_c) * 0.622 / (noahmp%forcing_PressureAirRefHeight(noahmp_c) - 0.378*noahmp%energy_state_PressureVaporCanAir(noahmp_c))) + (1.0 - noahmp%energy_state_VegFrac(noahmp_c)) * noahmp%energy_state_SpecHumiditySfc(noahmp_c)
      noahmp%energy_state_RoughLenMomSfcToAtm(noahmp_c) = noahmp%energy_state_RoughLenMomSfc(noahmp_c)
    else
      noahmp%energy_state_WindStressEwSfc(noahmp_c) = noahmp%energy_state_WindStressEwBare(noahmp_c)
      noahmp%energy_state_WindStressNsSfc(noahmp_c) = noahmp%energy_state_WindStressNsBare(noahmp_c)
      noahmp%energy_flux_RadLwNetSfc(noahmp_c) = noahmp%energy_flux_RadLwNetBareGrd(noahmp_c)
      noahmp%energy_flux_HeatSensibleSfc(noahmp_c) = noahmp%energy_flux_HeatSensibleBareGrd(noahmp_c)
      noahmp%energy_flux_HeatLatentGrd(noahmp_c) = noahmp%energy_flux_HeatLatentBareGrd(noahmp_c)
      noahmp%energy_flux_HeatGroundTot(noahmp_c) = noahmp%energy_flux_HeatGroundBareGrd(noahmp_c)
      noahmp%energy_state_TemperatureGrd(noahmp_c) = noahmp%energy_state_TemperatureGrdBare(noahmp_c)
      noahmp%energy_state_TemperatureAir2m(noahmp_c) = noahmp%energy_state_TemperatureAir2mBare(noahmp_c)
      noahmp%energy_flux_HeatLatentCanopy(noahmp_c) = 0.0
      noahmp%energy_flux_HeatLatentTransp(noahmp_c) = 0.0
      noahmp%energy_flux_HeatPrecipAdvSfc(noahmp_c) = noahmp%energy_flux_HeatPrecipAdvBareGrd(noahmp_c)
      noahmp%energy_state_TemperatureSfc(noahmp_c) = noahmp%energy_state_TemperatureGrd(noahmp_c)
      noahmp%energy_state_ExchCoeffMomSfc(noahmp_c) = noahmp%energy_state_ExchCoeffMomBare(noahmp_c)
      noahmp%energy_state_ExchCoeffShSfc(noahmp_c) = noahmp%energy_state_ExchCoeffShBare(noahmp_c)
      noahmp%energy_state_SpecHumiditySfcMean(noahmp_c) = noahmp%energy_state_SpecHumiditySfc(noahmp_c)
      noahmp%energy_state_SpecHumidity2m(noahmp_c) = noahmp%energy_state_SpecHumidity2mBare(noahmp_c)
      noahmp%energy_state_ResistanceStomataSunlit(noahmp_c) = 0.0
      noahmp%energy_state_ResistanceStomataShade(noahmp_c) = 0.0
      noahmp%energy_state_TemperatureGrdVeg(noahmp_c) = noahmp%energy_state_TemperatureGrdBare(noahmp_c)
      noahmp%energy_state_ExchCoeffShAbvCan(noahmp_c) = noahmp%energy_state_ExchCoeffShBare(noahmp_c)
      noahmp%energy_state_RoughLenMomSfcToAtm(noahmp_c) = noahmp%energy_state_RoughLenMomGrd(noahmp_c)
    endif
    noahmp%energy_flux_RadLwEmitSfc(noahmp_c) = noahmp%forcing_RadLwDownRefHeight(noahmp_c) + noahmp%energy_flux_RadLwNetSfc(noahmp_c)
    if ( noahmp%energy_flux_RadLwEmitSfc(noahmp_c) <= 0.0 ) then
      call physics_fault(7)
    endif
    noahmp%energy_state_TemperatureRadSfc(noahmp_c) = ((noahmp%energy_flux_RadLwEmitSfc(noahmp_c) - (1.0-noahmp%energy_state_EmissivitySfc(noahmp_c))*noahmp%forcing_RadLwDownRefHeight(noahmp_c)) / (noahmp%energy_state_EmissivitySfc(noahmp_c)*ConstStefanBoltzmann))**0.25
    noahmp%energy_flux_RadPhotoActAbsCan(noahmp_c) = noahmp%energy_flux_RadPhotoActAbsSunlit(noahmp_c) * noahmp%energy_state_LeafAreaIndSunlit(noahmp_c) + noahmp%energy_flux_RadPhotoActAbsShade(noahmp_c) * noahmp%energy_state_LeafAreaIndShade(noahmp_c)
    noahmp%biochem_flux_PhotosynTotal(noahmp_c) = noahmp%biochem_flux_PhotosynLeafSunlit(noahmp_c) * noahmp%energy_state_LeafAreaIndSunlit(noahmp_c) + noahmp%biochem_flux_PhotosynLeafShade(noahmp_c) * noahmp%energy_state_LeafAreaIndShade(noahmp_c)
    noahmp%energy_flux_HeatFromSoilBot(noahmp_c) = 0.0
    noahmp%energy_flux_HeatGroundTotAcc(noahmp_c) = noahmp%energy_flux_HeatGroundTotAcc(noahmp_c) + noahmp%energy_flux_HeatGroundTot(noahmp_c)
    if ( noahmp%config_domain_FlagSoilProcess(noahmp_c) .eqv. .true. ) then
      noahmp%energy_flux_HeatGroundTotMean(noahmp_c) = noahmp%energy_flux_HeatGroundTotAcc(noahmp_c) / noahmp%config_domain_NumSoilTimeStep(noahmp_c)
      call SoilSnowTemperatureMain(noahmp, noahmp_c)
    endif
    call SoilSnowWaterPhaseChange(noahmp, noahmp_c)
    if ( (noahmp%config_domain_FlagCropland(noahmp_c) .eqv. .true.) .and. (noahmp%water_state_IrrigationFracGrid(noahmp_c) >= noahmp%water_param_IrriFracThreshold(noahmp_c)) ) noahmp%energy_flux_HeatSensibleSfc(noahmp_c) = noahmp%energy_flux_HeatSensibleSfc(noahmp_c) - noahmp%energy_flux_HeatLatentIrriEvap(noahmp_c)
    if ( noahmp%forcing_RadSwDownRefHeight(noahmp_c) > 0.0 ) then
      noahmp%energy_state_AlbedoSfc(noahmp_c) = noahmp%energy_flux_RadSwReflSfc(noahmp_c) / noahmp%forcing_RadSwDownRefHeight(noahmp_c)
    else
      noahmp%energy_state_AlbedoSfc(noahmp_c) = undefined_real
    endif
  end subroutine EnergyMain
end module lean_energymainmod

! Source: physics_noahmp/src/CanopyHydrologyMod.F90
module lean_canopyhydrologymod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine CanopyHydrology(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    noahmp%water_flux_EvapCanopyNet(noahmp_c) = 0.0
    noahmp%water_flux_Transpiration(noahmp_c) = 0.0
    noahmp%water_flux_EvapCanopyLiq(noahmp_c) = 0.0
    noahmp%water_flux_DewCanopyLiq(noahmp_c) = 0.0
    noahmp%water_flux_FrostCanopyIce(noahmp_c) = 0.0
    noahmp%water_flux_SublimCanopyIce(noahmp_c) = 0.0
    noahmp%water_flux_MeltCanopyIce(noahmp_c) = 0.0
    noahmp%water_flux_FreezeCanopyLiq(noahmp_c) = 0.0
    noahmp%water_state_CanopyLiqWaterMax(noahmp_c) = 0.0
    noahmp%water_state_CanopyIceMax(noahmp_c) = 0.0
    noahmp%water_state_CanopyWetFrac(noahmp_c) = 0.0
    noahmp%water_state_CanopyTotalWater(noahmp_c) = 0.0
    noahmp%water_state_CanopyLiqWaterMax(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * noahmp%water_param_CanopyLiqHoldCap(noahmp_c) * (noahmp%energy_state_LeafAreaIndEff(noahmp_c) + noahmp%energy_state_StemAreaIndEff(noahmp_c))
    if ( noahmp%energy_state_FlagFrozenCanopy(noahmp_c) .eqv. .false. ) then
      noahmp%water_flux_Transpiration(noahmp_c) = max( noahmp%energy_flux_HeatLatentTransp(noahmp_c)/ConstLatHeatEvap, 0.0 )
      noahmp%water_flux_EvapCanopyLiq(noahmp_c) = max( noahmp%energy_flux_HeatLatentCanopy(noahmp_c)/ConstLatHeatEvap, 0.0 )
      noahmp%water_flux_DewCanopyLiq(noahmp_c) = abs( min( noahmp%energy_flux_HeatLatentCanopy(noahmp_c)/ConstLatHeatEvap, 0.0 ) )
      noahmp%water_flux_SublimCanopyIce(noahmp_c) = 0.0
      noahmp%water_flux_FrostCanopyIce(noahmp_c) = 0.0
    else
      noahmp%water_flux_Transpiration(noahmp_c) = max( noahmp%energy_flux_HeatLatentTransp(noahmp_c)/ConstLatHeatSublim, 0.0 )
      noahmp%water_flux_EvapCanopyLiq(noahmp_c) = 0.0
      noahmp%water_flux_DewCanopyLiq(noahmp_c) = 0.0
      noahmp%water_flux_SublimCanopyIce(noahmp_c) = max( noahmp%energy_flux_HeatLatentCanopy(noahmp_c)/ConstLatHeatSublim, 0.0 )
      noahmp%water_flux_FrostCanopyIce(noahmp_c) = abs( min( noahmp%energy_flux_HeatLatentCanopy(noahmp_c)/ConstLatHeatSublim, 0.0 ) )
    endif
    noahmp%water_flux_EvapCanopyLiq(noahmp_c) = min( noahmp%water_state_CanopyLiqWater(noahmp_c)/noahmp%config_domain_MainTimeStep(noahmp_c), noahmp%water_flux_EvapCanopyLiq(noahmp_c) )
    noahmp%water_state_CanopyLiqWater(noahmp_c) = max( 0.0, noahmp%water_state_CanopyLiqWater(noahmp_c)+(noahmp%water_flux_DewCanopyLiq(noahmp_c)-noahmp%water_flux_EvapCanopyLiq(noahmp_c))*noahmp%config_domain_MainTimeStep(noahmp_c) )
    if ( noahmp%water_state_CanopyLiqWater(noahmp_c) <= 1.0e-06 ) noahmp%water_state_CanopyLiqWater(noahmp_c) = 0.0
    noahmp%water_state_CanopyIceMax(noahmp_c) = noahmp%energy_state_VegFrac(noahmp_c) * 6.6 * (0.27 + 46.0/noahmp%water_state_SnowfallDensity(noahmp_c)) * (noahmp%energy_state_LeafAreaIndEff(noahmp_c) + noahmp%energy_state_StemAreaIndEff(noahmp_c))
    noahmp%water_flux_SublimCanopyIce(noahmp_c) = min( noahmp%water_state_CanopyIce(noahmp_c)/noahmp%config_domain_MainTimeStep(noahmp_c), noahmp%water_flux_SublimCanopyIce(noahmp_c) )
    noahmp%water_state_CanopyIce(noahmp_c) = max( 0.0, noahmp%water_state_CanopyIce(noahmp_c)+(noahmp%water_flux_FrostCanopyIce(noahmp_c)-noahmp%water_flux_SublimCanopyIce(noahmp_c))*noahmp%config_domain_MainTimeStep(noahmp_c) )
    if ( noahmp%water_state_CanopyIce(noahmp_c) <= 1.0e-6 ) noahmp%water_state_CanopyIce(noahmp_c) = 0.0
    if ( (noahmp%water_state_CanopyIce(noahmp_c) > 0.0) .and. (noahmp%water_state_CanopyIce(noahmp_c) >= noahmp%water_state_CanopyLiqWater(noahmp_c)) ) then
      noahmp%water_state_CanopyWetFrac(noahmp_c) = max(0.0,noahmp%water_state_CanopyIce(noahmp_c)) / max(noahmp%water_state_CanopyIceMax(noahmp_c),1.0e-06)
    else
      noahmp%water_state_CanopyWetFrac(noahmp_c) = max(0.0,noahmp%water_state_CanopyLiqWater(noahmp_c)) / max(noahmp%water_state_CanopyLiqWaterMax(noahmp_c),1.0e-06)
    endif
    noahmp%water_state_CanopyWetFrac(noahmp_c) = min(noahmp%water_state_CanopyWetFrac(noahmp_c), 1.0) ** 0.667
    noahmp%water_state_CanopyTotalWater(noahmp_c) = noahmp%water_state_CanopyLiqWater(noahmp_c) + noahmp%water_state_CanopyIce(noahmp_c)
    if ( (noahmp%water_state_CanopyIce(noahmp_c) > 1.0e-6) .and. (noahmp%energy_state_TemperatureCanopy(noahmp_c) > ConstFreezePoint) ) then
      noahmp%water_flux_MeltCanopyIce(noahmp_c) = min( noahmp%water_state_CanopyIce(noahmp_c)/noahmp%config_domain_MainTimeStep(noahmp_c), &
        & (noahmp%energy_state_TemperatureCanopy(noahmp_c)-ConstFreezePoint) * ConstHeatCapacIce * noahmp%water_state_CanopyIce(noahmp_c) / ConstDensityIce / (noahmp%config_domain_MainTimeStep(noahmp_c)*ConstLatHeatFusion) )
      noahmp%water_state_CanopyIce(noahmp_c) = max( 0.0, noahmp%water_state_CanopyIce(noahmp_c) - noahmp%water_flux_MeltCanopyIce(noahmp_c)*noahmp%config_domain_MainTimeStep(noahmp_c) )
      noahmp%water_state_CanopyLiqWater(noahmp_c) = max( 0.0, noahmp%water_state_CanopyTotalWater(noahmp_c) - noahmp%water_state_CanopyIce(noahmp_c) )
      noahmp%energy_state_TemperatureCanopy(noahmp_c) = noahmp%water_state_CanopyWetFrac(noahmp_c)*ConstFreezePoint + (1.0 - noahmp%water_state_CanopyWetFrac(noahmp_c))*noahmp%energy_state_TemperatureCanopy(noahmp_c)
    endif
    if ( (noahmp%water_state_CanopyLiqWater(noahmp_c) > 1.0e-6) .and. (noahmp%energy_state_TemperatureCanopy(noahmp_c) < ConstFreezePoint) ) then
      noahmp%water_flux_FreezeCanopyLiq(noahmp_c) = min( noahmp%water_state_CanopyLiqWater(noahmp_c)/noahmp%config_domain_MainTimeStep(noahmp_c), &
        & (ConstFreezePoint-noahmp%energy_state_TemperatureCanopy(noahmp_c)) * ConstHeatCapacWater * noahmp%water_state_CanopyLiqWater(noahmp_c) / ConstDensityWater / (noahmp%config_domain_MainTimeStep(noahmp_c)*ConstLatHeatFusion) )
      noahmp%water_state_CanopyLiqWater(noahmp_c) = max( 0.0, noahmp%water_state_CanopyLiqWater(noahmp_c) - noahmp%water_flux_FreezeCanopyLiq(noahmp_c)*noahmp%config_domain_MainTimeStep(noahmp_c) )
      noahmp%water_state_CanopyIce(noahmp_c) = max( 0.0, noahmp%water_state_CanopyTotalWater(noahmp_c) - noahmp%water_state_CanopyLiqWater(noahmp_c) )
      noahmp%energy_state_TemperatureCanopy(noahmp_c) = noahmp%water_state_CanopyWetFrac(noahmp_c)*ConstFreezePoint + (1.0 - noahmp%water_state_CanopyWetFrac(noahmp_c))*noahmp%energy_state_TemperatureCanopy(noahmp_c)
    endif
    noahmp%water_state_CanopyTotalWater(noahmp_c) = noahmp%water_state_CanopyLiqWater(noahmp_c) + noahmp%water_state_CanopyIce(noahmp_c)
    noahmp%water_flux_EvapCanopyNet(noahmp_c) = noahmp%water_flux_EvapCanopyLiq(noahmp_c) + noahmp%water_flux_SublimCanopyIce(noahmp_c) - noahmp%water_flux_DewCanopyLiq(noahmp_c) - noahmp%water_flux_FrostCanopyIce(noahmp_c)
  end subroutine CanopyHydrology
end module lean_canopyhydrologymod

! Source: physics_noahmp/src/SnowfallBelowCanopyMod.F90
module lean_snowfallbelowcanopymod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine SnowfallAfterCanopyIntercept(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: IndNewSnowLayer
    IndNewSnowLayer = 0
    if ( (noahmp%config_domain_NumSnowLayerNeg(noahmp_c) == 0) .and. (noahmp%water_flux_SnowfallGround(noahmp_c) > 0.0) ) then
      noahmp%water_state_SnowDepth(noahmp_c) = noahmp%water_state_SnowDepth(noahmp_c) + noahmp%water_flux_SnowDepthIncr(noahmp_c) * noahmp%config_domain_MainTimeStep(noahmp_c)
      noahmp%water_state_SnowWaterEquiv(noahmp_c) = noahmp%water_state_SnowWaterEquiv(noahmp_c) + noahmp%water_flux_SnowfallGround(noahmp_c) * noahmp%config_domain_MainTimeStep(noahmp_c)
    endif
    if ( (noahmp%config_domain_NumSnowLayerNeg(noahmp_c) == 0) .and. (noahmp%water_state_SnowDepth(noahmp_c) >= 0.025) ) then
      noahmp%config_domain_NumSnowLayerNeg(noahmp_c) = -1
      IndNewSnowLayer = 1
      noahmp%config_domain_ThicknessSnowSoilLayer(0, noahmp_c) = noahmp%water_state_SnowDepth(noahmp_c)
      noahmp%water_state_SnowDepth(noahmp_c) = 0.0
      noahmp%energy_state_TemperatureSoilSnow(0, noahmp_c) = min(273.16, noahmp%forcing_TemperatureAirRefHeight(noahmp_c))
      noahmp%water_state_SnowIce(0, noahmp_c) = noahmp%water_state_SnowWaterEquiv(noahmp_c)
      noahmp%water_state_SnowLiqWater(0, noahmp_c) = 0.0
    endif
    if ( (noahmp%config_domain_NumSnowLayerNeg(noahmp_c) < 0) .and. (IndNewSnowLayer == 0) .and. (noahmp%water_flux_SnowfallGround(noahmp_c) > 0.0) ) then
      noahmp%water_state_SnowIce(noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, noahmp_c) = noahmp%water_state_SnowIce(noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, noahmp_c) + noahmp%water_flux_SnowfallGround(noahmp_c) * noahmp%config_domain_MainTimeStep(noahmp_c)
      noahmp%config_domain_ThicknessSnowSoilLayer(noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, noahmp_c) = noahmp%config_domain_ThicknessSnowSoilLayer(noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, noahmp_c) + noahmp%water_flux_SnowDepthIncr(noahmp_c) * noahmp%config_domain_MainTimeStep(noahmp_c)
    endif
  end subroutine SnowfallAfterCanopyIntercept
end module lean_snowfallbelowcanopymod

! Source: physics_noahmp/src/SnowpackCompactionMod.F90
module lean_snowpackcompactionmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine SnowpackCompaction(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: LoopInd
    real(kind=kind_noahmp) :: SnowBurden
    real(kind=kind_noahmp) :: SnowCompactAgeExpFac
    real(kind=kind_noahmp) :: TempDiff
    real(kind=kind_noahmp) :: SnowVoid
    real(kind=kind_noahmp) :: SnowWatTotTmp
    real(kind=kind_noahmp) :: SnowIceDens
    noahmp%water_flux_CompactionSnowAging(:, noahmp_c) = 0.0
    noahmp%water_flux_CompactionSnowBurden(:, noahmp_c) = 0.0
    noahmp%water_flux_CompactionSnowMelt(:, noahmp_c) = 0.0
    noahmp%water_flux_CompactionSnowTot(:, noahmp_c) = 0.0
    noahmp%water_state_SnowIceFrac(:, noahmp_c) = 0.0
    SnowBurden = 0.0
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 0
      SnowWatTotTmp = noahmp%water_state_SnowIce(LoopInd, noahmp_c) + noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c)
      noahmp%water_state_SnowIceFrac(LoopInd, noahmp_c) = noahmp%water_state_SnowIce(LoopInd, noahmp_c) / SnowWatTotTmp
      SnowVoid = 1.0 - (noahmp%water_state_SnowIce(LoopInd, noahmp_c)/ConstDensityIce + noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c)/ConstDensityWater) / noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c)
      if ( (SnowVoid > 0.001) .and. (noahmp%water_state_SnowIce(LoopInd, noahmp_c) > 0.1) ) then
        SnowIceDens = noahmp%water_state_SnowIce(LoopInd, noahmp_c) / noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c)
        TempDiff = max(0.0, ConstFreezePoint-noahmp%energy_state_TemperatureSoilSnow(LoopInd, noahmp_c))
        SnowCompactAgeExpFac = exp(-noahmp%water_param_SnowCompactAgingFac2(noahmp_c) * TempDiff)
        noahmp%water_flux_CompactionSnowAging(LoopInd, noahmp_c) = -noahmp%water_param_SnowCompactAgingFac1(noahmp_c) * SnowCompactAgeExpFac
        if ( SnowIceDens > noahmp%water_param_SnowCompactAgingMax(noahmp_c) ) noahmp%water_flux_CompactionSnowAging(LoopInd, noahmp_c) = noahmp%water_flux_CompactionSnowAging(LoopInd, noahmp_c) * exp(-46.0e-3*(SnowIceDens-noahmp%water_param_SnowCompactAgingMax(noahmp_c)))
        if ( noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c) > (0.01*noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c)) ) noahmp%water_flux_CompactionSnowAging(LoopInd, noahmp_c) = noahmp%water_flux_CompactionSnowAging(LoopInd, noahmp_c) * noahmp%water_param_SnowCompactAgingFac3(noahmp_c)
        noahmp%water_flux_CompactionSnowBurden(LoopInd, noahmp_c) = -(SnowBurden + 0.5*SnowWatTotTmp) * exp(-0.08*TempDiff-noahmp%water_param_SnowCompactBurdenFac(noahmp_c)*SnowIceDens) / noahmp%water_param_SnowViscosityCoeff(noahmp_c)
        if ( noahmp%water_state_IndexPhaseChange(LoopInd, noahmp_c) == 1 ) then
          noahmp%water_flux_CompactionSnowMelt(LoopInd, noahmp_c) = max(0.0, (noahmp%water_state_SnowIceFracPrev(LoopInd, noahmp_c)-noahmp%water_state_SnowIceFrac(LoopInd, noahmp_c)) / max(1.0e-6, &
            & noahmp%water_state_SnowIceFracPrev(LoopInd, noahmp_c)))
          noahmp%water_flux_CompactionSnowMelt(LoopInd, noahmp_c) = -noahmp%water_flux_CompactionSnowMelt(LoopInd, noahmp_c) / noahmp%config_domain_MainTimeStep(noahmp_c)
        else
          noahmp%water_flux_CompactionSnowMelt(LoopInd, noahmp_c) = 0.0
        endif
        noahmp%water_flux_CompactionSnowTot(LoopInd, noahmp_c) = (noahmp%water_flux_CompactionSnowAging(LoopInd, noahmp_c) + noahmp%water_flux_CompactionSnowBurden(LoopInd, noahmp_c) + noahmp%water_flux_CompactionSnowMelt(LoopInd, noahmp_c) ) * noahmp%config_domain_MainTimeStep(noahmp_c)
        noahmp%water_flux_CompactionSnowTot(LoopInd, noahmp_c) = max(-0.5, noahmp%water_flux_CompactionSnowTot(LoopInd, noahmp_c))
        noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c) = noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c) * (1.0 + noahmp%water_flux_CompactionSnowTot(LoopInd, noahmp_c))
        noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c) = max(noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c), &
          & noahmp%water_state_SnowIce(LoopInd, noahmp_c)/ConstDensityIce + noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c)/ConstDensityWater)
        noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c) = min( max( noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c), &
          & (noahmp%water_state_SnowIce(LoopInd, noahmp_c)+noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c))/500.0 ), (noahmp%water_state_SnowIce(LoopInd, noahmp_c)+noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c))/50.0 )
      endif
      SnowBurden = SnowBurden + SnowWatTotTmp
    enddo
  end subroutine SnowpackCompaction
end module lean_snowpackcompactionmod

! Source: physics_noahmp/src/SnowLayerWaterComboMod.F90
module lean_snowlayerwatercombomod
  use Machine
  use lean_constantdefinemod
  implicit none
  contains
  subroutine SnowLayerWaterCombo(ThickLayer1, LiqLayer1, IceLayer1, TempLayer1, ThickLayer2, LiqLayer2, &
    & IceLayer2, TempLayer2)
 !$acc routine seq
    implicit none
    real(kind=kind_noahmp), intent(in) :: ThickLayer2
    real(kind=kind_noahmp), intent(in) :: LiqLayer2
    real(kind=kind_noahmp), intent(in) :: IceLayer2
    real(kind=kind_noahmp), intent(in) :: TempLayer2
    real(kind=kind_noahmp), intent(inout) :: ThickLayer1
    real(kind=kind_noahmp), intent(inout) :: LiqLayer1
    real(kind=kind_noahmp), intent(inout) :: IceLayer1
    real(kind=kind_noahmp), intent(inout) :: TempLayer1
    real(kind=kind_noahmp) :: ThickLayerComb
    real(kind=kind_noahmp) :: LiqLayerComb
    real(kind=kind_noahmp) :: IceLayerComb
    real(kind=kind_noahmp) :: TempLayerComb
    real(kind=kind_noahmp) :: EnthLayer1
    real(kind=kind_noahmp) :: EnthLayer2
    real(kind=kind_noahmp) :: EnthLayerComb
    ThickLayerComb = ThickLayer1 + ThickLayer2
    IceLayerComb = IceLayer1 + IceLayer2
    LiqLayerComb = LiqLayer1 + LiqLayer2
    EnthLayer1 = (ConstHeatCapacIce*IceLayer1 + ConstHeatCapacWater*LiqLayer1) * (TempLayer1-ConstFreezePoint) + ConstLatHeatFusion*LiqLayer1
    EnthLayer2 = (ConstHeatCapacIce*IceLayer2 + ConstHeatCapacWater*LiqLayer2) * (TempLayer2-ConstFreezePoint) + ConstLatHeatFusion*LiqLayer2
    EnthLayerComb = EnthLayer1 + EnthLayer2
    if ( EnthLayerComb < 0.0 ) then
      TempLayerComb = ConstFreezePoint + EnthLayerComb / (ConstHeatCapacIce*IceLayerComb + ConstHeatCapacWater*LiqLayerComb)
    else if ( EnthLayerComb <= (ConstLatHeatFusion*LiqLayerComb) ) then
      TempLayerComb = ConstFreezePoint
    else
      TempLayerComb = ConstFreezePoint + (EnthLayerComb-ConstLatHeatFusion*LiqLayerComb) / (ConstHeatCapacIce*IceLayerComb + ConstHeatCapacWater*LiqLayerComb)
    endif
    ThickLayer1 = ThickLayerComb
    IceLayer1 = IceLayerComb
    LiqLayer1 = LiqLayerComb
    TempLayer1 = TempLayerComb
  end subroutine SnowLayerWaterCombo
end module lean_snowlayerwatercombomod

! Source: physics_noahmp/src/SnowLayerCombineMod.F90
module lean_snowlayercombinemod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_snowlayerwatercombomod, only: SnowLayerWaterCombo
  implicit none
  contains
  subroutine SnowLayerCombine(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: I,J,K,L
    integer :: NumSnowLayerOld
    integer :: IndLayer
    integer :: IndNeighbor
    real(kind=kind_noahmp) :: SnowIceTmp
    real(kind=kind_noahmp) :: SnowLiqTmp
    real(kind=kind_noahmp) :: SnowThickMin(3)
    data SnowThickMin /0.025, 0.025, 0.1/
    NumSnowLayerOld = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)
    do J = NumSnowLayerOld+1,0
      if ( noahmp%water_state_SnowIce(J, noahmp_c) <= 0.1 ) then
        if ( J /= 0 ) then
          noahmp%water_state_SnowLiqWater(J+1, noahmp_c) = noahmp%water_state_SnowLiqWater(J+1, noahmp_c) + noahmp%water_state_SnowLiqWater(J, noahmp_c)
          noahmp%water_state_SnowIce(J+1, noahmp_c) = noahmp%water_state_SnowIce(J+1, noahmp_c) + noahmp%water_state_SnowIce(J, noahmp_c)
          noahmp%config_domain_ThicknessSnowSoilLayer(J+1, noahmp_c) = noahmp%config_domain_ThicknessSnowSoilLayer(J+1, noahmp_c) + noahmp%config_domain_ThicknessSnowSoilLayer(J, noahmp_c)
        else
          if ( noahmp%config_domain_NumSnowLayerNeg(noahmp_c) < -1 ) then
            noahmp%water_state_SnowLiqWater(J-1, noahmp_c) = noahmp%water_state_SnowLiqWater(J-1, noahmp_c) + noahmp%water_state_SnowLiqWater(J, noahmp_c)
            noahmp%water_state_SnowIce(J-1, noahmp_c) = noahmp%water_state_SnowIce(J-1, noahmp_c) + noahmp%water_state_SnowIce(J, noahmp_c)
            noahmp%config_domain_ThicknessSnowSoilLayer(J-1, noahmp_c) = noahmp%config_domain_ThicknessSnowSoilLayer(J-1, noahmp_c) + noahmp%config_domain_ThicknessSnowSoilLayer(J, noahmp_c)
          else
            if ( noahmp%water_state_SnowIce(J, noahmp_c) >= 0.0 ) then
              noahmp%water_state_PondSfcThinSnwComb(noahmp_c) = noahmp%water_state_SnowLiqWater(J, noahmp_c)
              noahmp%water_state_SnowWaterEquiv(noahmp_c) = noahmp%water_state_SnowIce(J, noahmp_c)
              noahmp%water_state_SnowDepth(noahmp_c) = noahmp%config_domain_ThicknessSnowSoilLayer(J, noahmp_c)
            else
              noahmp%water_state_PondSfcThinSnwComb(noahmp_c) = noahmp%water_state_SnowLiqWater(J, noahmp_c) + noahmp%water_state_SnowIce(J, noahmp_c)
              if ( noahmp%water_state_PondSfcThinSnwComb(noahmp_c) < 0.0 ) then
                noahmp%water_state_SoilIce(1, noahmp_c) = noahmp%water_state_SoilIce(1, noahmp_c) + noahmp%water_state_PondSfcThinSnwComb(noahmp_c)/(noahmp%config_domain_ThicknessSnowSoilLayer(1, noahmp_c)*1000.0)
                noahmp%water_state_PondSfcThinSnwComb(noahmp_c) = 0.0
              endif
              noahmp%water_state_SnowWaterEquiv(noahmp_c) = 0.0
              noahmp%water_state_SnowDepth(noahmp_c) = 0.0
            endif
            noahmp%water_state_SnowLiqWater(J, noahmp_c) = 0.0
            noahmp%water_state_SnowIce(J, noahmp_c) = 0.0
            noahmp%config_domain_ThicknessSnowSoilLayer(J, noahmp_c) = 0.0
          endif
        endif
        if ( (J > noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1) .and. (noahmp%config_domain_NumSnowLayerNeg(noahmp_c) < -1) ) then
          do I = J, noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+2, -1
            noahmp%energy_state_TemperatureSoilSnow(I, noahmp_c) = noahmp%energy_state_TemperatureSoilSnow(I-1, noahmp_c)
            noahmp%water_state_SnowLiqWater(I, noahmp_c) = noahmp%water_state_SnowLiqWater(I-1, noahmp_c)
            noahmp%water_state_SnowIce(I, noahmp_c) = noahmp%water_state_SnowIce(I-1, noahmp_c)
            noahmp%config_domain_ThicknessSnowSoilLayer(I, noahmp_c) = noahmp%config_domain_ThicknessSnowSoilLayer(I-1, noahmp_c)
          enddo
        endif
        noahmp%config_domain_NumSnowLayerNeg(noahmp_c) = noahmp%config_domain_NumSnowLayerNeg(noahmp_c) + 1
      endif
    enddo
    if ( noahmp%water_state_SoilIce(1, noahmp_c) < 0.0) then
      noahmp%water_state_SoilLiqWater(1, noahmp_c) = noahmp%water_state_SoilLiqWater(1, noahmp_c) + noahmp%water_state_SoilIce(1, noahmp_c)
      noahmp%water_state_SoilIce(1, noahmp_c) = 0.0
    endif
    if ( noahmp%config_domain_NumSnowLayerNeg(noahmp_c) ==0 ) return
    noahmp%water_state_SnowWaterEquiv(noahmp_c) = 0.0
    noahmp%water_state_SnowDepth(noahmp_c) = 0.0
    SnowIceTmp = 0.0
    SnowLiqTmp = 0.0
    do J = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 0
      noahmp%water_state_SnowWaterEquiv(noahmp_c) = noahmp%water_state_SnowWaterEquiv(noahmp_c) + noahmp%water_state_SnowIce(J, noahmp_c) + noahmp%water_state_SnowLiqWater(J, noahmp_c)
      noahmp%water_state_SnowDepth(noahmp_c) = noahmp%water_state_SnowDepth(noahmp_c) + noahmp%config_domain_ThicknessSnowSoilLayer(J, noahmp_c)
      SnowIceTmp = SnowIceTmp + noahmp%water_state_SnowIce(J, noahmp_c)
      SnowLiqTmp = SnowLiqTmp + noahmp%water_state_SnowLiqWater(J, noahmp_c)
    enddo
    if ( (noahmp%water_state_SnowDepth(noahmp_c) < 0.025) .and. (noahmp%config_domain_NumSnowLayerNeg(noahmp_c) < 0) ) then
      noahmp%config_domain_NumSnowLayerNeg(noahmp_c) = 0
      noahmp%water_state_SnowWaterEquiv(noahmp_c) = SnowIceTmp
      noahmp%water_state_PondSfcThinSnwTrans(noahmp_c) = SnowLiqTmp
      if ( noahmp%water_state_SnowWaterEquiv(noahmp_c) <= 0.0 ) noahmp%water_state_SnowDepth(noahmp_c) = 0.0
    endif
    if ( noahmp%config_domain_NumSnowLayerNeg(noahmp_c) < -1 ) then
      NumSnowLayerOld = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)
      IndLayer = 1
      do I = NumSnowLayerOld+1, 0
        if ( noahmp%config_domain_ThicknessSnowSoilLayer(I, noahmp_c) < SnowThickMin(IndLayer) ) then
          if ( I == noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1 ) then
            IndNeighbor = I + 1
          else if ( I == 0 ) then
            IndNeighbor = I - 1
          else
            IndNeighbor = I + 1
            if ( (noahmp%config_domain_ThicknessSnowSoilLayer(I-1, noahmp_c)+noahmp%config_domain_ThicknessSnowSoilLayer(I, noahmp_c)) < (noahmp%config_domain_ThicknessSnowSoilLayer(I+1, noahmp_c)+noahmp%config_domain_ThicknessSnowSoilLayer(I, noahmp_c)) ) IndNeighbor = I-1
          endif
          if ( IndNeighbor > I ) then
            J = IndNeighbor
            L = I
          else
            J = I
            L = IndNeighbor
          endif
          call SnowLayerWaterCombo(noahmp%config_domain_ThicknessSnowSoilLayer(J, noahmp_c), noahmp%water_state_SnowLiqWater(J, noahmp_c), noahmp%water_state_SnowIce(J, noahmp_c), noahmp%energy_state_TemperatureSoilSnow(J, noahmp_c), &
            & noahmp%config_domain_ThicknessSnowSoilLayer(L, noahmp_c), noahmp%water_state_SnowLiqWater(L, noahmp_c), noahmp%water_state_SnowIce(L, noahmp_c), noahmp%energy_state_TemperatureSoilSnow(L, noahmp_c) )
          if ( (J-1) > (noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1) ) then
            do K = J-1, noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+2, -1
              noahmp%energy_state_TemperatureSoilSnow(K, noahmp_c) = noahmp%energy_state_TemperatureSoilSnow(K-1, noahmp_c)
              noahmp%water_state_SnowIce(K, noahmp_c) = noahmp%water_state_SnowIce(K-1, noahmp_c)
              noahmp%water_state_SnowLiqWater(K, noahmp_c) = noahmp%water_state_SnowLiqWater(K-1, noahmp_c)
              noahmp%config_domain_ThicknessSnowSoilLayer(K, noahmp_c) = noahmp%config_domain_ThicknessSnowSoilLayer(K-1, noahmp_c)
            enddo
          endif
          noahmp%config_domain_NumSnowLayerNeg(noahmp_c) = noahmp%config_domain_NumSnowLayerNeg(noahmp_c) + 1
          if ( noahmp%config_domain_NumSnowLayerNeg(noahmp_c) >= -1 ) Exit
        else
          IndLayer = IndLayer + 1
        endif
      enddo
    endif
  end subroutine SnowLayerCombine
end module lean_snowlayercombinemod

! Source: physics_noahmp/src/SnowLayerDivideMod.F90
module lean_snowlayerdividemod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_snowlayerwatercombomod, only: SnowLayerWaterCombo
  implicit none
  contains
  subroutine SnowLayerDivide(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: LoopInd
    integer :: NumSnowLayerTmp
    real(kind=kind_noahmp) :: SnowThickCombTmp
    real(kind=kind_noahmp) :: SnowIceExtra
    real(kind=kind_noahmp) :: SnowLiqExtra
    real(kind=kind_noahmp) :: SnowFracExtra
    real(kind=kind_noahmp) :: SnowTempGrad
    real(kind=kind_noahmp), dimension(1:3) :: SnowThickTmp
    real(kind=kind_noahmp), dimension(1:3) :: SnowIceTmp
    real(kind=kind_noahmp), dimension(1:3) :: SnowLiqTmp
    real(kind=kind_noahmp), dimension(1:3) :: TemperatureSnowTmp
    SnowIceTmp (:) = 0.0
    SnowLiqTmp (:) = 0.0
    TemperatureSnowTmp(:) = 0.0
    SnowThickTmp (:) = 0.0
    do LoopInd = 1, 3
      if ( LoopInd <= abs(noahmp%config_domain_NumSnowLayerNeg(noahmp_c)) ) then
        SnowThickTmp(LoopInd) = noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd+noahmp%config_domain_NumSnowLayerNeg(noahmp_c), noahmp_c)
        SnowIceTmp(LoopInd) = noahmp%water_state_SnowIce(LoopInd+noahmp%config_domain_NumSnowLayerNeg(noahmp_c), noahmp_c)
        SnowLiqTmp(LoopInd) = noahmp%water_state_SnowLiqWater(LoopInd+noahmp%config_domain_NumSnowLayerNeg(noahmp_c), noahmp_c)
        TemperatureSnowTmp(LoopInd) = noahmp%energy_state_TemperatureSoilSnow(LoopInd+noahmp%config_domain_NumSnowLayerNeg(noahmp_c), noahmp_c)
      endif
    enddo
    NumSnowLayerTmp = abs(noahmp%config_domain_NumSnowLayerNeg(noahmp_c))
    if ( NumSnowLayerTmp == 1 ) then
      if ( SnowThickTmp(1) > 0.05 ) then
        NumSnowLayerTmp = 2
        SnowThickTmp(1) = SnowThickTmp(1)/2.0
        SnowIceTmp(1) = SnowIceTmp(1)/2.0
        SnowLiqTmp(1) = SnowLiqTmp(1)/2.0
        SnowThickTmp(2) = SnowThickTmp(1)
        SnowIceTmp(2) = SnowIceTmp(1)
        SnowLiqTmp(2) = SnowLiqTmp(1)
        TemperatureSnowTmp(2) = TemperatureSnowTmp(1)
      endif
    endif
    if ( NumSnowLayerTmp > 1 ) then
      if ( SnowThickTmp(1) > 0.05 ) then
        SnowThickCombTmp = SnowThickTmp(1) - 0.05
        SnowFracExtra = SnowThickCombTmp / SnowThickTmp(1)
        SnowIceExtra = SnowFracExtra * SnowIceTmp(1)
        SnowLiqExtra = SnowFracExtra * SnowLiqTmp(1)
        SnowFracExtra = 0.05 / SnowThickTmp(1)
        SnowIceTmp(1) = SnowFracExtra*SnowIceTmp(1)
        SnowLiqTmp(1) = SnowFracExtra*SnowLiqTmp(1)
        SnowThickTmp(1) = 0.05
        call SnowLayerWaterCombo(SnowThickTmp(2), SnowLiqTmp(2), SnowIceTmp(2), TemperatureSnowTmp(2), &
          & SnowThickCombTmp, SnowLiqExtra, SnowIceExtra, TemperatureSnowTmp(1))
        if ( (NumSnowLayerTmp <= 2) .and. (SnowThickTmp(2) > 0.20) ) then
          NumSnowLayerTmp = 3
          SnowTempGrad = (TemperatureSnowTmp(1) - TemperatureSnowTmp(2)) / ((SnowThickTmp(1)+SnowThickTmp(2)) / 2.0)
          SnowThickTmp(2) = SnowThickTmp(2) / 2.0
          SnowIceTmp(2) = SnowIceTmp(2) / 2.0
          SnowLiqTmp(2) = SnowLiqTmp(2) / 2.0
          SnowThickTmp(3) = SnowThickTmp(2)
          SnowIceTmp(3) = SnowIceTmp(2)
          SnowLiqTmp(3) = SnowLiqTmp(2)
          TemperatureSnowTmp(3) = TemperatureSnowTmp(2) - SnowTempGrad * SnowThickTmp(2) / 2.0
          if ( TemperatureSnowTmp(3) >= ConstFreezePoint ) then
            TemperatureSnowTmp(3) = TemperatureSnowTmp(2)
          else
            TemperatureSnowTmp(2) = TemperatureSnowTmp(2) + SnowTempGrad * SnowThickTmp(2) / 2.0
          endif
        endif
      endif
    endif
    if ( NumSnowLayerTmp > 2 ) then
      if ( SnowThickTmp(2) > 0.2 ) then
        SnowThickCombTmp = SnowThickTmp(2) - 0.2
        SnowFracExtra = SnowThickCombTmp / SnowThickTmp(2)
        SnowIceExtra = SnowFracExtra * SnowIceTmp(2)
        SnowLiqExtra = SnowFracExtra * SnowLiqTmp(2)
        SnowFracExtra = 0.2 / SnowThickTmp(2)
        SnowIceTmp(2) = SnowFracExtra * SnowIceTmp(2)
        SnowLiqTmp(2) = SnowFracExtra * SnowLiqTmp(2)
        SnowThickTmp(2) = 0.2
        call SnowLayerWaterCombo(SnowThickTmp(3), SnowLiqTmp(3), SnowIceTmp(3), TemperatureSnowTmp(3), &
          & SnowThickCombTmp, SnowLiqExtra, SnowIceExtra, TemperatureSnowTmp(2))
      endif
    endif
    noahmp%config_domain_NumSnowLayerNeg(noahmp_c) = -NumSnowLayerTmp
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 0
      noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c) = SnowThickTmp(LoopInd-noahmp%config_domain_NumSnowLayerNeg(noahmp_c))
      noahmp%water_state_SnowIce(LoopInd, noahmp_c) = SnowIceTmp(LoopInd-noahmp%config_domain_NumSnowLayerNeg(noahmp_c))
      noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c) = SnowLiqTmp(LoopInd-noahmp%config_domain_NumSnowLayerNeg(noahmp_c))
      noahmp%energy_state_TemperatureSoilSnow(LoopInd, noahmp_c) = TemperatureSnowTmp(LoopInd-noahmp%config_domain_NumSnowLayerNeg(noahmp_c))
    enddo
  end subroutine SnowLayerDivide
end module lean_snowlayerdividemod

! Source: physics_noahmp/src/SnowpackHydrologyMod.F90
module lean_snowpackhydrologymod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_snowlayercombinemod, only : SnowLayerCombine
  implicit none
  contains
  subroutine SnowpackHydrology(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: LoopInd
    real(kind=kind_noahmp) :: InflowSnowLayer
    real(kind=kind_noahmp) :: OutflowSnowLayer
    real(kind=kind_noahmp) :: SnowIceTmp
    real(kind=kind_noahmp) :: SnowWaterRatio
    real(kind=kind_noahmp) :: SnowWaterTmp
    real(kind=kind_noahmp), dimension(-2:0) :: SnowLiqVol
    real(kind=kind_noahmp), dimension(-2:0) :: SnowIceVol
    SnowLiqVol(:) = 0.0
    SnowIceVol(:) = 0.0
    noahmp%water_state_SnowEffPorosity(:, noahmp_c) = 0.0
    noahmp%water_flux_SnowBotOutflow(noahmp_c) = 0.0
    InflowSnowLayer = 0.0
    OutflowSnowLayer = 0.0
    if ( noahmp%water_state_SnowWaterEquiv(noahmp_c) == 0.0 ) then
      noahmp%water_state_SoilIce(1, noahmp_c) = noahmp%water_state_SoilIce(1, noahmp_c) + (noahmp%water_flux_FrostSnowSfcIce(noahmp_c)-noahmp%water_flux_SublimSnowSfcIce(noahmp_c)) * noahmp%config_domain_MainTimeStep(noahmp_c) / (noahmp%config_domain_ThicknessSnowSoilLayer(1, noahmp_c)*1000.0)
      if ( noahmp%water_state_SoilIce(1, noahmp_c) < 0.0 ) then
        noahmp%water_state_SoilLiqWater(1, noahmp_c) = noahmp%water_state_SoilLiqWater(1, noahmp_c) + noahmp%water_state_SoilIce(1, noahmp_c)
        noahmp%water_state_SoilIce(1, noahmp_c) = 0.0
      endif
    endif
    if ( (noahmp%config_domain_NumSnowLayerNeg(noahmp_c) == 0) .and. (noahmp%water_state_SnowWaterEquiv(noahmp_c) > 0.0) ) then
      SnowWaterTmp = noahmp%water_state_SnowWaterEquiv(noahmp_c)
      noahmp%water_state_SnowWaterEquiv(noahmp_c) = noahmp%water_state_SnowWaterEquiv(noahmp_c) - noahmp%water_flux_SublimSnowSfcIce(noahmp_c)*noahmp%config_domain_MainTimeStep(noahmp_c) + noahmp%water_flux_FrostSnowSfcIce(noahmp_c)*noahmp%config_domain_MainTimeStep(noahmp_c)
      SnowWaterRatio = noahmp%water_state_SnowWaterEquiv(noahmp_c) / SnowWaterTmp
      noahmp%water_state_SnowDepth(noahmp_c) = max(0.0, SnowWaterRatio*noahmp%water_state_SnowDepth(noahmp_c) )
      noahmp%water_state_SnowDepth(noahmp_c) = min(max(noahmp%water_state_SnowDepth(noahmp_c),noahmp%water_state_SnowWaterEquiv(noahmp_c)/500.0), noahmp%water_state_SnowWaterEquiv(noahmp_c)/50.0)
      if ( noahmp%water_state_SnowWaterEquiv(noahmp_c) < 0.0 ) then
        noahmp%water_state_SoilIce(1, noahmp_c) = noahmp%water_state_SoilIce(1, noahmp_c) + noahmp%water_state_SnowWaterEquiv(noahmp_c) / (noahmp%config_domain_ThicknessSnowSoilLayer(1, noahmp_c)*1000.0)
        noahmp%water_state_SnowWaterEquiv(noahmp_c) = 0.0
        noahmp%water_state_SnowDepth(noahmp_c) = 0.0
      endif
      if ( noahmp%water_state_SoilIce(1, noahmp_c) < 0.0 ) then
        noahmp%water_state_SoilLiqWater(1, noahmp_c) = noahmp%water_state_SoilLiqWater(1, noahmp_c) + noahmp%water_state_SoilIce(1, noahmp_c)
        noahmp%water_state_SoilIce(1, noahmp_c) = 0.0
      endif
    endif
    if ( (noahmp%water_state_SnowDepth(noahmp_c) <= 1.0e-8) .or. (noahmp%water_state_SnowWaterEquiv(noahmp_c) <= 1.0e-6) ) then
      noahmp%water_state_SnowDepth(noahmp_c) = 0.0
      noahmp%water_state_SnowWaterEquiv(noahmp_c) = 0.0
    endif
    if ( noahmp%config_domain_NumSnowLayerNeg(noahmp_c) < 0 ) then
      SnowIceTmp = noahmp%water_state_SnowIce(noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, noahmp_c) - noahmp%water_flux_SublimSnowSfcIce(noahmp_c)*noahmp%config_domain_MainTimeStep(noahmp_c) + noahmp%water_flux_FrostSnowSfcIce(noahmp_c)*noahmp%config_domain_MainTimeStep(noahmp_c)
      noahmp%water_state_SnowIce(noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, noahmp_c) = SnowIceTmp
      if ( (SnowIceTmp < 1.0e-6) .and. (noahmp%config_domain_NumSnowLayerNeg(noahmp_c) < 0) ) call SnowLayerCombine(noahmp, noahmp_c)
      if ( noahmp%config_domain_NumSnowLayerNeg(noahmp_c) < 0 ) then
        noahmp%water_state_SnowLiqWater(noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, noahmp_c) = noahmp%water_state_SnowLiqWater(noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, noahmp_c) + noahmp%water_flux_RainfallGround(noahmp_c) * noahmp%config_domain_MainTimeStep(noahmp_c)
        noahmp%water_state_SnowLiqWater(noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, noahmp_c) = max(0.0, noahmp%water_state_SnowLiqWater(noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, noahmp_c))
      endif
    endif
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 0
      SnowIceVol(LoopInd) = min(1.0, noahmp%water_state_SnowIce(LoopInd, noahmp_c)/(noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c)*ConstDensityIce))
      noahmp%water_state_SnowEffPorosity(LoopInd, noahmp_c) = 1.0 - SnowIceVol(LoopInd)
    enddo
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 0
      noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c) = noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c) + InflowSnowLayer
      SnowLiqVol(LoopInd) = noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c) / (noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c)*ConstDensityWater)
      OutflowSnowLayer = max(0.0, &
        & (SnowLiqVol(LoopInd)-noahmp%water_param_SnowLiqHoldCap(noahmp_c)*noahmp%water_state_SnowEffPorosity(LoopInd, noahmp_c)) * noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c))
      if ( LoopInd == 0 ) then
        OutflowSnowLayer = max((SnowLiqVol(LoopInd)-noahmp%water_state_SnowEffPorosity(LoopInd, noahmp_c)) * noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c), &
          & noahmp%water_param_SnowLiqReleaseFac(noahmp_c) * noahmp%config_domain_MainTimeStep(noahmp_c) * OutflowSnowLayer)
      endif
      OutflowSnowLayer = OutflowSnowLayer * ConstDensityWater
      noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c) = noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c) - OutflowSnowLayer
      if ( (noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c)/(noahmp%water_state_SnowIce(LoopInd, noahmp_c)+noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c))) > noahmp%water_param_SnowLiqFracMax(noahmp_c) ) then
        OutflowSnowLayer = OutflowSnowLayer + (noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c) - noahmp%water_param_SnowLiqFracMax(noahmp_c) / (1.0-noahmp%water_param_SnowLiqFracMax(noahmp_c)) * noahmp%water_state_SnowIce(LoopInd, noahmp_c))
        noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c) = noahmp%water_param_SnowLiqFracMax(noahmp_c) / (1.0 - noahmp%water_param_SnowLiqFracMax(noahmp_c)) * noahmp%water_state_SnowIce(LoopInd, noahmp_c)
      endif
      InflowSnowLayer = OutflowSnowLayer
    enddo
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 0
      noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c) = max(noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c), &
        & noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c)/ConstDensityWater+noahmp%water_state_SnowIce(LoopInd, noahmp_c)/ConstDensityIce)
    enddo
    noahmp%water_flux_SnowBotOutflow(noahmp_c) = OutflowSnowLayer / noahmp%config_domain_MainTimeStep(noahmp_c)
  end subroutine SnowpackHydrology
end module lean_snowpackhydrologymod

! Source: physics_noahmp/src/SnowWaterMainMod.F90
module lean_snowwatermainmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_snowfallbelowcanopymod, only : SnowfallAfterCanopyIntercept
  use lean_snowpackcompactionmod, only : SnowpackCompaction
  use lean_snowlayercombinemod, only : SnowLayerCombine
  use lean_snowlayerdividemod, only : SnowLayerDivide
  use lean_snowpackhydrologymod, only : SnowpackHydrology
  implicit none
  contains
  subroutine SnowWaterMain(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: LoopInd
    real(kind=kind_noahmp) :: SnowDensBulk
    noahmp%water_flux_GlacierExcessFlow(noahmp_c) = 0.0
    noahmp%water_state_PondSfcThinSnwComb(noahmp_c) = 0.0
    noahmp%water_state_PondSfcThinSnwTrans(noahmp_c) = 0.0
    call SnowfallAfterCanopyIntercept(noahmp, noahmp_c)
    if ( noahmp%config_domain_NumSnowLayerNeg(noahmp_c) < 0 ) call SnowpackCompaction(noahmp, noahmp_c)
    if ( noahmp%config_domain_NumSnowLayerNeg(noahmp_c) < 0 ) call SnowLayerCombine(noahmp, noahmp_c)
    if ( noahmp%config_domain_NumSnowLayerNeg(noahmp_c) < 0 ) call SnowLayerDivide(noahmp, noahmp_c)
    call SnowpackHydrology(noahmp, noahmp_c)
    do LoopInd = -3+1, noahmp%config_domain_NumSnowLayerNeg(noahmp_c)
      noahmp%water_state_SnowIce(LoopInd, noahmp_c) = 0.0
      noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c) = 0.0
      noahmp%energy_state_TemperatureSoilSnow(LoopInd, noahmp_c) = 0.0
      noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c) = 0.0
      noahmp%config_domain_DepthSnowSoilLayer(LoopInd, noahmp_c) = 0.0
    enddo
    if ( noahmp%water_state_SnowWaterEquiv(noahmp_c) > noahmp%water_param_SnoWatEqvMaxGlacier(noahmp_c) ) then
      SnowDensBulk = noahmp%water_state_SnowIce(0, noahmp_c) / noahmp%config_domain_ThicknessSnowSoilLayer(0, noahmp_c)
      noahmp%water_flux_GlacierExcessFlow(noahmp_c) = noahmp%water_state_SnowWaterEquiv(noahmp_c) - noahmp%water_param_SnoWatEqvMaxGlacier(noahmp_c)
      noahmp%water_state_SnowIce(0, noahmp_c) = noahmp%water_state_SnowIce(0, noahmp_c) - noahmp%water_flux_GlacierExcessFlow(noahmp_c)
      noahmp%config_domain_ThicknessSnowSoilLayer(0, noahmp_c) = noahmp%config_domain_ThicknessSnowSoilLayer(0, noahmp_c) - noahmp%water_flux_GlacierExcessFlow(noahmp_c) / SnowDensBulk
      noahmp%water_flux_GlacierExcessFlow(noahmp_c) = noahmp%water_flux_GlacierExcessFlow(noahmp_c) / noahmp%config_domain_MainTimeStep(noahmp_c)
    endif
    if ( noahmp%config_domain_NumSnowLayerNeg(noahmp_c) < 0 ) then
      noahmp%water_state_SnowWaterEquiv(noahmp_c) = 0.0
      do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 0
        noahmp%water_state_SnowWaterEquiv(noahmp_c) = noahmp%water_state_SnowWaterEquiv(noahmp_c) + noahmp%water_state_SnowIce(LoopInd, noahmp_c) + noahmp%water_state_SnowLiqWater(LoopInd, noahmp_c)
      enddo
    endif
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 0
      noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c) = -noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c)
    enddo
    noahmp%config_domain_ThicknessSnowSoilLayer(1, noahmp_c) = noahmp%config_domain_DepthSoilLayer(1, noahmp_c)
    do LoopInd = 2, 4
      noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c) = noahmp%config_domain_DepthSoilLayer(LoopInd, noahmp_c) - noahmp%config_domain_DepthSoilLayer(LoopInd-1, noahmp_c)
    enddo
    noahmp%config_domain_DepthSnowSoilLayer(noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, noahmp_c) = noahmp%config_domain_ThicknessSnowSoilLayer(noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, noahmp_c)
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+2, 4
      noahmp%config_domain_DepthSnowSoilLayer(LoopInd, noahmp_c) = noahmp%config_domain_DepthSnowSoilLayer(LoopInd-1, noahmp_c) + noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c)
    enddo
    do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 4
      noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c) = -noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c)
    enddo
    if ( noahmp%config_domain_NumSnowLayerNeg(noahmp_c) < 0 ) then
      noahmp%water_state_SnowDepth(noahmp_c) = 0.0
      do LoopInd = noahmp%config_domain_NumSnowLayerNeg(noahmp_c)+1, 0
        noahmp%water_state_SnowDepth(noahmp_c) = noahmp%water_state_SnowDepth(noahmp_c) + noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c)
      enddo
    endif
    if ( (noahmp%water_state_SnowDepth(noahmp_c) <= 1.0e-6) .or. (noahmp%water_state_SnowWaterEquiv(noahmp_c) <= 1.0e-6) ) then
      noahmp%water_state_SnowDepth(noahmp_c) = 0.0
      noahmp%water_state_SnowWaterEquiv(noahmp_c) = 0.0
    endif
  end subroutine SnowWaterMain
end module lean_snowwatermainmod

! Source: physics_noahmp/src/IrrigationFloodMod.F90
module lean_irrigationfloodmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_irrigationinfilphilipmod, only : IrrigationInfilPhilip
  implicit none
  contains
  subroutine IrrigationFlood(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    real(kind=kind_noahmp) :: InfilRateSfc
    InfilRateSfc = 0.0
    call IrrigationInfilPhilip(noahmp, noahmp_c, noahmp%config_domain_SoilTimeStep(noahmp_c), InfilRateSfc)
    noahmp%water_flux_IrrigationRateFlood(noahmp_c) = InfilRateSfc * noahmp%config_domain_SoilTimeStep(noahmp_c) * noahmp%water_param_IrriFloodRateFac(noahmp_c)
    noahmp%water_flux_IrrigationRateFlood(noahmp_c) = noahmp%water_flux_IrrigationRateFlood(noahmp_c) * noahmp%water_state_IrrigationFracFlood(noahmp_c)
    if ( noahmp%water_flux_IrrigationRateFlood(noahmp_c) >= noahmp%water_state_IrrigationAmtFlood(noahmp_c) ) then
      noahmp%water_flux_IrrigationRateFlood(noahmp_c) = noahmp%water_state_IrrigationAmtFlood(noahmp_c)
      noahmp%water_state_IrrigationAmtFlood(noahmp_c) = 0.0
    else
      noahmp%water_state_IrrigationAmtFlood(noahmp_c) = noahmp%water_state_IrrigationAmtFlood(noahmp_c) - noahmp%water_flux_IrrigationRateFlood(noahmp_c)
    endif
    noahmp%water_flux_SoilSfcInflowAcc(noahmp_c) = noahmp%water_flux_SoilSfcInflowAcc(noahmp_c) + (noahmp%water_flux_IrrigationRateFlood(noahmp_c) / noahmp%config_domain_SoilTimeStep(noahmp_c) * noahmp%config_domain_NumSoilTimeStep(noahmp_c))
  end subroutine IrrigationFlood
end module lean_irrigationfloodmod

! Source: physics_noahmp/src/IrrigationMicroMod.F90
module lean_irrigationmicromod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_irrigationinfilphilipmod, only : IrrigationInfilPhilip
  implicit none
  contains
  subroutine IrrigationMicro(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    real(kind=kind_noahmp) :: InfilRateSfc
    real(kind=kind_noahmp) :: IrriRateTmp
    InfilRateSfc = 0.0
    IrriRateTmp = 0.0
    call IrrigationInfilPhilip(noahmp, noahmp_c, noahmp%config_domain_SoilTimeStep(noahmp_c), InfilRateSfc)
    IrriRateTmp = noahmp%water_param_IrriMicroRate(noahmp_c) * (1.0/1000.0) * noahmp%config_domain_SoilTimeStep(noahmp_c)/ 3600.0
    noahmp%water_flux_IrrigationRateMicro(noahmp_c) = min(0.5*InfilRateSfc*noahmp%config_domain_SoilTimeStep(noahmp_c), noahmp%water_state_IrrigationAmtMicro(noahmp_c), IrriRateTmp)
    noahmp%water_flux_IrrigationRateMicro(noahmp_c) = noahmp%water_flux_IrrigationRateMicro(noahmp_c) * noahmp%water_state_IrrigationFracMicro(noahmp_c)
    if ( noahmp%water_flux_IrrigationRateMicro(noahmp_c) >= noahmp%water_state_IrrigationAmtMicro(noahmp_c) ) then
      noahmp%water_flux_IrrigationRateMicro(noahmp_c) = noahmp%water_state_IrrigationAmtMicro(noahmp_c)
      noahmp%water_state_IrrigationAmtMicro(noahmp_c) = 0.0
    else
      noahmp%water_state_IrrigationAmtMicro(noahmp_c) = noahmp%water_state_IrrigationAmtMicro(noahmp_c) - noahmp%water_flux_IrrigationRateMicro(noahmp_c)
    endif
    noahmp%water_state_SoilLiqWater(1, noahmp_c) = noahmp%water_state_SoilLiqWater(1, noahmp_c) + (noahmp%water_flux_IrrigationRateMicro(noahmp_c) / (-1.0*noahmp%config_domain_DepthSoilLayer(1, noahmp_c)))
  end subroutine IrrigationMicro
end module lean_irrigationmicromod

! Source: physics_noahmp/src/RunoffSurfaceFreeDrainMod.F90
module lean_runoffsurfacefreedrainmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_soilhydraulicpropertymod, only : SoilDiffusivityConductivityOpt2
  implicit none
  contains
  subroutine RunoffSurfaceFreeDrain(noahmp, noahmp_c, TimeStep)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    real(kind=kind_noahmp), intent(in) :: TimeStep
    integer :: IndSoilFrz
    integer :: LoopInd1, LoopInd2, LoopInd3
    integer, parameter :: FrzSoilFac = 3
    real(kind=kind_noahmp) :: FracVoidRem
    real(kind=kind_noahmp) :: SoilWatHoldMaxRem
    real(kind=kind_noahmp) :: WaterInSfc
    real(kind=kind_noahmp) :: TimeStepDay
    real(kind=kind_noahmp) :: SoilWatHoldMaxAcc
    real(kind=kind_noahmp) :: SoilIceWatTmp
    real(kind=kind_noahmp) :: SoilImpervFrac
    real(kind=kind_noahmp) :: IndAcc
    real(kind=kind_noahmp) :: SoilIceCoeff
    real(kind=kind_noahmp) :: SoilWatDiffusivity
    real(kind=kind_noahmp) :: SoilWatConductivity
    real(kind=kind_noahmp) :: SoilWatHoldCap
    real(kind=kind_noahmp) :: InfilRateMax
    real(kind=kind_noahmp), dimension(1:4) :: SoilWatMaxHold
    SoilWatMaxHold(1:4) = 0.0
    if ( noahmp%water_flux_SoilSfcInflowMean(noahmp_c) > 0.0 ) then
      TimeStepDay = TimeStep / 86400.0
      SoilWatHoldCap = noahmp%water_param_SoilMoistureSat(1, noahmp_c) - noahmp%water_param_SoilMoistureWilt(1, noahmp_c)
      SoilWatMaxHold(1) = -noahmp%config_domain_DepthSoilLayer(1, noahmp_c) * SoilWatHoldCap
      SoilIceWatTmp = -noahmp%config_domain_DepthSoilLayer(1, noahmp_c) * noahmp%water_state_SoilIce(1, noahmp_c)
      SoilWatMaxHold(1) = SoilWatMaxHold(1) * (1.0-(noahmp%water_state_SoilLiqWater(1, noahmp_c)+noahmp%water_state_SoilIce(1, noahmp_c)-noahmp%water_param_SoilMoistureWilt(1, noahmp_c)) / SoilWatHoldCap)
      SoilWatHoldMaxAcc = SoilWatMaxHold(1)
      do LoopInd3 = 2, 4
        SoilIceWatTmp = SoilIceWatTmp + (noahmp%config_domain_DepthSoilLayer(LoopInd3-1, noahmp_c) - noahmp%config_domain_DepthSoilLayer(LoopInd3, noahmp_c))*noahmp%water_state_SoilIce(LoopInd3, noahmp_c)
        SoilWatMaxHold(LoopInd3) = (noahmp%config_domain_DepthSoilLayer(LoopInd3-1, noahmp_c) - noahmp%config_domain_DepthSoilLayer(LoopInd3, noahmp_c)) * SoilWatHoldCap
        SoilWatMaxHold(LoopInd3) = SoilWatMaxHold(LoopInd3) * (1.0 - (noahmp%water_state_SoilLiqWater(LoopInd3, noahmp_c) + noahmp%water_state_SoilIce(LoopInd3, noahmp_c) - noahmp%water_param_SoilMoistureWilt(LoopInd3, noahmp_c)) / SoilWatHoldCap)
        SoilWatHoldMaxAcc = SoilWatHoldMaxAcc + SoilWatMaxHold(LoopInd3)
      enddo
      FracVoidRem = 1.0 - exp(-1.0 * noahmp%water_param_SoilInfilMaxCoeff(noahmp_c) * TimeStepDay)
      SoilWatHoldMaxRem = SoilWatHoldMaxAcc * FracVoidRem
      WaterInSfc = max(0.0, noahmp%water_flux_SoilSfcInflowMean(noahmp_c) * TimeStep)
      InfilRateMax = (WaterInSfc * (SoilWatHoldMaxRem/(WaterInSfc + SoilWatHoldMaxRem))) / TimeStep
      SoilImpervFrac = 1.0
      if ( SoilIceWatTmp > 1.0e-2 ) then
        SoilIceCoeff = FrzSoilFac * noahmp%water_param_SoilImpervFracCoeff(noahmp_c) / SoilIceWatTmp
        IndAcc = 1.0
        IndSoilFrz = FrzSoilFac - 1
        do LoopInd1 = 1, IndSoilFrz
          LoopInd3 = 1
          do LoopInd2 = LoopInd1+1, IndSoilFrz
            LoopInd3 = LoopInd3 * LoopInd2
          enddo
          IndAcc = IndAcc + (SoilIceCoeff ** (FrzSoilFac-LoopInd1)) / float(LoopInd3)
        enddo
        SoilImpervFrac = 1.0 - exp(-SoilIceCoeff) * IndAcc
      endif
      InfilRateMax = InfilRateMax * SoilImpervFrac
      call SoilDiffusivityConductivityOpt2(noahmp, noahmp_c, SoilWatDiffusivity, SoilWatConductivity, noahmp%water_state_SoilLiqWater(1, noahmp_c), &
        & noahmp%water_state_SoilIceMax(noahmp_c), 1)
      InfilRateMax = max(InfilRateMax, SoilWatConductivity)
      InfilRateMax = min(InfilRateMax, WaterInSfc/TimeStep)
      noahmp%water_flux_RunoffSurface(noahmp_c) = max(0.0, noahmp%water_flux_SoilSfcInflowMean(noahmp_c)-InfilRateMax)
      noahmp%water_flux_InfilRateSfc(noahmp_c) = noahmp%water_flux_SoilSfcInflowMean(noahmp_c) - noahmp%water_flux_RunoffSurface(noahmp_c)
    endif
  end subroutine RunoffSurfaceFreeDrain
end module lean_runoffsurfacefreedrainmod

! Source: physics_noahmp/src/RunoffSubSurfaceDrainageMod.F90
module lean_runoffsubsurfacedrainagemod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine RunoffSubSurfaceDrainage(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    noahmp%water_flux_RunoffSubsurface(noahmp_c) = noahmp%water_flux_RunoffSubsurface(noahmp_c) + noahmp%water_flux_DrainSoilBot(noahmp_c)
  end subroutine RunoffSubSurfaceDrainage
end module lean_runoffsubsurfacedrainagemod

! Source: physics_noahmp/src/SoilWaterDiffusionRichardsMod.F90
module lean_soilwaterdiffusionrichardsmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_soilhydraulicpropertymod
  implicit none
  contains
  subroutine SoilWaterDiffusionRichards(noahmp, noahmp_c, MatLeft1, MatLeft2, MatLeft3, MatRight)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    real(kind=kind_noahmp), dimension(4), intent(inout) :: MatRight
    real(kind=kind_noahmp), dimension(4), intent(inout) :: MatLeft1
    real(kind=kind_noahmp), dimension(4), intent(inout) :: MatLeft2
    real(kind=kind_noahmp), dimension(4), intent(inout) :: MatLeft3
    integer :: LoopInd
    real(kind=kind_noahmp) :: DepthSnowSoilTmp
    real(kind=kind_noahmp) :: SoilMoistTmpToWT
    real(kind=kind_noahmp) :: SoilMoistBotTmp
    real(kind=kind_noahmp), dimension(1:4) :: DepthSnowSoilInv
    real(kind=kind_noahmp), dimension(1:4) :: SoilThickTmp
    real(kind=kind_noahmp), dimension(1:4) :: SoilWaterGrad
    real(kind=kind_noahmp), dimension(1:4) :: WaterExcess
    real(kind=kind_noahmp), dimension(1:4) :: SoilMoistureTmp
    MatRight(:) = 0.0
    MatLeft1(:) = 0.0
    MatLeft2(:) = 0.0
    MatLeft3(:) = 0.0
    DepthSnowSoilInv(:) = 0.0
    SoilThickTmp(:) = 0.0
    SoilWaterGrad(:) = 0.0
    WaterExcess(:) = 0.0
    SoilMoistureTmp(:) = 0.0
    do LoopInd = 1, 4
      call SoilDiffusivityConductivityOpt1(noahmp, noahmp_c,noahmp%water_state_SoilWatDiffusivity(LoopInd, noahmp_c),noahmp%water_state_SoilWatConductivity(LoopInd, noahmp_c), &
        & noahmp%water_state_SoilMoisture(LoopInd, noahmp_c),noahmp%water_state_SoilImpervFrac(LoopInd, noahmp_c),LoopInd)
      SoilMoistureTmp(LoopInd) = noahmp%water_state_SoilMoisture(LoopInd, noahmp_c)
    enddo
    do LoopInd = 1, 4
      if ( LoopInd == 1 ) then
        SoilThickTmp(LoopInd) = - noahmp%config_domain_DepthSoilLayer(LoopInd, noahmp_c)
        DepthSnowSoilTmp = - noahmp%config_domain_DepthSoilLayer(LoopInd+1, noahmp_c)
        DepthSnowSoilInv(LoopInd) = 2.0 / DepthSnowSoilTmp
        SoilWaterGrad(LoopInd) = 2.0 * (SoilMoistureTmp(LoopInd)-SoilMoistureTmp(LoopInd+1)) / DepthSnowSoilTmp
        WaterExcess(LoopInd) = noahmp%water_state_SoilWatDiffusivity(LoopInd, noahmp_c)*SoilWaterGrad(LoopInd) + noahmp%water_state_SoilWatConductivity(LoopInd, noahmp_c) - noahmp%water_flux_InfilRateSfc(noahmp_c) + noahmp%water_flux_TranspWatLossSoilMean(LoopInd, noahmp_c) + noahmp%water_flux_EvapSoilSfcLiqMean(noahmp_c)
      else if ( LoopInd < 4 ) then
        SoilThickTmp(LoopInd) = (noahmp%config_domain_DepthSoilLayer(LoopInd-1, noahmp_c) - noahmp%config_domain_DepthSoilLayer(LoopInd, noahmp_c))
        DepthSnowSoilTmp = (noahmp%config_domain_DepthSoilLayer(LoopInd-1, noahmp_c) - noahmp%config_domain_DepthSoilLayer(LoopInd+1, noahmp_c))
        DepthSnowSoilInv(LoopInd) = 2.0 / DepthSnowSoilTmp
        SoilWaterGrad(LoopInd) = 2.0 * (SoilMoistureTmp(LoopInd) - SoilMoistureTmp(LoopInd+1)) / DepthSnowSoilTmp
        WaterExcess(LoopInd) = noahmp%water_state_SoilWatDiffusivity(LoopInd, noahmp_c)*SoilWaterGrad(LoopInd) + noahmp%water_state_SoilWatConductivity(LoopInd, noahmp_c) - noahmp%water_state_SoilWatDiffusivity(LoopInd-1, noahmp_c)*SoilWaterGrad(LoopInd-1) - noahmp%water_state_SoilWatConductivity(LoopInd-1, noahmp_c) + noahmp%water_flux_TranspWatLossSoilMean(LoopInd, noahmp_c)
      else
        SoilThickTmp(LoopInd) = (noahmp%config_domain_DepthSoilLayer(LoopInd-1, noahmp_c) - noahmp%config_domain_DepthSoilLayer(LoopInd, noahmp_c))
        noahmp%water_flux_DrainSoilBot(noahmp_c) = noahmp%water_param_SoilDrainSlope(noahmp_c) * noahmp%water_state_SoilWatConductivity(LoopInd, noahmp_c)
        WaterExcess(LoopInd) = -(noahmp%water_state_SoilWatDiffusivity(LoopInd-1, noahmp_c)*SoilWaterGrad(LoopInd-1)) - noahmp%water_state_SoilWatConductivity(LoopInd-1, noahmp_c) + noahmp%water_flux_TranspWatLossSoilMean(LoopInd, noahmp_c) + noahmp%water_flux_DrainSoilBot(noahmp_c)
      endif
    enddo
    do LoopInd = 1, 4
      if ( LoopInd == 1 ) then
        MatLeft1(LoopInd) = 0.0
        MatLeft2(LoopInd) = noahmp%water_state_SoilWatDiffusivity(LoopInd , noahmp_c) * DepthSnowSoilInv(LoopInd ) / SoilThickTmp(LoopInd)
        MatLeft3(LoopInd) = - MatLeft2(LoopInd)
      else if ( LoopInd < 4 ) then
        MatLeft1(LoopInd) = - noahmp%water_state_SoilWatDiffusivity(LoopInd-1, noahmp_c) * DepthSnowSoilInv(LoopInd-1) / SoilThickTmp(LoopInd)
        MatLeft3(LoopInd) = - noahmp%water_state_SoilWatDiffusivity(LoopInd , noahmp_c) * DepthSnowSoilInv(LoopInd ) / SoilThickTmp(LoopInd)
        MatLeft2(LoopInd) = - (MatLeft1(LoopInd) + MatLeft3(LoopInd))
      else
        MatLeft1(LoopInd) = - noahmp%water_state_SoilWatDiffusivity(LoopInd-1, noahmp_c) * DepthSnowSoilInv(LoopInd-1) / SoilThickTmp(LoopInd)
        MatLeft3(LoopInd) = 0.0
        MatLeft2(LoopInd) = - (MatLeft1(LoopInd) + MatLeft3(LoopInd))
      endif
      MatRight(LoopInd) = WaterExcess(LoopInd) / (-SoilThickTmp(LoopInd))
    enddo
  end subroutine SoilWaterDiffusionRichards
end module lean_soilwaterdiffusionrichardsmod

! Source: physics_noahmp/src/SoilMoistureSolverMod.F90
module lean_soilmoisturesolvermod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_matrixsolvertridiagonalmod, only : MatrixSolverTriDiagonal
  implicit none
  contains
  subroutine SoilMoistureSolver(noahmp, noahmp_c, TimeStep, MatLeft1, MatLeft2, MatLeft3, MatRight)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    real(kind=kind_noahmp), intent(in) :: TimeStep
    real(kind=kind_noahmp), dimension(4), intent(inout) :: MatRight
    real(kind=kind_noahmp), dimension(4), intent(inout) :: MatLeft1
    real(kind=kind_noahmp), dimension(4), intent(inout) :: MatLeft2
    real(kind=kind_noahmp), dimension(4), intent(inout) :: MatLeft3
    integer :: LoopInd
    real(kind=kind_noahmp) :: WatDefiTmp
    real(kind=kind_noahmp), dimension(1:4) :: MatRightTmp
    real(kind=kind_noahmp), dimension(1:4) :: MatLeft3Tmp
    MatRightTmp = 0.0
    MatLeft3Tmp = 0.0
    noahmp%water_state_SoilSaturationExcess(noahmp_c) = 0.0
    noahmp%water_state_SoilEffPorosity(:, noahmp_c) = 0.0
    do LoopInd = 1, 4
      MatRight(LoopInd) = MatRight(LoopInd) * TimeStep
      MatLeft1(LoopInd) = MatLeft1(LoopInd) * TimeStep
      MatLeft2(LoopInd) = 1.0 + MatLeft2(LoopInd) * TimeStep
      MatLeft3(LoopInd) = MatLeft3(LoopInd) * TimeStep
    enddo
    do LoopInd = 1, 4
      MatRightTmp(LoopInd) = MatRight(LoopInd)
      MatLeft3Tmp(LoopInd) = MatLeft3(LoopInd)
    enddo
    call MatrixSolverTriDiagonal(MatLeft3,MatLeft1,MatLeft2,MatLeft3Tmp,MatRightTmp,MatRight,1,4,0)
    do LoopInd = 1, 4
      noahmp%water_state_SoilLiqWater(LoopInd, noahmp_c) = noahmp%water_state_SoilLiqWater(LoopInd, noahmp_c) + MatLeft3(LoopInd)
    enddo
    do LoopInd = 4, 2, -1
      noahmp%water_state_SoilEffPorosity(LoopInd, noahmp_c) = max(1.0e-4, (noahmp%water_param_SoilMoistureSat(LoopInd, noahmp_c) - noahmp%water_state_SoilIce(LoopInd, noahmp_c)))
      noahmp%water_state_SoilSaturationExcess(noahmp_c) = max((noahmp%water_state_SoilLiqWater(LoopInd, noahmp_c)-noahmp%water_state_SoilEffPorosity(LoopInd, noahmp_c)), &
        & 0.0) * noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c)
      noahmp%water_state_SoilLiqWater(LoopInd, noahmp_c) = min(noahmp%water_state_SoilEffPorosity(LoopInd, noahmp_c), noahmp%water_state_SoilLiqWater(LoopInd, noahmp_c) )
      noahmp%water_state_SoilLiqWater(LoopInd-1, noahmp_c) = noahmp%water_state_SoilLiqWater(LoopInd-1, noahmp_c) + noahmp%water_state_SoilSaturationExcess(noahmp_c) / noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd-1, noahmp_c)
    enddo
    noahmp%water_state_SoilEffPorosity(1, noahmp_c) = max(1.0e-4, (noahmp%water_param_SoilMoistureSat(1, noahmp_c)-noahmp%water_state_SoilIce(1, noahmp_c)))
    noahmp%water_state_SoilSaturationExcess(noahmp_c) = max((noahmp%water_state_SoilLiqWater(1, noahmp_c)-noahmp%water_state_SoilEffPorosity(1, noahmp_c)), 0.0) * noahmp%config_domain_ThicknessSnowSoilLayer(1, noahmp_c)
    noahmp%water_state_SoilLiqWater(1, noahmp_c) = min(noahmp%water_state_SoilEffPorosity(1, noahmp_c), noahmp%water_state_SoilLiqWater(1, noahmp_c))
    if ( noahmp%water_state_SoilSaturationExcess(noahmp_c) > 0.0 ) then
      noahmp%water_state_SoilLiqWater(2, noahmp_c) = noahmp%water_state_SoilLiqWater(2, noahmp_c) + noahmp%water_state_SoilSaturationExcess(noahmp_c) / noahmp%config_domain_ThicknessSnowSoilLayer(2, noahmp_c)
      do LoopInd = 2, 4-1
        noahmp%water_state_SoilEffPorosity(LoopInd, noahmp_c) = max(1.0e-4, (noahmp%water_param_SoilMoistureSat(LoopInd, noahmp_c) - noahmp%water_state_SoilIce(LoopInd, noahmp_c)))
        noahmp%water_state_SoilSaturationExcess(noahmp_c) = max((noahmp%water_state_SoilLiqWater(LoopInd, noahmp_c)-noahmp%water_state_SoilEffPorosity(LoopInd, noahmp_c)), &
          & 0.0) * noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c)
        noahmp%water_state_SoilLiqWater(LoopInd, noahmp_c) = min(noahmp%water_state_SoilEffPorosity(LoopInd, noahmp_c), noahmp%water_state_SoilLiqWater(LoopInd, noahmp_c))
        noahmp%water_state_SoilLiqWater(LoopInd+1, noahmp_c) = noahmp%water_state_SoilLiqWater(LoopInd+1, noahmp_c) + noahmp%water_state_SoilSaturationExcess(noahmp_c) / noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd+1, noahmp_c)
      enddo
      noahmp%water_state_SoilEffPorosity(4, noahmp_c) = max(1.0e-4, (noahmp%water_param_SoilMoistureSat(4, noahmp_c) - noahmp%water_state_SoilIce(4, noahmp_c)))
      noahmp%water_state_SoilSaturationExcess(noahmp_c) = max((noahmp%water_state_SoilLiqWater(4, noahmp_c)-noahmp%water_state_SoilEffPorosity(4, noahmp_c)), &
        & 0.0) * noahmp%config_domain_ThicknessSnowSoilLayer(4, noahmp_c)
      noahmp%water_state_SoilLiqWater(4, noahmp_c) = min(noahmp%water_state_SoilEffPorosity(4, noahmp_c), noahmp%water_state_SoilLiqWater(4, noahmp_c))
    endif
    noahmp%water_state_SoilMoisture(:, noahmp_c) = noahmp%water_state_SoilLiqWater(:, noahmp_c) + noahmp%water_state_SoilIce(:, noahmp_c)
  end subroutine SoilMoistureSolver
end module lean_soilmoisturesolvermod

! Source: physics_noahmp/src/SoilWaterMainMod.F90
module lean_soilwatermainmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_runoffsurfacefreedrainmod, only : RunoffSurfaceFreeDrain
  use lean_runoffsubsurfacedrainagemod, only : RunoffSubSurfaceDrainage
  use lean_soilwaterdiffusionrichardsmod, only : SoilWaterDiffusionRichards
  use lean_soilmoisturesolvermod, only : SoilMoistureSolver
  implicit none
  contains
  subroutine SoilWaterMain(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: LoopInd1, LoopInd2
    integer :: IndIter
    integer :: NumIterSoilWat
    real(kind=kind_noahmp) :: TimeStepFine
    real(kind=kind_noahmp) :: SoilSatExcAcc
    real(kind=kind_noahmp) :: SoilWatConductAcc
    real(kind=kind_noahmp) :: WaterRemove
    real(kind=kind_noahmp) :: SoilWatRem
    real(kind=kind_noahmp) :: SoilWaterMin
    real(kind=kind_noahmp) :: DrainSoilBotAcc
    real(kind=kind_noahmp) :: RunoffSurfaceAcc
    real(kind=kind_noahmp) :: InfilSfcAcc
    real(kind=kind_noahmp), parameter :: SoilImpPara = 4.0
    real(kind=kind_noahmp), dimension(1:4) :: MatRight
    real(kind=kind_noahmp), dimension(1:4) :: MatLeft1
    real(kind=kind_noahmp), dimension(1:4) :: MatLeft2
    real(kind=kind_noahmp), dimension(1:4) :: MatLeft3
    real(kind=kind_noahmp), dimension(1:4) :: SoilLiqTmp
    MatRight = 0.0
    MatLeft1 = 0.0
    MatLeft2 = 0.0
    MatLeft3 = 0.0
    SoilLiqTmp = 0.0
    noahmp%water_flux_RunoffSurface(noahmp_c) = 0.0
    noahmp%water_flux_RunoffSubsurface(noahmp_c) = 0.0
    noahmp%water_flux_InfilRateSfc(noahmp_c) = 0.0
    SoilSatExcAcc = 0.0
    InfilSfcAcc = 1.0e-06
    do LoopInd1 = 1, 4
      noahmp%water_state_SoilEffPorosity(LoopInd1, noahmp_c) = max(1.0e-4, (noahmp%water_param_SoilMoistureSat(LoopInd1, noahmp_c) - noahmp%water_state_SoilIce(LoopInd1, noahmp_c)))
      SoilSatExcAcc = SoilSatExcAcc + max(0.0, &
        & noahmp%water_state_SoilLiqWater(LoopInd1, noahmp_c) - noahmp%water_state_SoilEffPorosity(LoopInd1, noahmp_c)) * noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd1, noahmp_c)
      noahmp%water_state_SoilLiqWater(LoopInd1, noahmp_c) = min(noahmp%water_state_SoilEffPorosity(LoopInd1, noahmp_c), noahmp%water_state_SoilLiqWater(LoopInd1, noahmp_c))
    enddo
    do LoopInd1 = 1, 4
      noahmp%water_state_SoilIceFrac(LoopInd1, noahmp_c) = min(1.0, noahmp%water_state_SoilIce(LoopInd1, noahmp_c) / noahmp%water_param_SoilMoistureSat(LoopInd1, noahmp_c))
      noahmp%water_state_SoilImpervFrac(LoopInd1, noahmp_c) = max(0.0, &
        & exp(-SoilImpPara*(1.0-noahmp%water_state_SoilIceFrac(LoopInd1, noahmp_c))) - exp(-SoilImpPara)) / (1.0 - exp(-SoilImpPara))
    enddo
    noahmp%water_state_SoilIceMax(noahmp_c) = 0.0
    noahmp%water_state_SoilImpervFracMax(noahmp_c) = 0.0
    noahmp%water_state_SoilLiqWaterMin(noahmp_c) = noahmp%water_param_SoilMoistureSat(1, noahmp_c)
    do LoopInd1 = 1, 4
      if ( noahmp%water_state_SoilIce(LoopInd1, noahmp_c) > noahmp%water_state_SoilIceMax(noahmp_c) ) noahmp%water_state_SoilIceMax(noahmp_c) = noahmp%water_state_SoilIce(LoopInd1, noahmp_c)
      if ( noahmp%water_state_SoilImpervFrac(LoopInd1, noahmp_c) > noahmp%water_state_SoilImpervFracMax(noahmp_c) ) noahmp%water_state_SoilImpervFracMax(noahmp_c) = noahmp%water_state_SoilImpervFrac(LoopInd1, noahmp_c)
      if ( noahmp%water_state_SoilLiqWater(LoopInd1, noahmp_c) < noahmp%water_state_SoilLiqWaterMin(noahmp_c) ) noahmp%water_state_SoilLiqWaterMin(noahmp_c) = noahmp%water_state_SoilLiqWater(LoopInd1, noahmp_c)
    enddo
    if ( noahmp%config_domain_FlagUrban(noahmp_c) .eqv. .true. ) noahmp%water_state_SoilImpervFrac(1, noahmp_c) = 0.95
    call RunoffSurfaceFreeDrain(noahmp, noahmp_c,noahmp%config_domain_SoilTimeStep(noahmp_c))
    NumIterSoilWat = 3
    if ( (noahmp%water_flux_InfilRateSfc(noahmp_c)*noahmp%config_domain_SoilTimeStep(noahmp_c)) > (noahmp%config_domain_ThicknessSnowSoilLayer(1, noahmp_c)*noahmp%water_param_SoilMoistureSat(1, noahmp_c)) ) then
      NumIterSoilWat = NumIterSoilWat*2
    endif
    TimeStepFine = noahmp%config_domain_SoilTimeStep(noahmp_c) / NumIterSoilWat
    InfilSfcAcc = 1.0e-06
    DrainSoilBotAcc = 0.0
    RunoffSurfaceAcc = 0.0
    do IndIter = 1, NumIterSoilWat
      if ( noahmp%water_flux_SoilSfcInflowMean(noahmp_c) > 0.0 ) then
        call RunoffSurfaceFreeDrain(noahmp, noahmp_c,TimeStepFine)
      endif
      call SoilWaterDiffusionRichards(noahmp, noahmp_c, MatLeft1, MatLeft2, MatLeft3, MatRight)
      call SoilMoistureSolver(noahmp, noahmp_c, TimeStepFine, MatLeft1, MatLeft2, MatLeft3, MatRight)
      SoilSatExcAcc = SoilSatExcAcc + noahmp%water_state_SoilSaturationExcess(noahmp_c)
      DrainSoilBotAcc = DrainSoilBotAcc + noahmp%water_flux_DrainSoilBot(noahmp_c)
      RunoffSurfaceAcc = RunoffSurfaceAcc + noahmp%water_flux_RunoffSurface(noahmp_c)
    enddo
    noahmp%water_flux_DrainSoilBot(noahmp_c) = DrainSoilBotAcc / NumIterSoilWat
    noahmp%water_flux_RunoffSurface(noahmp_c) = RunoffSurfaceAcc / NumIterSoilWat
    noahmp%water_flux_RunoffSurface(noahmp_c) = noahmp%water_flux_RunoffSurface(noahmp_c) * 1000.0 + SoilSatExcAcc * 1000.0 / noahmp%config_domain_SoilTimeStep(noahmp_c)
    noahmp%water_flux_DrainSoilBot(noahmp_c) = noahmp%water_flux_DrainSoilBot(noahmp_c) * 1000.0
    do LoopInd2 = 1, 4
      SoilLiqTmp(LoopInd2) = noahmp%water_state_SoilLiqWater(LoopInd2, noahmp_c) * noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd2, noahmp_c) * 1000.0
    enddo
    SoilWaterMin = 0.01
    do LoopInd2 = 1, 4-1
      if ( SoilLiqTmp(LoopInd2) < 0.0 ) then
        SoilWatRem = SoilWaterMin - SoilLiqTmp(LoopInd2)
      else
        SoilWatRem = 0.0
      endif
      SoilLiqTmp(LoopInd2 ) = SoilLiqTmp(LoopInd2 ) + SoilWatRem
      SoilLiqTmp(LoopInd2+1) = SoilLiqTmp(LoopInd2+1) - SoilWatRem
    enddo
    LoopInd2 = 4
    if ( SoilLiqTmp(LoopInd2) < SoilWaterMin ) then
      SoilWatRem = SoilWaterMin - SoilLiqTmp(LoopInd2)
    else
      SoilWatRem = 0.0
    endif
    SoilLiqTmp(LoopInd2) = SoilLiqTmp(LoopInd2) + SoilWatRem
    noahmp%water_flux_RunoffSubsurface(noahmp_c) = noahmp%water_flux_RunoffSubsurface(noahmp_c) - SoilWatRem/noahmp%config_domain_SoilTimeStep(noahmp_c)
    do LoopInd2 = 1, 4
      noahmp%water_state_SoilLiqWater(LoopInd2, noahmp_c) = SoilLiqTmp(LoopInd2) / (noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd2, noahmp_c)*1000.0)
    enddo
    call RunoffSubSurfaceDrainage(noahmp, noahmp_c)
    do LoopInd2 = 1, 4
      noahmp%water_state_SoilMoisture(LoopInd2, noahmp_c) = noahmp%water_state_SoilLiqWater(LoopInd2, noahmp_c) + noahmp%water_state_SoilIce(LoopInd2, noahmp_c)
    enddo
    noahmp%water_flux_RunoffSurface(noahmp_c) = noahmp%water_flux_RunoffSurface(noahmp_c) * noahmp%config_domain_SoilTimeStep(noahmp_c)
    noahmp%water_flux_RunoffSubsurface(noahmp_c) = noahmp%water_flux_RunoffSubsurface(noahmp_c) * noahmp%config_domain_SoilTimeStep(noahmp_c)
    noahmp%water_flux_TileDrain(noahmp_c) = noahmp%water_flux_TileDrain(noahmp_c) * noahmp%config_domain_SoilTimeStep(noahmp_c)
  end subroutine SoilWaterMain
end module lean_soilwatermainmod

! Source: physics_noahmp/src/WaterMainMod.F90
module lean_watermainmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_canopyhydrologymod, only : CanopyHydrology
  use lean_snowwatermainmod, only : SnowWaterMain
  use lean_irrigationfloodmod, only : IrrigationFlood
  use lean_irrigationmicromod, only : IrrigationMicro
  use lean_soilwatermainmod, only : SoilWaterMain
  implicit none
  contains
  subroutine WaterMain(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: LoopInd
    noahmp%water_flux_TranspWatLossSoil(:, noahmp_c) = 0.0
    noahmp%water_flux_GlacierExcessFlow(noahmp_c) = 0.0
    noahmp%water_flux_RunoffSubsurface(noahmp_c) = 0.0
    noahmp%water_flux_RunoffSurface(noahmp_c) = 0.0
    noahmp%water_flux_SoilSfcInflow(noahmp_c) = 0.0
    noahmp%water_flux_TileDrain(noahmp_c) = 0.0
    noahmp%water_state_SoilIce(:, noahmp_c) = max(0.0, noahmp%water_state_SoilMoisture(:, noahmp_c)-noahmp%water_state_SoilLiqWater(:, noahmp_c))
    noahmp%water_state_SnowWaterEquivPrev(noahmp_c) = noahmp%water_state_SnowWaterEquiv(noahmp_c)
    noahmp%water_flux_VaporizeGrd(noahmp_c) = max(noahmp%energy_flux_HeatLatentGrd(noahmp_c)/noahmp%energy_state_LatHeatVapGrd(noahmp_c), 0.0)
    noahmp%water_flux_CondenseVapGrd(noahmp_c) = abs(min(noahmp%energy_flux_HeatLatentGrd(noahmp_c)/noahmp%energy_state_LatHeatVapGrd(noahmp_c), 0.0))
    noahmp%water_flux_EvapGroundNet(noahmp_c) = noahmp%water_flux_VaporizeGrd(noahmp_c) - noahmp%water_flux_CondenseVapGrd(noahmp_c)
    call CanopyHydrology(noahmp, noahmp_c)
    noahmp%water_flux_SublimSnowSfcIce(noahmp_c) = 0.0
    if ( noahmp%water_state_SnowWaterEquiv(noahmp_c) > 0.0 ) then
      noahmp%water_flux_SublimSnowSfcIce(noahmp_c) = min(noahmp%water_flux_VaporizeGrd(noahmp_c), noahmp%water_state_SnowWaterEquiv(noahmp_c)/noahmp%config_domain_MainTimeStep(noahmp_c))
    endif
    noahmp%water_flux_EvapSoilSfcLiq(noahmp_c) = noahmp%water_flux_VaporizeGrd(noahmp_c) - noahmp%water_flux_SublimSnowSfcIce(noahmp_c)
    noahmp%water_flux_FrostSnowSfcIce(noahmp_c) = 0.0
    if ( noahmp%water_state_SnowWaterEquiv(noahmp_c) > 0.0 ) then
      noahmp%water_flux_FrostSnowSfcIce(noahmp_c) = noahmp%water_flux_CondenseVapGrd(noahmp_c)
    endif
    noahmp%water_flux_DewSoilSfcLiq(noahmp_c) = noahmp%water_flux_CondenseVapGrd(noahmp_c) - noahmp%water_flux_FrostSnowSfcIce(noahmp_c)
    call SnowWaterMain(noahmp, noahmp_c)
    if ( noahmp%energy_state_FlagFrozenGround(noahmp_c) .eqv. .true. ) then
      noahmp%water_state_SoilIce(1, noahmp_c) = noahmp%water_state_SoilIce(1, noahmp_c) + (noahmp%water_flux_DewSoilSfcLiq(noahmp_c)-noahmp%water_flux_EvapSoilSfcLiq(noahmp_c)) * noahmp%config_domain_MainTimeStep(noahmp_c) / (noahmp%config_domain_ThicknessSnowSoilLayer(1, noahmp_c)*1000.0)
      noahmp%water_flux_DewSoilSfcLiq(noahmp_c) = 0.0
      noahmp%water_flux_EvapSoilSfcLiq(noahmp_c) = 0.0
      if ( noahmp%water_state_SoilIce(1, noahmp_c) < 0.0 ) then
        noahmp%water_state_SoilLiqWater(1, noahmp_c) = noahmp%water_state_SoilLiqWater(1, noahmp_c) + noahmp%water_state_SoilIce(1, noahmp_c)
        noahmp%water_state_SoilIce(1, noahmp_c) = 0.0
      endif
      noahmp%water_state_SoilMoisture(1, noahmp_c) = noahmp%water_state_SoilLiqWater(1, noahmp_c) + noahmp%water_state_SoilIce(1, noahmp_c)
    endif
    noahmp%water_flux_EvapSoilSfcLiq(noahmp_c) = noahmp%water_flux_EvapSoilSfcLiq(noahmp_c) * 0.001
    do LoopInd = 1, noahmp%water_param_NumSoilLayerRoot(noahmp_c)
      noahmp%water_flux_TranspWatLossSoil(LoopInd, noahmp_c) = noahmp%water_flux_Transpiration(noahmp_c) * noahmp%water_state_SoilTranspFac(LoopInd, noahmp_c) * 0.001
    enddo
    noahmp%water_flux_SoilSfcInflow(noahmp_c) = (noahmp%water_state_PondSfcThinSnwMelt(noahmp_c) + noahmp%water_state_PondSfcThinSnwComb(noahmp_c) + noahmp%water_state_PondSfcThinSnwTrans(noahmp_c)) / noahmp%config_domain_MainTimeStep(noahmp_c) * 0.001
    if ( noahmp%config_domain_NumSnowLayerNeg(noahmp_c) == 0 ) then
      noahmp%water_flux_SoilSfcInflow(noahmp_c) = noahmp%water_flux_SoilSfcInflow(noahmp_c) + (noahmp%water_flux_SnowBotOutflow(noahmp_c) + noahmp%water_flux_DewSoilSfcLiq(noahmp_c) + noahmp%water_flux_RainfallGround(noahmp_c)) * 0.001
    else
      noahmp%water_flux_SoilSfcInflow(noahmp_c) = noahmp%water_flux_SoilSfcInflow(noahmp_c) + (noahmp%water_flux_SnowBotOutflow(noahmp_c) + noahmp%water_flux_DewSoilSfcLiq(noahmp_c)) * 0.001
    endif
    noahmp%water_flux_SoilSfcInflowAcc(noahmp_c) = noahmp%water_flux_SoilSfcInflowAcc(noahmp_c) + noahmp%water_flux_SoilSfcInflow(noahmp_c)
    noahmp%water_flux_EvapSoilSfcLiqAcc(noahmp_c) = noahmp%water_flux_EvapSoilSfcLiqAcc(noahmp_c) + noahmp%water_flux_EvapSoilSfcLiq(noahmp_c)
    noahmp%water_flux_TranspWatLossSoilAcc(:, noahmp_c) = noahmp%water_flux_TranspWatLossSoilAcc(:, noahmp_c) + noahmp%water_flux_TranspWatLossSoil(:, noahmp_c)
    if ( noahmp%config_domain_FlagSoilProcess(noahmp_c) .eqv. .true. ) then
      if ( (noahmp%config_domain_FlagCropland(noahmp_c) .eqv. .true.) .and. (noahmp%water_state_IrrigationAmtFlood(noahmp_c) > 0.0) ) call IrrigationFlood(noahmp, noahmp_c)
      if ( (noahmp%config_domain_FlagCropland(noahmp_c) .eqv. .true.) .and. (noahmp%water_state_IrrigationAmtMicro(noahmp_c) > 0.0) ) call IrrigationMicro(noahmp, noahmp_c)
      noahmp%water_flux_SoilSfcInflowMean(noahmp_c) = noahmp%water_flux_SoilSfcInflowAcc(noahmp_c) / noahmp%config_domain_NumSoilTimeStep(noahmp_c)
      noahmp%water_flux_EvapSoilSfcLiqMean(noahmp_c) = noahmp%water_flux_EvapSoilSfcLiqAcc(noahmp_c) / noahmp%config_domain_NumSoilTimeStep(noahmp_c)
      noahmp%water_flux_TranspWatLossSoilMean(:, noahmp_c) = noahmp%water_flux_TranspWatLossSoilAcc(:, noahmp_c) / noahmp%config_domain_NumSoilTimeStep(noahmp_c)
      call SoilWaterMain(noahmp, noahmp_c)
    endif
    noahmp%water_flux_RunoffSubsurface(noahmp_c) = noahmp%water_flux_RunoffSubsurface(noahmp_c) + noahmp%water_flux_GlacierExcessFlow(noahmp_c) * noahmp%config_domain_MainTimeStep(noahmp_c)
    noahmp%water_flux_WaterToAtmosTotal(noahmp_c) = noahmp%water_flux_Transpiration(noahmp_c) + noahmp%water_flux_EvapCanopyNet(noahmp_c) + noahmp%water_flux_EvapGroundNet(noahmp_c)
    if ( (noahmp%config_domain_FlagUrban(noahmp_c) .eqv. .true.) ) then
      noahmp%energy_state_SpecHumiditySfc(noahmp_c) = noahmp%water_flux_WaterToAtmosTotal(noahmp_c) / (noahmp%energy_state_DensityAirRefHeight(noahmp_c)*noahmp%energy_state_ExchCoeffShSfc(noahmp_c)) + noahmp%forcing_SpecHumidityRefHeight(noahmp_c)
      noahmp%energy_state_SpecHumidity2mBare(noahmp_c) = noahmp%energy_state_SpecHumiditySfc(noahmp_c)
    endif
  end subroutine WaterMain
end module lean_watermainmod

! Source: physics_noahmp/src/BalanceErrorCheckMod.F90
module lean_balanceerrorcheckmod
 use lean_phys_fault, only: physics_fault
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  implicit none
  contains
  subroutine BalanceWaterInit(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: LoopInd
    noahmp%water_state_WaterStorageTotBeg(noahmp_c) = noahmp%water_state_CanopyLiqWater(noahmp_c) + noahmp%water_state_CanopyIce(noahmp_c) + noahmp%water_state_SnowWaterEquiv(noahmp_c) + noahmp%water_state_WaterStorageAquifer(noahmp_c)
    do LoopInd = 1, 4
      noahmp%water_state_WaterStorageTotBeg(noahmp_c) = noahmp%water_state_WaterStorageTotBeg(noahmp_c) + noahmp%water_state_SoilMoisture(LoopInd, noahmp_c) * noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c) * 1000.0
    enddo
  end subroutine BalanceWaterInit
  subroutine BalanceWaterCheck(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    integer :: LoopInd
    if ( (noahmp%config_domain_FlagCropland(noahmp_c) .eqv. .true.) .and. (noahmp%water_state_IrrigationFracGrid(noahmp_c) >= noahmp%water_param_IrriFracThreshold(noahmp_c)) ) then
      noahmp%water_flux_PrecipTotRefHeight(noahmp_c) = noahmp%water_flux_PrecipTotRefHeight(noahmp_c) + noahmp%water_flux_IrrigationRateSprinkler(noahmp_c) * 1000.0 / noahmp%config_domain_MainTimeStep(noahmp_c)
    endif
    noahmp%water_state_WaterStorageTotEnd(noahmp_c) = noahmp%water_state_CanopyLiqWater(noahmp_c) + noahmp%water_state_CanopyIce(noahmp_c) + noahmp%water_state_SnowWaterEquiv(noahmp_c) + noahmp%water_state_WaterStorageAquifer(noahmp_c)
    do LoopInd = 1, 4
      noahmp%water_state_WaterStorageTotEnd(noahmp_c) = noahmp%water_state_WaterStorageTotEnd(noahmp_c) + noahmp%water_state_SoilMoisture(LoopInd, noahmp_c) * noahmp%config_domain_ThicknessSnowSoilLayer(LoopInd, noahmp_c) * 1000.0
    enddo
    noahmp%water_flux_SfcWaterTotChgAcc(noahmp_c) = noahmp%water_flux_SfcWaterTotChgAcc(noahmp_c) + (noahmp%water_state_WaterStorageTotEnd(noahmp_c) - noahmp%water_state_WaterStorageTotBeg(noahmp_c))
    noahmp%water_flux_PrecipTotAcc(noahmp_c) = noahmp%water_flux_PrecipTotAcc(noahmp_c) + noahmp%water_flux_PrecipTotRefHeight(noahmp_c) * noahmp%config_domain_MainTimeStep(noahmp_c)
    noahmp%water_flux_EvapCanopyNetAcc(noahmp_c) = noahmp%water_flux_EvapCanopyNetAcc(noahmp_c) + noahmp%water_flux_EvapCanopyNet(noahmp_c) * noahmp%config_domain_MainTimeStep(noahmp_c)
    noahmp%water_flux_TranspirationAcc(noahmp_c) = noahmp%water_flux_TranspirationAcc(noahmp_c) + noahmp%water_flux_Transpiration(noahmp_c) * noahmp%config_domain_MainTimeStep(noahmp_c)
    noahmp%water_flux_EvapGroundNetAcc(noahmp_c) = noahmp%water_flux_EvapGroundNetAcc(noahmp_c) + noahmp%water_flux_EvapGroundNet(noahmp_c) * noahmp%config_domain_MainTimeStep(noahmp_c)
    if ( noahmp%config_domain_FlagSoilProcess(noahmp_c) .eqv. .true. ) then
      noahmp%water_state_WaterBalanceError(noahmp_c) = noahmp%water_flux_SfcWaterTotChgAcc(noahmp_c) - (noahmp%water_flux_PrecipTotAcc(noahmp_c) + noahmp%water_flux_IrrigationRateMicro(noahmp_c)*1000.0 + noahmp%water_flux_IrrigationRateFlood(noahmp_c)*1000.0 - noahmp%water_flux_EvapCanopyNetAcc(noahmp_c) - noahmp%water_flux_TranspirationAcc(noahmp_c) - noahmp%water_flux_EvapGroundNetAcc(noahmp_c) - noahmp%water_flux_RunoffSurface(noahmp_c) - noahmp%water_flux_RunoffSubsurface(noahmp_c) - noahmp%water_flux_TileDrain(noahmp_c))
      if ( abs(noahmp%water_state_WaterBalanceError(noahmp_c)) > 0.1 ) then
        if ( noahmp%water_state_WaterBalanceError(noahmp_c) > 0 ) then
        else
        endif
        call physics_fault(8)
      endif
    endif
  end subroutine BalanceWaterCheck
  subroutine BalanceEnergyCheck(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    noahmp%energy_state_RadSwBalanceError(noahmp_c) = noahmp%forcing_RadSwDownRefHeight(noahmp_c) - (noahmp%energy_flux_RadSwAbsSfc(noahmp_c) + noahmp%energy_flux_RadSwReflSfc(noahmp_c))
    if ( abs(noahmp%energy_state_RadSwBalanceError(noahmp_c)) > 0.01 ) then
      call physics_fault(9)
    endif
    noahmp%energy_state_EnergyBalanceError(noahmp_c) = noahmp%energy_flux_RadSwAbsVeg(noahmp_c) + noahmp%energy_flux_RadSwAbsGrd(noahmp_c) + noahmp%energy_flux_HeatPrecipAdvSfc(noahmp_c) - (noahmp%energy_flux_RadLwNetSfc(noahmp_c) + noahmp%energy_flux_HeatSensibleSfc(noahmp_c) + noahmp%energy_flux_HeatLatentCanopy(noahmp_c) + noahmp%energy_flux_HeatLatentGrd(noahmp_c) + noahmp%energy_flux_HeatLatentTransp(noahmp_c) + noahmp%energy_flux_HeatGroundTot(noahmp_c) + noahmp%energy_flux_HeatLatentIrriEvap(noahmp_c) + noahmp%energy_flux_HeatCanStorageChg(noahmp_c))
    if ( abs(noahmp%energy_state_EnergyBalanceError(noahmp_c)) > 0.01 ) then
      call physics_fault(10)
    endif
  end subroutine BalanceEnergyCheck
end module lean_balanceerrorcheckmod

! Source: physics_noahmp/src/NoahmpMainMod.F90
module lean_noahmpmainmod
  use Machine
  use noahmp_state
  use lean_constantdefinemod
  use lean_atmosforcingmod, only : ProcessAtmosForcing
  use lean_generalinitmod, only : GeneralInit
  use lean_phenologymainmod, only : PhenologyMain
  use lean_irrigationpreparemod, only : IrrigationPrepare
  use lean_irrigationsprinklermod, only : IrrigationSprinkler
  use lean_canopywaterinterceptmod, only : CanopyWaterIntercept
  use lean_precipitationheatadvectmod, only : PrecipitationHeatAdvect
  use lean_energymainmod, only : EnergyMain
  use lean_watermainmod, only : WaterMain
  use lean_balanceerrorcheckmod, only : BalanceWaterInit, BalanceWaterCheck, BalanceEnergyCheck
  implicit none
  contains
  subroutine NoahmpMain(noahmp, noahmp_c)
 !$acc routine seq
    implicit none
    type(noahmp_state_type), intent(inout) :: noahmp
    integer, intent(in) :: noahmp_c
    call ProcessAtmosForcing(noahmp, noahmp_c)
    call GeneralInit(noahmp, noahmp_c)
    call BalanceWaterInit(noahmp, noahmp_c)
    call PhenologyMain(noahmp, noahmp_c)
    call IrrigationPrepare(noahmp, noahmp_c)
    if ( (noahmp%config_domain_FlagCropland(noahmp_c) .eqv. .true.) .and. (noahmp%water_state_IrrigationAmtSprinkler(noahmp_c) > 0.0) ) call IrrigationSprinkler(noahmp, noahmp_c)
    call CanopyWaterIntercept(noahmp, noahmp_c)
    call PrecipitationHeatAdvect(noahmp, noahmp_c)
    call EnergyMain(noahmp, noahmp_c)
    call WaterMain(noahmp, noahmp_c)
    call BalanceWaterCheck(noahmp, noahmp_c)
    call BalanceEnergyCheck(noahmp, noahmp_c)
  end subroutine NoahmpMain
end module lean_noahmpmainmod
